	// stage 17: in hyperspace by the Cone's star. On to the Crystal Planet (192,152 planet 1) and into orbit with the Crystal Orb aboard: its field does no harm,
	// and the Crystal Cone finds the control nexus
	IEnumerator ScenarioPlaythrough17()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var ship = playerData.m_playerShip;
		var done = new bool[ 1 ];
		var crystalPlanet = 33;
		var crystalStar = gameData.m_planetList[ crystalPlanet ].m_starId;

		ProbeKeyboard();

		Log( "playthrough-17: loaded: location " + playerData.m_general.m_location + ", fuel " + Endurium() + ", armor " + ship.m_armorPoints + ", hold " + PtShipHold() );

		Check( "playthrough-17: the save of stage 16 is in hyperspace with the Orb, the egg and the Cone", ( playerData.m_general.m_location == PD_General.Location.Hyperspace ) && ship.HasArtifact( "Crystal Cone" ), playerData.m_general.m_location + ", " + PtShipHold() );

		yield return PtHyperspaceTo( crystalStar, 2.0f, done );

		Check( "playthrough-17: hyperspace travel reaches the Crystal Planet's star", done[ 0 ], playerData.m_general.m_location + " star " + playerData.m_general.m_currentStarId );

		if ( !done[ 0 ] )
		{
			PlaythroughSave( "no crystal star" );
			Finish( "scenario=playthrough-17 abort: the Crystal Planet's star was not reached", 2 );
			yield break;
		}

		yield return PtFlyToPlanetAndEnter( crystalPlanet, PD_General.Location.InOrbit, done );

		if ( playerData.m_general.m_location == PD_General.Location.Encounter )
		{
			yield return PtMeetEncounter();
			yield return PtFlyToPlanetAndEnter( crystalPlanet, PD_General.Location.InOrbit, done );
		}

		var orbitMessages = PtMessages();

		Check( "playthrough-17: into orbit around the Crystal Planet", done[ 0 ] && ( playerData.m_general.m_currentPlanetId == crystalPlanet ), playerData.m_general.m_location + " " + playerData.m_general.m_currentPlanetId );
		Check( "playthrough-17: in orbit the Crystal Cone reports the control nexus at 47N x 45E", orbitMessages.Contains( "47" ) && orbitMessages.Contains( "45" ), orbitMessages );

		// a few seconds in orbit with the shields down: the Crystal Orb keeps the field off
		var armorBefore = ship.m_armorPoints;
		var shieldsUp = ship.m_shieldsAreUp;
		var end = Time.realtimeSinceStartup + 4.0f;

		while ( ( Time.realtimeSinceStartup < end ) && ( playerData.m_general.m_location == PD_General.Location.InOrbit ) )
		{
			yield return null;
		}

		Log( "playthrough-17: in orbit around the Crystal Planet: armor " + armorBefore + " -> " + ship.m_armorPoints + " in 4 s (shields up " + shieldsUp + "), messages '" + PtMessages() + "'" );

		Check( "playthrough-17: with the Crystal Orb aboard the Crystal Planet's field does no damage", ship.m_armorPoints >= armorBefore, armorBefore + " -> " + ship.m_armorPoints );

		// the science officer: sensors and analysis of the Crystal Planet
		yield return PtOfficer( "Science" );
		yield return PtPress( "Sensors" );

		var sensors = SpaceflightController.m_instance.m_displayController.m_sensorsDisplay;
		var scanEnd = Time.realtimeSinceStartup + 25.0f;

		while ( ( Time.realtimeSinceStartup < scanEnd ) && !sensors.m_hasSensorData )
		{
			yield return null;
		}

		if ( PtButtonRunning() )
		{
			yield return Tap( Key.Enter );
			yield return Frames( 5 );
		}

		SpaceflightController.m_instance.m_messages.Clear();

		yield return PtPress( "Analysis" );
		yield return Frames( 5 );

		Log( "playthrough-17: the analysis of the Crystal Planet: '" + PtMessages() + "'" );

		PlaythroughSave( "location=" + playerData.m_general.m_location + " planet=" + playerData.m_general.m_currentPlanetId + " fuel=" + Endurium() + " armor=" + ship.m_armorPoints );

		Finish( "scenario=playthrough-17 checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// stage 18: in orbit around the Crystal Planet. Land at the control nexus (47N x 45E: the Cone reports it on Land too), go out (the terrain vehicle takes the
	// Black Egg), drive to the nexus by the vehicle's coordinates, drop the egg with the cargo list, and back into the ship
	IEnumerator ScenarioPlaythrough18()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var controller = SpaceflightController.m_instance;
		var done = new bool[ 1 ];
		var driven = new float[ 1 ];
		var eggId = gameData.FindArtifactId( "Black Egg" );

		ProbeKeyboard();

		Log( "playthrough-18: loaded: location " + playerData.m_general.m_location + " planet " + playerData.m_general.m_currentPlanetId + ", hold " + PtShipHold() + ", armor " + playerData.m_playerShip.m_armorPoints );

		Check( "playthrough-18: the save of stage 17 is in orbit around the Crystal Planet", ( playerData.m_general.m_location == PD_General.Location.InOrbit ) && ( playerData.m_general.m_currentPlanetId == 33 ), playerData.m_general.m_location + " " + playerData.m_general.m_currentPlanetId );

		yield return PtWaitForPlanets( 30.0f );

		// Land: the Cone reports the nexus with the landing map
		controller.m_messages.Clear();

		yield return PtOfficer( "Command" );
		yield return PtPress( "Land" );

		var landSaid = PtMessages();

		Check( "playthrough-18: Land with the Crystal Cone aboard reports the control nexus", landSaid.Contains( "47N x 45E" ), landSaid );

		// back out of the landing menu with Abort, and land through the usual steps
		yield return PtPress( "Abort" );
		yield return PtLand( BlackEgg.c_nexusLongitude, BlackEgg.c_nexusLatitude, done );

		Check( "playthrough-18: the ship lands at the control nexus", done[ 0 ], playerData.m_general.m_location.ToString() );

		if ( !done[ 0 ] )
		{
			PlaythroughSave( "no landing at the nexus" );
			Finish( "scenario=playthrough-18 abort: no landing", 2 );
			yield break;
		}

		yield return PtDisembark( done );

		var vehicleHasEgg = ArtifactsHeld( playerData.m_terrainVehicle.m_artifactStorage, eggId ) > 0;

		Check( "playthrough-18: the terrain vehicle takes the Black Egg out of the ship's hold", done[ 0 ] && vehicleHasEgg, PtVehicleHold() );

		// to the nexus by the vehicle's own coordinates
		var nexus = Tools.LatLongToWorldCoordinates( BlackEgg.c_nexusLongitude, BlackEgg.c_nexusLatitude );
		var vehicle = controller.m_terrainVehicle;

		if ( !( GetField( controller.m_buttonController, "m_currentButton" ) is MoveButton ) )
		{
			yield return PtPress( "Move" );
		}

		yield return PtDrive( () => nexus, 3.0f, 15.0f, driven );
		yield return Tap( Key.Enter );
		yield return Frames( 10 );

		float east, north;

		Tools.WorldToLatLongCoordinates( playerData.m_general.m_lastDisembarkedCoordinates, out east, out north );

		var bar = FieldOrNull( controller.m_viewport, "m_label" ) as TMPro.TMP_Text;

		Log( "playthrough-18: drove " + driven[ 0 ].ToString( "F0" ) + " to the nexus: the vehicle at " + north.ToString( "F2" ) + "N " + east.ToString( "F2" ) + "E, the coordinates above the main view '" + ( ( bar == null ) ? "-" : bar.text ) + "'" );

		// Cargo with nothing beside the vehicle lists its cargo; Drop drops the marked item (the egg is the only one)
		controller.m_messages.Clear();

		var listSaid = "";

		// the nexus has a ruin with a message: the first Cargo records it, the next lists the cargo
		for ( var press = 0; ( press < 3 ) && ( PtIndexOf( "Drop" ) < 0 ); press++ )
		{
			controller.m_messages.Clear();

			yield return PtPress( "Cargo" );
			yield return Frames( 5 );

			listSaid += "[" + press + "] " + Head( PtMessages() ) + " ";
		}

		var listSet = PtLabels();
		var dropSaid = "";

		if ( PtIndexOf( "Drop" ) >= 0 )
		{
			var items = TVCargoButton.BuildCargoItems();
			var eggIndex = items.FindIndex( item => item.m_artifactId == eggId );

			for ( var i = 0; i < eggIndex; i++ )
			{
				yield return PtPress( "Next" );
			}

			controller.m_messages.Clear();

			yield return PtPress( "Drop" );
			yield return Frames( 5 );

			// the original asks "ARM THIS DEVICE?" on the drop (ITEMS-OV WE9AA, roadmap 8.31): Yes
			if ( PtIndexOf( "Yes" ) >= 0 )
			{
				yield return PtPress( "Yes" );
				yield return Frames( 5 );
			}

			dropSaid = PtMessages();

			if ( PtIndexOf( "Back" ) >= 0 )
			{
				yield return PtPress( "Back" );
			}
		}

		var eggsAtTheNexus = 0;

		foreach ( var droppedCargo in playerData.m_planetSurfaces.m_droppedCargoList )
		{
			if ( ( droppedCargo.m_planetId == 33 ) && ( droppedCargo.m_artifactId == eggId ) && BlackEgg.IsAtTheNexus( droppedCargo ) )
			{
				eggsAtTheNexus++;
			}
		}

		Log( "playthrough-18: Cargo: '" + listSaid + "' (" + listSet + "), Drop: '" + dropSaid + "', eggs at the nexus " + eggsAtTheNexus + ", vehicle " + PtVehicleHold() );

		Check( "playthrough-18: the cargo list drops the Black Egg at the control nexus, and the messages say it is armed", ( eggsAtTheNexus == 1 ) && dropSaid.Contains( "armed" ), eggsAtTheNexus + " | " + dropSaid );

		yield return PtBackToTheShip( done );

		Check( "playthrough-18: back in the ship without the egg", done[ 0 ] && !playerData.m_playerShip.HasArtifact( "Black Egg" ), done[ 0 ] + ", " + PtShipHold() );

		PlaythroughSave( "location=" + playerData.m_general.m_location + " eggsAtTheNexus=" + eggsAtTheNexus );

		Finish( "scenario=playthrough-18 checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// stage 19: on the Crystal Planet with the egg armed at the nexus. Launch: back in orbit the egg counts down, BOOM, the Crystal Planet is destroyed and the
	// game is won (Interstel's message, the bonus waiting for the Starport); then out of the star system
	IEnumerator ScenarioPlaythrough19()
	{
		var playerData = DataController.m_instance.m_playerData;
		var general = playerData.m_general;
		var done = new bool[ 1 ];

		ProbeKeyboard();

		Log( "playthrough-19: loaded: location " + general.m_location + " planet " + general.m_currentPlanetId + ", won " + general.m_gameWon + ", dropped cargo " + playerData.m_planetSurfaces.m_droppedCargoList.Count );

		Check( "playthrough-19: the save of stage 18 is on the Crystal Planet, the game not won yet", ( general.m_location == PD_General.Location.Planetside ) && ( general.m_currentPlanetId == 33 ) && !general.m_gameWon, general.m_location + " " + general.m_currentPlanetId + " won " + general.m_gameWon );

		yield return PtWaitForPlanets( 30.0f );

		// the launch: the egg goes off once the ship is back in orbit
		var said = new List<string>();

		yield return PtOfficer( "Command" );
		yield return PtPress( "Launch" );
		yield return PtPress( "Yes" );

		var end = Time.realtimeSinceStartup + 60.0f;

		while ( ( Time.realtimeSinceStartup < end ) && !general.m_gameWon )
		{
			foreach ( var message in general.m_messageList )
			{
				var text = System.Text.RegularExpressions.Regex.Replace( message, "<[^>]*>", "" ).Replace( "\n", " / " );

				if ( !said.Contains( text ) )
				{
					said.Add( text );
				}
			}

			yield return null;
		}

		yield return new WaitForSecondsRealtime( 2.0f );

		foreach ( var message in general.m_messageList )
		{
			var text = System.Text.RegularExpressions.Regex.Replace( message, "<[^>]*>", "" ).Replace( "\n", " / " );

			if ( !said.Contains( text ) )
			{
				said.Add( text );
			}
		}

		var all = string.Join( " || ", said );
		var destroyed = StarSystem.IsPlanetDestroyed( 33 );

		Log( "playthrough-19: after the launch: location " + general.m_location + ", won " + general.m_gameWon + ", bonus pending " + general.m_winBonusPending + ", Crystal Planet destroyed " + destroyed + ", said: " + all );

		Check( "playthrough-19: back in orbit the egg counts down and goes BOOM", all.Contains( "COUNTDOWN TRANSMISSION FROM THE BLACK EGG" ) && all.Contains( "BOOM!" ), Head( all ) );
		var lastRow = ( playerData.m_bank.m_transactionList.Count > 0 ) ? playerData.m_bank.m_transactionList[ playerData.m_bank.m_transactionList.Count - 1 ] : null;
		var lastRowText = ( lastRow == null ) ? "no ledger" : lastRow.m_description + " " + lastRow.m_amount;

		Check( "playthrough-19: the Crystal Planet is destroyed and the game is won, and Interstel pays its bonus at once", destroyed && general.m_gameWon && !general.m_winBonusPending && ( lastRowText == "Bonus 500000+" ), destroyed + ", " + general.m_gameWon + ", " + general.m_winBonusPending + ", " + lastRowText );
		Check( "playthrough-19: Interstel's message of the win", all.Contains( "INTERSTEL MEDAL OF SUBLIME ACHIEVEMENT" ), Tail( all ) );

		var settle = Time.realtimeSinceStartup + 6.0f;

		while ( ( Time.realtimeSinceStartup < settle ) && ( general.m_location != PD_General.Location.StarSystem ) )
		{
			yield return null;
		}

		yield return Frames( 10 );

		Log( "playthrough-19: after the explosion: " + general.m_location + ", console " + PtLabels() + ", running " + PtButtonRunning() + ", messages '" + PtMessages() + "'" );

		Check( "playthrough-19: after the explosion the ship is in the star system", general.m_location == PD_General.Location.StarSystem, general.m_location.ToString() );

		if ( general.m_location == PD_General.Location.StarSystem )
		{
			yield return PtLeaveSystem( done );
		}

		PlaythroughSave( "location=" + general.m_location + " won=" + general.m_gameWon + " fuel=" + Endurium() );

		Finish( "scenario=playthrough-19 checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// stage 20: in hyperspace by the Crystal Planet's star after the win. Home to Arth: hyperspace to its star (or, with the hold out of fuel, a distress call and
	// Interstel's tow), the docking bay, and into the Starport
	IEnumerator ScenarioPlaythrough20()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var general = playerData.m_general;
		var bank = playerData.m_bank;
		var done = new bool[ 1 ];
		var balanceBefore = bank.m_currentBalance;
		var ledgerBefore = bank.m_transactionList.Count;
		var towed = false;

		ProbeKeyboard();

		Log( "playthrough-20: loaded: location " + general.m_location + ", won " + general.m_gameWon + ", bonus pending " + general.m_winBonusPending + ", fuel " + Endurium() + ", balance " + balanceBefore + ", stardate " + general.m_currentStardateYMD );

		Check( "playthrough-20: the save of stage 19 keeps the win, with the bonus paid", general.m_gameWon && !general.m_winBonusPending, general.m_gameWon + ", " + general.m_winBonusPending );

		yield return PtHyperspaceTo( gameData.m_misc.m_arthStarId, 2.0f, done );

		if ( !done[ 0 ] && ( general.m_location == PD_General.Location.Hyperspace ) )
		{
			// out of fuel short of Arth: the distress call
			Log( "playthrough-20: short of Arth with " + Endurium() + " tenths of fuel at " + Tools.WorldToGameCoordinates( general.m_coordinates ) + ": a distress call" );

			yield return PtOfficer( "Communications" );
			yield return PtPress( "Distress" );

			var asked = PtMessages();

			yield return PtPress( "Yes" );
			yield return Frames( 30 );

			towed = general.m_location == PD_General.Location.DockingBay;

			Log( "playthrough-20: Distress asked '" + asked + "'; then " + general.m_location + ", messages '" + PtMessages() + "'" );

			Check( "playthrough-20: the distress call has Interstel tow the ship to the Starport", towed, general.m_location.ToString() );
		}
		else if ( done[ 0 ] )
		{
			yield return PtFlyToPlanetAndEnter( gameData.m_misc.m_arthPlanetId, PD_General.Location.DockingBay, done );

			Check( "playthrough-20: home at Arth the ship docks at the Starport", done[ 0 ], general.m_location + ": " + PtMessages() );

			var dockEnd = Time.realtimeSinceStartup + 30.0f;

			while ( ( Time.realtimeSinceStartup < dockEnd ) && SpaceflightController.m_instance.m_playerCamera.IsLaunchingOrLanding() )
			{
				yield return null;
			}

			yield return Frames( 10 );
		}

		var bonus = bank.m_currentBalance - balanceBefore;
		var newRows = "";

		for ( var i = ledgerBefore; i < bank.m_transactionList.Count; i++ )
		{
			newRows += bank.m_transactionList[ i ].m_stardate + " " + bank.m_transactionList[ i ].m_description + " " + bank.m_transactionList[ i ].m_amount + "; ";
		}

		Log( "playthrough-20: in the docking bay (towed " + towed + "): balance " + balanceBefore + " -> " + bank.m_currentBalance + " (" + bonus + "), bonus pending " + general.m_winBonusPending + ", new ledger rows " + newRows + "messages '" + PtMessages() + "'" );

		Check( "playthrough-20: docking at the Starport after the win pays no second bonus", !general.m_winBonusPending && !newRows.Contains( "Bonus" ), bonus + ", " + newRows );

		// into the Starport
		if ( general.m_location == PD_General.Location.DockingBay )
		{
			yield return PtOfficer( "Command" );
			yield return PtPress( "Disembark" );
			yield return PtWaitForScene( "Starport", 20.0f );
			yield return Frames( 60 );
		}

		Check( "playthrough-20: into the Starport", ( SceneManager.GetActiveScene().name == "Starport" ) && ( DataController.m_instance.m_playerData.m_general.m_location == PD_General.Location.Starport ), SceneManager.GetActiveScene().name + " " + DataController.m_instance.m_playerData.m_general.m_location );

		PlaythroughSave( "location=" + DataController.m_instance.m_playerData.m_general.m_location + " balance=" + DataController.m_instance.m_playerData.m_bank.m_currentBalance + " towed=" + towed );

		Finish( "scenario=playthrough-20 checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// stage 21: at the Starport after the win. Operations: Interstel's supplemental evaluation on the completion of the mission (and any towing charges), its pages
	// with More; the Bank's ledger with the bonus; the docking bay still lets the ship out (the game goes on after the win)
	IEnumerator ScenarioPlaythrough21()
	{
		var playerData = DataController.m_instance.m_playerData;
		var general = playerData.m_general;
		var bank = playerData.m_bank;

		ProbeKeyboard();

		Log( "playthrough-21: loaded at the Starport: location " + general.m_location + ", won " + general.m_gameWon + ", balance " + bank.m_currentBalance + ", unread evaluation " + general.HasUnreadEvaluation() + ", supplemental evaluations " + general.m_supplementalEvaluationList.Count );

		Check( "playthrough-21: the save of stage 20 is at the Starport with the win", ( general.m_location == PD_General.Location.Starport ) && general.m_gameWon, general.m_location + " " + general.m_gameWon );

		// the evaluation of the win waits unread, but does not keep the ship docked: the original's preflight check (CHKFLIGHT-OV WF40A) does not look at the
		// win's WMSG (the docking bay is not opened here, since a passing check starts the transporter)
		var dockingBay = FindPanel<DockingBayPanel>();
		var missionCompleteUnread = !general.m_missionCompleteShown;
		var keptDocked = general.HasUnreadEvaluation();

		Log( "playthrough-21: before the evaluation: the completion of the mission unread " + missionCompleteUnread + ", an evaluation keeps the ship docked " + keptDocked );

		Check( "playthrough-21: the evaluation of the win waits unread and does not keep the ship docked, as the original's", missionCompleteUnread && !keptDocked, missionCompleteUnread + ", " + keptDocked );

		// Operations: the evaluation's pages
		var operations = FindPanel<OperationsPanel>();
		var balanceBefore = bank.m_currentBalance;

		yield return OpenPanel( operations, "operations" );

		PanelCall( "EvaluationClicked", () => operations.EvaluationClicked() );

		yield return Frames( 3 );

		var pages = new List<string>();

		for ( var page = 0; page < 6; page++ )
		{
			var text = "";

			foreach ( var tmp in operations.m_evaluationGameObject.GetComponentsInChildren<TMPro.TextMeshProUGUI>() )
			{
				text += PtText( tmp ) + " ";
			}

			pages.Add( text.Trim() );

			if ( !operations.m_moreButton.gameObject.activeInHierarchy )
			{
				break;
			}

			PanelCall( "MoreClicked", () => operations.MoreClicked() );

			yield return Frames( 3 );
		}

		PanelCall( "QuitClicked", () => operations.QuitClicked() );

		yield return ClosePanel( operations, "operations" );

		var all = string.Join( " ## ", pages );

		Log( "playthrough-21: the evaluation, " + pages.Count + " pages: " + all + " | balance " + balanceBefore + " -> " + bank.m_currentBalance );

		Check( "playthrough-21: Interstel's evaluation says the mission is complete", all.ToUpperInvariant().Contains( "MISSION" ) && ( all.ToUpperInvariant().Contains( "COMPLET" ) || all.ToUpperInvariant().Contains( "CRYSTAL" ) ), Head( all ) );

		// the Bank: the bonus in the ledger
		var bankPanel = FindPanel<BankPanel>();

		yield return OpenPanel( bankPanel, "bank" );

		var ledger = "";

		foreach ( var transaction in bank.m_transactionList )
		{
			ledger += transaction.m_stardate + " " + transaction.m_description + " " + transaction.m_amount + "; ";
		}

		var balanceText = PtText( FieldOrNull( bankPanel, "m_currentBalanceText" ) as TMPro.TMP_Text );

		yield return ClosePanel( bankPanel, "bank" );

		Log( "playthrough-21: the bank: '" + balanceText + "', ledger " + ledger );

		Check( "playthrough-21: the ledger has the 500,000 MU bonus", ledger.Contains( "Bonus 500000+" ), ledger );

		// fuel for the next flight if the hold has none (a ship towed home has burnt it all)
		if ( Endurium() < 100 )
		{
			var depot = FindPanel<TradeDepotPanel>();
			var change = new int[ 1 ];

			yield return OpenPanel( depot, "trade depot" );
			yield return PtDepotTrade( depot, true, 5, "20", change );
			yield return ClosePanel( depot, "trade depot" );

			Log( "playthrough-21: bought 20 cubic meters of fuel for " + ( -change[ 0 ] ) + ", fuel now " + Endurium() );
		}

		// the game goes on after the win: the docking bay lets the ship out
		yield return OpenPanel( dockingBay, "docking bay" );

		var transporting = dockingBay.IsTransporting();
		var after = PreflightText( dockingBay );

		Check( "playthrough-21: after the evaluation the preflight check passes again", transporting, after );

		yield return PtWaitForScene( "Spaceflight", 20.0f );
		yield return Frames( 60 );

		Log( "playthrough-21: the end: location " + DataController.m_instance.m_playerData.m_general.m_location + ", balance " + DataController.m_instance.m_playerData.m_bank.m_currentBalance + ", stardate " + DataController.m_instance.m_playerData.m_general.m_currentStardateYMD + ", encounters " + string.Join( " ## ", s_ptEncounters ) );

		PlaythroughSave( "the end: location=" + DataController.m_instance.m_playerData.m_general.m_location + " balance=" + DataController.m_instance.m_playerData.m_bank.m_currentBalance );

		Finish( "scenario=playthrough-21 checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// aliens that fight do not talk, as the original's (COMM-OV <TALK>: a fight leaves no chance to talk): fired on, they do not answer a hail, and a comm link that is
	// up when the player fires ends; aliens that have turned cowardly still talk
	IEnumerator ScenarioFiredOnSilent()
	{
		var playerData = DataController.m_instance.m_playerData;
		var encounter = SpaceflightController.m_instance.m_encounter;

		EnsureCrew();

		// an officer who understands every word, and a ship that survives the fight
		playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.CommunicationsOfficer ).m_communications = 250;
		playerData.m_playerShip.m_armorPoints = 100000;

		// three Spemin ships at once, in a star system
		var encounterId = FindEncounter( 1, 6, 3, 0 );
		var said = new List<string>();

		// ---- 1. fired on, then hailed: no answer, and no comm link
		EnterEncounter( encounterId );
		yield return Frames( 10 );

		// (the scan's message is not the aliens talking)
		encounter.m_pdEncounter.m_alreadyScanned = true;

		encounter.PlayerAttacked();
		playerData.m_playerShip.RestoreSystems();
		encounter.Hail( GD_Comm.Stance.Friendly, false );

		yield return LetAliensSpeak( 3, said );

		var firedOnConnected = encounter.IsConnected();
		var firedOnSaid = string.Join( " | ", said ).Trim( ' ', '|' );

		ClearMissiles();
		LeaveEncounter();
		yield return Frames( 10 );

		// ---- 2. hailed without a shot (the link comes up), then fired on: the aliens end the link
		EnterEncounter( encounterId );
		yield return Frames( 10 );

		encounter.Hail( GD_Comm.Stance.Friendly, false );

		said.Clear();

		yield return LetAliensSpeak( 2, said );

		var linkedBeforeShot = encounter.IsConnected();

		encounter.PlayerAttacked();

		yield return Frames( 5 );

		var linkedAfterShot = encounter.IsConnected();

		ClearMissiles();
		LeaveEncounter();
		yield return Frames( 10 );

		// ---- 3. the control: two of the three destroyed, the last turns cowardly, and a hail is answered
		EnterEncounter( encounterId );
		yield return Frames( 10 );

		encounter.PlayerAttacked();

		Kill( FirstLivingAlien() );
		Kill( FirstLivingAlien() );

		yield return Frames( 3 );

		playerData.m_playerShip.RestoreSystems();
		encounter.Hail( GD_Comm.Stance.Friendly, false );

		said.Clear();

		yield return LetAliensSpeak( 1, said );

		var cowardlyConnected = encounter.IsConnected();
		var cowardlySaid = string.Join( " | ", said ).Trim( ' ', '|' );
		var cowardly = encounter.m_pdEncounter.m_aliensAreCowardly;

		ClearMissiles();
		LeaveEncounter();
		yield return Frames( 10 );

		Log( "firedonsilent: encounter " + encounterId + "; fired on and hailed: connected " + firedOnConnected + ", said '" + firedOnSaid + "'; linked before the shot " + linkedBeforeShot + ", after it " + linkedAfterShot + "; cowardly " + cowardly + ", connected " + cowardlyConnected + ", said '" + cowardlySaid + "'" );

		Check( "firedonsilent: aliens that have been fired on do not answer a hail (no comm link, nothing received from them)", !firedOnConnected && !firedOnSaid.Contains( "Receiving:" ), firedOnConnected + " '" + firedOnSaid + "'" );
		Check( "firedonsilent: a comm link that is up when the player fires ends (the setup: it was up)", linkedBeforeShot && !linkedAfterShot, linkedBeforeShot + " -> " + linkedAfterShot );
		Check( "firedonsilent: aliens that have turned cowardly still answer a hail (control)", cowardly && cowardlyConnected && ( cowardlySaid.Length > 0 ), cowardly + " " + cowardlyConnected + " '" + cowardlySaid + "'" );

		Finish( "scenario=firedonsilent checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// after an encounter in flight ends, no encounter begins for a minute, as the original's (HYPERMSG-OV WF022: ENC-TIME is the time plus 60000 ms, except in
	// orbit; HYPER-OV >ENCOUNTER begins one only when TIME is past it)
	IEnumerator ScenarioEncounterGrace()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var encounter = controller.m_encounter;

		EnsureCrew();

		playerData.m_playerShip.m_armorPoints = 100000;

		// a star system encounter of the Spemin, in its star system
		var encounterId = -1;

		for ( var atOnce = 1; ( atOnce <= 8 ) && ( encounterId < 0 ); atOnce++ )
		{
			encounterId = FindEncounter( 1, 1, atOnce, 0 );
		}

		if ( encounterId < 0 )
		{
			Finish( "scenario=encountergrace abort: no star system encounter of the Spemin", 2 );
			yield break;
		}

		EnterStarSystem( playerData.FindEncounter( encounterId ).GetStarId() );

		var start = Time.realtimeSinceStartup;

		while ( controller.m_starSystem.GeneratingPlanets() && ( Time.realtimeSinceStartup - start < 40.0f ) )
		{
			yield return null;
		}

		yield return Frames( 10 );

		EnterEncounter( encounterId );

		yield return Frames( 10 );

		// out of it the way the game leaves every encounter (the Crystal Pearl's warp goes through Encounter.LeaveEncounter)
		encounter.WarpOut();

		yield return Frames( 5 );

		var locationAfterLeaving = playerData.m_general.m_location;

		// the same aliens right beside the ship, for half a second
		var pdEncounter = playerData.FindEncounter( encounterId );

		pdEncounter.m_currentCoordinates = playerData.m_general.m_coordinates;

		yield return Frames( 30 );

		var locationDuringGrace = playerData.m_general.m_location;

		// the control: with the minute over (set here rather than waited for), they meet the ship again
		var resumeTime = typeof( SpaceflightController ).GetField( "m_encountersResumeTime", BindingFlags.NonPublic | BindingFlags.Instance );

		if ( resumeTime != null )
		{
			resumeTime.SetValue( controller, 0.0f );
		}

		pdEncounter.m_currentCoordinates = playerData.m_general.m_coordinates;

		yield return Frames( 30 );

		var locationAfterGrace = playerData.m_general.m_location;

		Log( "encountergrace: encounter " + encounterId + "; after leaving " + locationAfterLeaving + ", the aliens beside the ship within the minute: " + locationDuringGrace + ", after it: " + locationAfterGrace );

		Check( "encountergrace: the encounter is left into the star system (the setup is the case)", locationAfterLeaving == PD_General.Location.StarSystem, locationAfterLeaving.ToString() );
		Check( "encountergrace: within a minute of leaving, the aliens beside the ship begin no encounter", locationDuringGrace == PD_General.Location.StarSystem, locationDuringGrace.ToString() );
		Check( "encountergrace: after the minute they do (control)", locationAfterGrace == PD_General.Location.Encounter, locationAfterGrace.ToString() );

		ClearMissiles();

		if ( playerData.m_general.m_location == PD_General.Location.Encounter )
		{
			LeaveEncounter();
		}

		yield return Frames( 10 );

		Finish( "scenario=encountergrace checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	static int EnduriumTenths()
	{
		var endurium = DataController.m_instance.m_playerData.m_playerShip.m_elementStorage.Find( 5 );

		return ( endurium == null ) ? 0 : endurium.m_volume;
	}

	// landing and launching as the original's (LAND-OV): each burns the gravity's share of Endurium (the gravity in hundredths of a G over 40, in tenths), a
	// launch without it is refused, a landing without it crashes, and once the gravity is analysed Land warns of a planet that would crush the hull
	IEnumerator ScenarioLandingGravity()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var controller = SpaceflightController.m_instance;

		EnsureCrew();

		// ---- 1. a launch from planet 90 (1.08 G: 2 tenths) with 1 tenth aboard is refused, and with 100 it burns 2
		var planet90Star = gameData.m_planetList[ 90 ].m_starId;

		yield return GoIntoOrbit( planet90Star, 90 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );

		SetEndurium( 1 );
		controller.m_messages.Clear();

		new LaunchYesButton().Execute();

		yield return Frames( 10 );

		var launchRefusedLocation = playerData.m_general.m_location;
		var launchRefusedText = MessageList();

		SetEndurium( 100 );

		new LaunchYesButton().Execute();

		var fuelAfterLaunch = EnduriumTenths();

		yield return WaitForLocation( PD_General.Location.InOrbit, 20.0f );
		yield return Frames( 10 );

		var launchedLocation = playerData.m_general.m_location;

		// ---- 2. a landing on planet 90 with 1 tenth aboard crashes, and the game is over
		SetEndurium( 1 );
		controller.m_messages.Clear();

		PressButton( ButtonController.ButtonSet.CommandB, 0 );

		yield return Frames( 5 );

		PressButton( ButtonController.ButtonSet.Land, 1 );

		var end = Time.realtimeSinceStartup + 60.0f;

		// until the touchdown: a safe landing, or the end of the game (the location is the surface from the start of the descent)
		while ( ( Time.realtimeSinceStartup < end ) && !CombatController.m_instance.PlayerIsDestroyed() && !MessageList().Contains( "Safe landing" ) )
		{
			yield return null;
		}

		yield return new WaitForSecondsRealtime( 1.0f );

		var crashed = CombatController.m_instance.PlayerIsDestroyed();
		var crashText = MessageList();

		Log( "landinggravity: planet 90 is " + gameData.m_planetList[ 90 ].m_gravity + " hundredths of a G; launch with 1 tenth: " + launchRefusedLocation + " '" + launchRefusedText + "'; with 100: " + fuelAfterLaunch + " left, then " + launchedLocation + "; landing with 1 tenth: destroyed " + crashed + " '" + crashText + "'" );

		Check( "landinggravity: a launch without the gravity's share of Endurium is refused (1 tenth on planet 90)", ( launchRefusedLocation == PD_General.Location.Planetside ) && launchRefusedText.Contains( "Insufficient fuel for re-launching" ), launchRefusedLocation + " '" + launchRefusedText + "'" );
		Check( "landinggravity: a launch from planet 90 burns 2 tenths of Endurium (108 hundredths of a G over 40)", ( fuelAfterLaunch == 98 ) && ( launchedLocation == PD_General.Location.InOrbit ), fuelAfterLaunch + ", " + launchedLocation );
		Check( "landinggravity: a landing without the fuel for it crashes, and the game is over", crashed && crashText.Contains( "crashed on planet" ), crashed + " '" + crashText + "'" );

		// ---- 3. the rules for every planet: what a landing burns, and the planets that crush a hull (more than 7.99 G, 194 of the 811)
		var crushing = -1;
		var heaviestFuel = -1;
		var crushes = typeof( PD_PlayerShip ).GetMethod( "GravityCrushesHull" );
		var landingFuel = typeof( PD_PlayerShip ).GetMethod( "GetLandingFuel" );

		if ( ( crushes != null ) && ( landingFuel != null ) )
		{
			crushing = 0;
			heaviestFuel = 0;

			foreach ( var planet in gameData.m_planetList )
			{
				if ( (bool) crushes.Invoke( null, new object[] { planet } ) )
				{
					crushing++;
				}

				heaviestFuel = Mathf.Max( heaviestFuel, (int) landingFuel.Invoke( null, new object[] { planet } ) );
			}
		}

		Log( "landinggravity: " + crushing + " planets crush a hull; the heaviest landing burns " + heaviestFuel + " tenths" );

		Check( "landinggravity: 194 planets crush a landing ship's hull, and the heaviest landing burns at most 32 tenths", ( crushing == 194 ) && ( heaviestFuel > 0 ) && ( heaviestFuel <= 32 ), crushing + ", " + heaviestFuel );

		Finish( "scenario=landinggravity checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// once the gravity has been analysed, Land warns of a landing the ship cannot make, and a second Land goes down anyway (LAND-OV ?LAND and WF45E)
	IEnumerator ScenarioLandingWarning()
	{
		var gameData = DataController.m_instance.m_gameData;
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;

		EnsureCrew();

		yield return GoIntoOrbit( gameData.m_planetList[ 90 ].m_starId, 90 );

		// 1 tenth of Endurium, and the science officer has analysed planet 90's gravity (1.08 G)
		SetEndurium( 1 );

		var analysed = typeof( SpaceflightController ).GetField( "m_gravityAnalysedPlanetId" );

		if ( analysed != null )
		{
			analysed.SetValue( controller, 90 );
		}

		controller.m_messages.Clear();

		PressButton( ButtonController.ButtonSet.CommandB, 0 );

		yield return Frames( 5 );

		var firstSet = buttonController.GetCurrentButtonSet();
		var firstText = MessageList();

		PressButton( ButtonController.ButtonSet.CommandB, 0 );

		yield return Frames( 5 );

		var secondSet = buttonController.GetCurrentButtonSet();

		Log( "landingwarning: first Land: " + firstSet + " '" + firstText + "'; second Land: " + secondSet );

		Check( "landingwarning: with the gravity analysed, the first Land warns of the fuel and stays in orbit", ( firstSet != ButtonController.ButtonSet.Land ) && firstText.Contains( "Insufficient fuel for safe landing" ), firstSet + " '" + firstText + "'" );
		Check( "landingwarning: a second Land goes on to the landing", secondSet == ButtonController.ButtonSet.Land, secondSet.ToString() );

		Finish( "scenario=landingwarning checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// flies in hyperspace with the engines on until the Endurium is down to the given tenths, or the seconds are up - returns the messages said meanwhile
	static IEnumerator FlyUntilEndurium( int tenths, float seconds, string[] said )
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;

		controller.m_messages.Clear();
		controller.m_playerShip.TurnOnEngines();

		var end = Time.realtimeSinceStartup + seconds;

		while ( ( Time.realtimeSinceStartup < end ) && ( Endurium() > tenths ) )
		{
			yield return null;
		}

		yield return Frames( 5 );

		controller.m_playerShip.TurnOffEngines();
		playerData.m_general.m_currentSpeed = 0.0f;

		said[ 0 ] = MessageList();
	}

	// the fuel warnings in hyperspace, as the original's (HYPER-OV (-ENDURIUM)): "Fuel supply low." at 150 steps' worth of Endurium (class 1 engines: 9.0 cubic
	// meters), "Fuel supply critical." at 75 (4.5) and "Out of fuel." at none
	IEnumerator ScenarioFuelWarnings()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var ship = playerData.m_playerShip;
		var low = new string[ 1 ];
		var critical = new string[ 1 ];
		var outOfFuel = new string[ 1 ];

		EnsureCrew();

		ship.m_enginesClass = 1;

		// out in hyperspace, in a corner of it, with no encounter able to begin
		controller.m_encounterRange = 0.0f;
		playerData.m_general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 4.0f, 0.0f, 4.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		SetEndurium( 92 );

		yield return FlyUntilEndurium( 89, 30.0f, low );

		SetEndurium( 47 );

		yield return FlyUntilEndurium( 44, 30.0f, critical );

		SetEndurium( 2 );

		yield return FlyUntilEndurium( 0, 30.0f, outOfFuel );

		Log( "fuelwarnings: from 9.2 to 8.9 cubic meters '" + low[ 0 ] + "'; from 4.7 to 4.4 '" + critical[ 0 ] + "'; from 0.2 to none '" + outOfFuel[ 0 ] + "'" );

		Check( "fuelwarnings: below 150 steps' worth of Endurium (9.0 cubic meters with class 1 engines) the ship says the fuel supply is low", low[ 0 ].Contains( "Fuel supply low." ), low[ 0 ] );
		Check( "fuelwarnings: below 75 steps' worth (4.5) it says the fuel supply is critical", critical[ 0 ].Contains( "Fuel supply critical." ), critical[ 0 ] );
		Check( "fuelwarnings: with none left it says it is out of fuel", outOfFuel[ 0 ].Contains( "Out of fuel." ), outOfFuel[ 0 ] );

		Finish( "scenario=fuelwarnings checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// an amount typed at the Trade Depot is cut to the most that can be traded, as the original's (TDEPOT-OV WEACC: the typed volume, ABS, ELEM-AM @ MIN): more
	// than the hold takes buys what the hold takes, and more than the hold has sells all of it
	IEnumerator ScenarioStarportTradeClamp()
	{
		var playerData = DataController.m_instance.m_playerData;
		var depot = FindPanel<TradeDepotPanel>();
		var ship = playerData.m_playerShip;

		// plenty of money, an empty hold with no cargo pods
		playerData.m_bank.m_currentBalance = 1000000;

		ship.m_elementStorage.m_elementList.Clear();
		ship.m_artifactStorage.m_artifactList.Clear();
		ship.m_numCargoPods = 0;
		ship.RecalculateVolume();
		ship.RecalculateVolumeUsed();

		var room = ship.GetRemainingVolume();

		// buy 5000 cubic meters of the first element on the list
		Call( depot, "SwitchToBuyItemState", true );

		yield return Frames( 2 );

		Call( depot, "SwitchToBuyAmountState" );

		yield return Frames( 2 );

		depot.m_amountInputField.text = "5000";

		Call( depot, "OnEndEdit" );

		yield return Frames( 2 );

		var bought = room - ship.GetRemainingVolume();
		var boughtState = GetField( depot, "m_currentState" ).ToString();

		Call( depot, "SwitchToMenuBarState" );

		yield return Frames( 2 );

		// sell 5000 cubic meters of it
		Call( depot, "SwitchToSellItemState", true );

		yield return Frames( 2 );

		Call( depot, "SwitchToSellAmountState" );

		yield return Frames( 2 );

		depot.m_amountInputField.text = "5000";

		Call( depot, "OnEndEdit" );

		yield return Frames( 2 );

		var left = room - ship.GetRemainingVolume();
		var soldState = GetField( depot, "m_currentState" ).ToString();

		Log( "starport-tradeclamp: room " + room + " tenths; 5000 cubic meters asked: " + bought + " tenths bought (" + boughtState + "); 5000 sold: " + left + " tenths left (" + soldState + ")" );

		Check( "starport-tradeclamp: buying more than the hold takes buys what it takes, as the original's", ( room > 0 ) && ( bought == room ), room + " room, " + bought + " bought, " + boughtState );
		Check( "starport-tradeclamp: selling more than the hold has sells all of it", ( bought > 0 ) && ( left == 0 ), left + " left, " + soldState );

		Finish( "scenario=starport-tradeclamp checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the aliens' weapons, as the original's (COMBAT-OV): a ship with a laser and a missile launcher fires both, and its missile flies to where the player's ship
	// was when it was launched (only the plasma bolt follows the ship, WE929), so a ship that has moved away is missed
	IEnumerator ScenarioAlienMissiles()
	{
		var gameData = DataController.m_instance.m_gameData;
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;

		EnsureCrew();

		playerData.m_playerShip.m_armorPoints = 100000;

		// a Spemin encounter, its first ship made a Spemin Warship (a class 2 laser and a class 1 missile launcher), 300 units from the player
		var encounterId = FindEncounter( 1, 6, 3, 0 );

		EnterEncounter( encounterId );

		yield return Frames( 10 );

		var alienShip = controller.m_encounter.m_pdEncounter.GetAlienShipList()[ FirstLivingAlien() ];
		var warship = gameData.m_vesselList[ 3 ];

		alienShip.m_vesselId = 3;
		alienShip.m_coordinates = playerData.m_general.m_coordinates + Vector3.right * 300.0f;

		controller.m_messages.Clear();

		CombatController.m_instance.AlienFiresAtPlayer( alienShip, warship );

		yield return Frames( 2 );

		var laserSaid = MessageList().Contains( "Laser class" );
		var missilesLaunched = MissilesInFlight();

		// the player's ship moves 600 units away at once
		var away = controller.m_playerShip.transform.position + Vector3.forward * 600.0f;

		controller.m_playerShip.transform.position = away;
		playerData.m_general.m_coordinates = away;

		var pointsBefore = playerData.m_playerShip.m_armorPoints + playerData.m_playerShip.m_shieldPoints;
		var end = Time.realtimeSinceStartup + 10.0f;

		while ( ( Time.realtimeSinceStartup < end ) && ( MissilesInFlight() > 0 ) )
		{
			yield return null;
		}

		yield return Frames( 5 );

		var pointsAfter = playerData.m_playerShip.m_armorPoints + playerData.m_playerShip.m_shieldPoints;
		var missileHit = MessageList().Contains( "Missile class" );

		// the control: fired again at a ship that stays where it is, the missile hits
		alienShip.m_coordinates = playerData.m_general.m_coordinates + Vector3.right * 300.0f;
		controller.m_messages.Clear();

		CombatController.m_instance.AlienFiresAtPlayer( alienShip, warship );

		end = Time.realtimeSinceStartup + 10.0f;

		yield return Frames( 2 );

		while ( ( Time.realtimeSinceStartup < end ) && ( MissilesInFlight() > 0 ) )
		{
			yield return null;
		}

		yield return Frames( 5 );

		var missileHitStill = MessageList().Contains( "Missile class" );

		ClearMissiles();
		LeaveEncounter();

		yield return Frames( 10 );

		Log( "alienmissiles: the warship fired: laser " + laserSaid + ", missiles in the air " + missilesLaunched + "; after the ship moved 600 units away the missile hit " + missileHit + ", armor and shields " + pointsBefore + " -> " + pointsAfter );

		Check( "alienmissiles: a ship with a laser and a missile launcher fires both", laserSaid && ( missilesLaunched >= 1 ), laserSaid + ", " + missilesLaunched );
		Check( "alienmissiles: a ship that stays where it is is hit by the missile (control)", missileHitStill, missileHitStill.ToString() );
		Check( "alienmissiles: its missile flies to where the ship was, and misses a ship that has moved away", ( missilesLaunched >= 1 ) && !missileHit && ( pointsAfter == pointsBefore ), missileHit + ", " + pointsBefore + " -> " + pointsAfter );

		Finish( "scenario=alienmissiles checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// what an alien ship's shields take of a hit, as the original's (DAMAGE-OV WF162): the whole hit if they have points left, are up and the fight is not in a
	// nebula, and nothing over goes on to the armor; otherwise the armor takes it all
	IEnumerator ScenarioAlienShieldHits()
	{
		var playerData = DataController.m_instance.m_playerData;
		var encounter = SpaceflightController.m_instance.m_encounter;
		var applyDamage = typeof( CombatController ).GetMethod( "ApplyDamageToAlien", System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Instance );
		var results = new string[ 2 ];
		var armorTaken = new int[ 2 ];
		var shieldsLeft = new int[ 2 ];
		var shieldsUp = new bool[ 2 ];
		var races = new GameData.Race[] { GameData.Race.Uhlek, GameData.Race.Spemin };

		EnsureCrew();

		playerData.m_playerShip.m_armorPoints = 100000;

		for ( var i = 0; i < races.Length; i++ )
		{
			var encounterId = FindEncounterOfRace( races[ i ] );

			EnterEncounter( encounterId );
			yield return Frames( 10 );

			// the first living ship, with 30 shield points and plenty of armor, takes a hit of 50
			var ships = encounter.m_pdEncounter.GetAlienShipList();
			var index = -1;

			for ( var s = 0; s < ships.Length; s++ )
			{
				if ( ships[ s ].m_addedToEncounter && !ships[ s ].m_isDead )
				{
					index = s;
					break;
				}
			}

			if ( index < 0 )
			{
				results[ i ] = "no living ship in encounter " + encounterId;
				continue;
			}

			ships[ index ].EnsureHitPoints( DataController.m_instance.m_gameData.m_vesselList[ ships[ index ].m_vesselId ] );
			ships[ index ].m_shieldPoints = 30;
			ships[ index ].m_armorPoints = 500;

			shieldsUp[ i ] = encounter.AliensHaveShieldsUp();

			applyDamage.Invoke( CombatController.m_instance, new object[] { index, 50 } );

			armorTaken[ i ] = 500 - ships[ index ].m_armorPoints;
			shieldsLeft[ i ] = ships[ index ].m_shieldPoints;
			results[ i ] = races[ i ] + " (encounter " + encounterId + "): shields up " + shieldsUp[ i ] + ", shields 30 -> " + shieldsLeft[ i ] + ", armor took " + armorTaken[ i ];

			ClearMissiles();
			LeaveEncounter();
			yield return Frames( 10 );
		}

		Log( "alienshieldhits: " + results[ 0 ] + " | " + results[ 1 ] );

		Check( "alienshieldhits: an Uhlek ship's raised shields take the whole hit of 50 with 30 points left, and nothing goes on to the armor", shieldsUp[ 0 ] && ( shieldsLeft[ 0 ] == 0 ) && ( armorTaken[ 0 ] == 0 ), results[ 0 ] );
		Check( "alienshieldhits: the Spemin never raise their shields, so the armor takes the whole hit and the shields keep their points", !shieldsUp[ 1 ] && ( shieldsLeft[ 1 ] == 30 ) && ( armorTaken[ 1 ] == 50 ), results[ 1 ] );

		Finish( "scenario=alienshieldhits checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the game clock's rate, as the original's kernel keeps it (?NEW-HO: a star hour every REAL-MS, 10,000 ms of play): 30 game minutes in 5 seconds of flight
	IEnumerator ScenarioClockRate()
	{
		var general = DataController.m_instance.m_playerData.m_general;

		EnsureCrew();

		// in the star system, where the clock runs
		SpaceflightController.m_instance.SwitchLocation( PD_General.Location.StarSystem );

		yield return Frames( 10 );

		var minutesBefore = ( general.m_day * 24 + general.m_hour ) * 60 + general.m_minute + general.m_second / 60.0f;
		var end = Time.realtimeSinceStartup + 5.0f;
		var scaledBefore = Time.time;

		while ( Time.realtimeSinceStartup < end )
		{
			yield return null;
		}

		// what passed in game time, over what passed in the game's own seconds (the frame pacing of a headless run is not the clock's business)
		var played = Time.time - scaledBefore;
		var minutesAfter = ( general.m_day * 24 + general.m_hour ) * 60 + general.m_minute + general.m_second / 60.0f;
		var minutesPerTenSeconds = ( played > 0.0f ) ? ( minutesAfter - minutesBefore ) / played * 10.0f : 0.0f;

		Log( "clockrate: " + ( minutesAfter - minutesBefore ).ToString( "F1" ) + " game minutes in " + played.ToString( "F2" ) + " s of play: " + minutesPerTenSeconds.ToString( "F1" ) + " a 10 s" );

		Check( "clockrate: a star hour passes in 10 seconds of play, as the original's (REAL-MS 10000)", Mathf.Abs( minutesPerTenSeconds - 60.0f ) < 3.0f, minutesPerTenSeconds.ToString( "F1" ) + " game minutes per 10 s" );

		Finish( "scenario=clockrate checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the hull's integrity and where a hit lands (DAMAGE-OV)

	// the hull's integrity of a ship (-1 on the code from before the hull had an integrity of its own)
	static int HullIntegrityOf( PD_PlayerShip ship )
	{
		var getter = typeof( PD_PlayerShip ).GetMethod( "GetHullIntegrity" );

		return ( getter == null ) ? -1 : (int) getter.Invoke( ship, null );
	}

	// sets the hull's integrity (nothing on the code from before it)
	static void SetHullIntegrity( int integrity )
	{
		if ( !System.Enum.IsDefined( typeof( PD_PlayerShip.ShipSystem ), "Hull" ) )
		{
			return;
		}

		var hull = (PD_PlayerShip.ShipSystem) System.Enum.Parse( typeof( PD_PlayerShip.ShipSystem ), "Hull" );

		DataController.m_instance.m_playerData.m_playerShip.SetSystemHealth( hull, integrity );
	}

	// the sum of the health of every system and the vitality of the crew, to see whether a hit touched any of them
	static float PartsTotal()
	{
		var playerData = DataController.m_instance.m_playerData;
		var total = 0.0f;

		foreach ( var health in SystemHealth() )
		{
			total += health;
		}

		foreach ( var file in playerData.m_personnel.m_personnelList )
		{
			total += file.m_vitality;
		}

		return total;
	}

	IEnumerator ScenarioHullIntegrity()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var ship = playerData.m_playerShip;
		var combat = CombatController.m_instance;

		EnsureCrew();

		yield return Frames( 5 );

		// a bare hull (250 armor points) with a laser cannon and a missile launcher, the shields down, everything whole
		ship.m_armorClass = 0;
		ship.m_shieldingClass = 0;
		ship.m_laserCannonClass = 1;
		ship.m_missileLauncherClass = 1;
		ship.m_shieldsAreUp = false;
		ship.m_shieldPoints = 0;
		ship.RestoreSystems();
		SetHullIntegrity( 100 );

		// ---- 1. three hits of 50 on a ship with armor left: the armor takes all of them, no system, the hull or the crew is touched (a hit lands on the parts
		// only once the armor is gone, DAMAGE-OV WF378)
		ship.m_armorPoints = 250;

		var partsBefore = PartsTotal();

		for ( var hit = 0; hit < 3; hit++ )
		{
			combat.ApplyDamageToPlayer( 50, Vector3.forward );
		}

		var armorAfterHits = ship.m_armorPoints;
		var partsAfter = PartsTotal();

		// ---- 2. better armor loses less of a chunk, (6 - class) / 5 of it (WF26A): a hit of 10 is one chunk of 10
		ship.m_armorClass = 5;
		ship.m_armorPoints = 1500;

		combat.ApplyDamageToPlayer( 10, Vector3.forward );

		var class5Lost = 1500 - ship.m_armorPoints;

		ship.m_armorClass = 0;
		ship.m_armorPoints = 250;

		combat.ApplyDamageToPlayer( 10, Vector3.forward );

		var bareLost = 250 - ship.m_armorPoints;

		// ---- 3. raised shields take a whole chunk and pass nothing on to the armor, losing (6 - class) / 5 of it (WF248): class 3 shields with 3 points left, and
		// with 100
		ship.m_shieldingClass = 3;
		ship.m_shieldsAreUp = true;
		ship.m_shieldPoints = 3;
		ship.m_armorPoints = 250;

		combat.ApplyDamageToPlayer( 10, Vector3.forward );

		var weakShieldsLeft = ship.m_shieldPoints;
		var armorBehindWeakShields = ship.m_armorPoints;

		ship.m_shieldPoints = 100;

		combat.ApplyDamageToPlayer( 10, Vector3.forward );

		var class3ShieldsLeft = ship.m_shieldPoints;

		ship.m_shieldsAreUp = false;
		ship.m_shieldPoints = 0;
		ship.m_shieldingClass = 0;

		// ---- 4. the armor gone: the ship lives on and can be saved, and a hit lands on its parts, each chunk on one of them; with the hull at 20 a chunk of 10 takes
		// 5 off a system (10 times the chunk over the hull's integrity) - the hit is made again until it lands on a system rather than the crew
		ship.RestoreSystems();
		SetHullIntegrity( 100 );
		ship.m_armorPoints = 0;

		var savesBefore = MemorySaveSystem.s_saveCalls;

		combat.ApplyDamageToPlayer( 50, Vector3.forward );

		var destroyedAtNoArmor = combat.PlayerIsDestroyed();

		dataController.SaveActiveGame();

		var savedAtNoArmor = MemorySaveSystem.s_saveCalls > savesBefore;
		var systemLoss = -1;

		for ( var attempt = 0; ( attempt < 30 ) && ( systemLoss <= 0 ) && !combat.PlayerIsDestroyed(); attempt++ )
		{
			ship.RestoreSystems();
			SetHullIntegrity( 20 );
			ship.m_armorPoints = 0;

			var before = SystemHealth();

			combat.ApplyDamageToPlayer( 10, Vector3.forward );

			var after = SystemHealth();

			systemLoss = 0;

			for ( var system = 0; ( system < before.Length ) && ( system < after.Length ); system++ )
			{
				// the hull's own loss is 5 as well, but at 20 it is easier to read on the others
				systemLoss += before[ system ] - after[ system ];
			}
		}

		ship.RestoreSystems();
		SetHullIntegrity( 100 );

		// ---- 5. the status display's DAMAGE reads the hull and the systems, not the armor (SCIENCE WE760): no armor and everything whole is no damage, every
		// system and the hull at half is moderate, and a hull at 15 is critical
		ship.m_armorPoints = 0;

		var noArmorLine = StatusDamageLine( out _, out _ );

		for ( var system = 0; system < (int) PD_PlayerShip.ShipSystem.Count; system++ )
		{
			ship.SetSystemHealth( (PD_PlayerShip.ShipSystem) system, 50 );
		}

		var halfLine = StatusDamageLine( out _, out _ );

		ship.RestoreSystems();
		SetHullIntegrity( 15 );

		var weakHullLine = StatusDamageLine( out _, out _ );

		// ---- 6. the Starport charges 250 M.U. a point of the hull's integrity (CONFIG-OV WF226), the rest whole
		SetHullIntegrity( 90 );
		ship.m_armorPoints = 250;

		var repairCost = ship.GetStarportRepairCost();

		// ---- 7. a save from before the hull had an integrity of its own (six systems) loads with a whole hull
		var oldShip = JsonUtility.FromJson<PD_PlayerShip>( JsonUtility.ToJson( ship ) );

		oldShip.m_systemHealth = new[] { 100, 90, 80, 100, 100, 100 };

		var reloaded = JsonUtility.FromJson<PD_PlayerShip>( JsonUtility.ToJson( oldShip ) );
		var oldSaveHull = HullIntegrityOf( reloaded );

		// ---- 8. the engineer repairs the hull's integrity, never the armor (REPAIR-OV: the armor is the Starport's)
		ship.RestoreSystems();
		SetHullIntegrity( 50 );
		ship.m_armorPoints = 100;
		ship.StartRepairs( PD_PlayerShip.c_hullRepairItem );
		ship.UpdateRepairs( 10.0f );

		var hullAfterRepair = HullIntegrityOf( ship );
		var armorAfterRepair = ship.m_armorPoints;

		ship.StopRepairs();

		Log( "hullintegrity: 3 hits of 50 on 250 armor: armor " + armorAfterHits + ", parts " + partsBefore + " -> " + partsAfter + " | a chunk of 10 takes " + class5Lost + " off class 5 armor, " + bareLost + " off a bare hull | class 3 shields at 3: " + weakShieldsLeft + " left, armor " + armorBehindWeakShields + "; at 100: " + class3ShieldsLeft + " left | no armor: destroyed " + destroyedAtNoArmor + ", saved " + savedAtNoArmor + ", a chunk of 10 at hull 20 took " + systemLoss + " | damage lines '" + noArmorLine + "' / '" + halfLine + "' / '" + weakHullLine + "' | repair cost at hull 90 " + repairCost + " | old save hull " + oldSaveHull + " | engineer: hull " + hullAfterRepair + ", armor " + armorAfterRepair );

		Check( "hullintegrity: hits on a ship with armor left fall on the armor alone (no system, the hull or the crew is touched)", ( armorAfterHits < 250 ) && ( armorAfterHits > 0 ) && Mathf.Approximately( partsBefore, partsAfter ), "armor " + armorAfterHits + ", parts " + partsBefore + " -> " + partsAfter );
		Check( "hullintegrity: better armor loses less of a hit, (6 - class) / 5 of it: 2 of 10 for class 5, 12 for a bare hull", ( class5Lost == 2 ) && ( bareLost == 12 ), class5Lost + " / " + bareLost );
		Check( "hullintegrity: raised shields take a whole chunk and pass nothing on to the armor (class 3 lose 6 of 10)", ( weakShieldsLeft == 0 ) && ( armorBehindWeakShields == 250 ) && ( class3ShieldsLeft == 94 ), weakShieldsLeft + " left, armor " + armorBehindWeakShields + ", class 3 at 100: " + class3ShieldsLeft );
		Check( "hullintegrity: a ship with no armor left is not destroyed and can be saved, and a chunk of 10 takes 5 off a part when the hull is at 20", !destroyedAtNoArmor && savedAtNoArmor && ( systemLoss == 5 ), "destroyed " + destroyedAtNoArmor + ", saved " + savedAtNoArmor + ", loss " + systemLoss );
		Check( "hullintegrity: the status display's DAMAGE reads the hull and the systems, not the armor", ( noArmorLine == "None" ) && halfLine.Contains( ">Moderate<" ) && weakHullLine.Contains( ">Critical<" ), noArmorLine + " / " + halfLine + " / " + weakHullLine );
		Check( "hullintegrity: the Starport charges 250 M.U. a point of the hull's integrity", repairCost == 2500, repairCost.ToString() );
		Check( "hullintegrity: a save from before the hull's integrity loads with a whole hull", oldSaveHull == 100, oldSaveHull.ToString() );
		Check( "hullintegrity: the engineer repairs the hull's integrity and never the armor", ( hullAfterRepair > 50 ) && ( armorAfterRepair == 100 ), "hull " + hullAfterRepair + ", armor " + armorAfterRepair );

		// ---- 9. the hull's integrity at 0 destroys the ship, in the original's words ("!!HULL DESTROYED!!"), and the lost game is never saved: the hull at 1 and
		// every system gone, so a chunk lands on the hull or the crew, hit until the ship is destroyed
		ship.m_armorPoints = 0;

		for ( var system = 0; system < (int) PD_PlayerShip.ShipSystem.Count; system++ )
		{
			ship.SetSystemHealth( (PD_PlayerShip.ShipSystem) system, 0 );
		}

		SetHullIntegrity( 1 );
		SpaceflightController.m_instance.m_messages.Clear();

		for ( var hit = 0; ( hit < 50 ) && !combat.PlayerIsDestroyed(); hit++ )
		{
			combat.ApplyDamageToPlayer( 10, Vector3.forward );
		}

		var destroyed = combat.PlayerIsDestroyed();
		var hullAtTheEnd = HullIntegrityOf( ship );

		yield return new WaitForSecondsRealtime( 3.0f );

		var gameOverText = MessageList();
		var savesBeforeLost = MemorySaveSystem.s_saveCalls;

		dataController.SaveActiveGame();

		var savedLost = MemorySaveSystem.s_saveCalls > savesBeforeLost;

		Log( "hullintegrity: destroyed " + destroyed + ", hull " + hullAtTheEnd + ", saved " + savedLost + " | " + gameOverText );

		Check( "hullintegrity: the ship is destroyed when its hull's integrity reaches 0, in the original's words, and the lost game is never saved", destroyed && ( hullAtTheEnd == 0 ) && gameOverText.Contains( "Hull destroyed" ) && !savedLost, "destroyed " + destroyed + ", hull " + hullAtTheEnd + ", saved " + savedLost + " | " + gameOverText );

		Finish( "scenario=hullintegrity checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the weapons' damage (DAMAGE-OV LDAMAGE and MDAMAGE)

	// a static method of a type that returns a number, called with these arguments (-1 on the code that has no such method)
	static int CallStaticInt( System.Type type, string name, params object[] args )
	{
		var method = type.GetMethod( name, BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static );

		if ( method == null )
		{
			return -1;
		}

		var result = method.Invoke( null, args );

		return ( result is bool flag ) ? ( flag ? 1 : 0 ) : (int) result;
	}

	// the index of a vessel in the game data by its name (-1 if there is none)
	static int VesselIndex( string name )
	{
		var vessels = DataController.m_instance.m_gameData.m_vesselList;

		for ( var i = 0; i < vessels.Length; i++ )
		{
			if ( vessels[ i ].m_name == name )
			{
				return i;
			}
		}

		return -1;
	}

	IEnumerator ScenarioWeaponDamage()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var ship = playerData.m_playerShip;
		var combat = CombatController.m_instance;

		EnsureCrew();

		yield return Frames( 5 );

		// ---- 1. a laser's damage, falling off with the distance (WED12: (10 - cells) / 10 of LDAMAGE, a cell 80 units in the port)
		var laser1Close = CallStaticInt( typeof( CombatController ), "GetLaserDamage", 1, 0.0f );
		var laser1FiveCells = CallStaticInt( typeof( CombatController ), "GetLaserDamage", 1, 400.0f );
		var laser1TenCells = CallStaticInt( typeof( CombatController ), "GetLaserDamage", 1, 800.0f );
		var laser5Close = CallStaticInt( typeof( CombatController ), "GetLaserDamage", 5, 0.0f );

		// ---- 2. a missile's damage, whatever the distance (MDAMAGE: class 6 is the plasma bolt)
		var missile1 = CallStaticInt( typeof( CombatController ), "GetMissileDamage", 1 );
		var missile5 = CallStaticInt( typeof( CombatController ), "GetMissileDamage", 5 );
		var plasmaBolt = CallStaticInt( typeof( CombatController ), "GetMissileDamage", 6 );

		// ---- 3. an alien laser does twice a laser's damage, a quarter of it first with the Rod Device aboard (WF3EA, WED36): class 3 from 3 cells is (10 - 3) / 10
		// of 360, 252, so 504, and 63 twice with the Rod, 126
		var alienLaser = CallStaticInt( typeof( CombatController ), "GetAlienLaserDamage", 3, 240.0f, false );
		var alienLaserRod = CallStaticInt( typeof( CombatController ), "GetAlienLaserDamage", 3, 240.0f, true );

		// ---- 4. an alien fires only within 5 cells of the ship across and along (COMBAT-OV WE07D, WE0AB: 400 units in the port)
		var inReach = CallStaticInt( typeof( Encounter ), "IsWithinWeaponsReach", new Vector3( 399.0f, 0.0f, -399.0f ), Vector3.zero );
		var outAcross = CallStaticInt( typeof( Encounter ), "IsWithinWeaponsReach", new Vector3( 401.0f, 0.0f, 0.0f ), Vector3.zero );
		var outAlong = CallStaticInt( typeof( Encounter ), "IsWithinWeaponsReach", new Vector3( 0.0f, 0.0f, -401.0f ), Vector3.zero );

		// ---- 5. end to end: a Thrynn scout's class 5 laser from 3 cells (twice 462, 924), with the Rod Device (twice 115, 230), and an Uhlek warship's plasma bolt
		// (4000), on class 1 armor with plenty of points (a chunk takes its own size off it; a hit's last chunk is at least 10 points, so up to 9 more)
		ship.m_shieldsAreUp = false;
		ship.m_armorClass = 1;
		ship.m_armorPoints = 100000;
		ship.RestoreSystems();

		var rodId = gameData.FindArtifactId( "Rod Device" );

		for ( var guard = 0; ( guard < 10 ) && ( ship.m_artifactStorage.Find( rodId ) != null ); guard++ )
		{
			ship.RemoveArtifact( rodId );
		}

		var scoutIndex = VesselIndex( "Thrynn Scout" );
		var warshipIndex = VesselIndex( "Uhlek Warship" );
		var alienShip = new PD_AlienShip();

		alienShip.m_coordinates = playerData.m_general.m_coordinates + new Vector3( 240.0f, 0.0f, 0.0f );

		var before = ship.m_armorPoints;

		combat.AlienFiresAtPlayer( alienShip, gameData.m_vesselList[ scoutIndex ] );

		var laserLoss = before - ship.m_armorPoints;

		ship.AddArtifact( rodId );

		before = ship.m_armorPoints;

		combat.AlienFiresAtPlayer( alienShip, gameData.m_vesselList[ scoutIndex ] );

		var rodLoss = before - ship.m_armorPoints;

		ship.RemoveArtifact( rodId );

		before = ship.m_armorPoints;

		combat.AlienFiresAtPlayer( alienShip, gameData.m_vesselList[ warshipIndex ] );

		// the plasma bolt is a missile that follows the ship (COMBAT-OV WE929): nothing until it arrives
		var plasmaRightAway = before - ship.m_armorPoints;
		var waitUntil = Time.realtimeSinceStartup + 10.0f;

		while ( ( ship.m_armorPoints == before ) && ( Time.realtimeSinceStartup < waitUntil ) )
		{
			yield return null;
		}

		var plasmaLoss = before - ship.m_armorPoints;

		ship.m_armorPoints = ship.GetMaximumArmorPoints();

		Log( "weapondamage: laser class 1 at 0/400/800 units " + laser1Close + "/" + laser1FiveCells + "/" + laser1TenCells + ", class 5 at 0 " + laser5Close + " | missiles " + missile1 + "/" + missile5 + ", plasma " + plasmaBolt + " | alien class 3 laser from 240 " + alienLaser + ", with the Rod " + alienLaserRod + " | reach " + inReach + "/" + outAcross + "/" + outAlong + " | end to end: Thrynn scout's laser " + laserLoss + ", with the Rod " + rodLoss + ", Uhlek plasma " + plasmaRightAway + " right away and " + plasmaLoss + " when it arrived" );

		Check( "weapondamage: a laser does the original's damage, falling off with the distance (class 1: 90 close, 45 at 5 cells, nothing at 10; class 5: 660)", ( laser1Close == 90 ) && ( laser1FiveCells == 45 ) && ( laser1TenCells == 0 ) && ( laser5Close == 660 ), laser1Close + "/" + laser1FiveCells + "/" + laser1TenCells + "/" + laser5Close );
		Check( "weapondamage: a missile does the original's damage whatever the distance (200 for class 1, 1500 for class 5, 4000 for the plasma bolt)", ( missile1 == 200 ) && ( missile5 == 1500 ) && ( plasmaBolt == 4000 ), missile1 + "/" + missile5 + "/" + plasmaBolt );
		Check( "weapondamage: an alien laser does twice a laser's damage, a quarter of it first with the Rod Device (class 3 from 3 cells: 504, with the Rod 126)", ( alienLaser == 504 ) && ( alienLaserRod == 126 ), alienLaser + "/" + alienLaserRod );
		Check( "weapondamage: an alien fires only within 5 cells of the ship across and along", ( inReach == 1 ) && ( outAcross == 0 ) && ( outAlong == 0 ), inReach + "/" + outAcross + "/" + outAlong );
		Check( "weapondamage: end to end a Thrynn scout's laser from 3 cells takes 924, 230 with the Rod Device, and an Uhlek warship's plasma bolt, a missile that follows the ship, 4000 when it arrives", ( laserLoss >= 924 ) && ( laserLoss <= 933 ) && ( rodLoss >= 230 ) && ( rodLoss <= 239 ) && ( plasmaRightAway == 0 ) && ( plasmaLoss >= 4000 ) && ( plasmaLoss <= 4009 ), laserLoss + "/" + rodLoss + "/" + plasmaRightAway + "/" + plasmaLoss );

		Finish( "scenario=weapondamage checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the navigator's aim and the Endurium a shot uses (COMBAT-OV)

	// how many of these rolls of the navigator's aim are on target, and the most cells any of them is off (-1 on the code without the aim)
	static int AimOnTarget( int skill, int rolls, out int widest )
	{
		widest = 0;

		var roll = typeof( CombatController ).GetMethod( "RollAimOffset", BindingFlags.Public | BindingFlags.Static );

		if ( roll == null )
		{
			return -1;
		}

		var onTarget = 0;

		for ( var i = 0; i < rolls; i++ )
		{
			var offset = (Vector2Int) roll.Invoke( null, new object[] { skill } );

			if ( offset == Vector2Int.zero )
			{
				onTarget++;
			}

			widest = Mathf.Max( widest, Mathf.Max( Mathf.Abs( offset.x ), Mathf.Abs( offset.y ) ) );
		}

		return onTarget;
	}

	IEnumerator ScenarioAimAndFuel()
	{
		var playerData = DataController.m_instance.m_playerData;
		var ship = playerData.m_playerShip;
		var combat = CombatController.m_instance;

		EnsureCrew();

		yield return Frames( 5 );

		// ---- 1 to 3. the aim, rolled 2000 times at each skill (WF0D8: on target with (50 / (250 - skill)) squared, always from 200)
		var at250 = AimOnTarget( 250, 2000, out _ );
		var at200 = AimOnTarget( 200, 2000, out _ );
		var at150 = AimOnTarget( 150, 2000, out var widest150 );
		var at0 = AimOnTarget( 0, 2000, out var widest0 );

		// ---- 4. end to end: a navigator of skill 0 fires the laser 20 times at a Spemin scout, then one of skill 250 five times
		ship.m_laserCannonClass = 1;
		ship.m_missileLauncherClass = 1;
		ship.m_armorPoints = 100000;
		ship.m_shieldsAreUp = false;
		ship.m_weaponsAreArmed = true;

		if ( EnduriumTenths() < 200 )
		{
			ship.AddElement( 5, 500 );
		}

		var speminId = FindEncounter( 1, 6, 3, 0 );

		ForceVessel( speminId, 2 );
		EnterEncounter( speminId );

		yield return Frames( 10 );

		var targetIndex = FirstLivingAlien();
		var alien = SpaceflightController.m_instance.m_encounter.m_pdEncounter.GetAlienShipList()[ targetIndex ];

		alien.m_armorPoints = 100000;
		alien.m_shieldPoints = 0;

		combat.SetTarget( targetIndex );

		var navigator = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.Navigator );
		var laserCooldown = typeof( CombatController ).GetField( "m_playerLaserCooldown", BindingFlags.NonPublic | BindingFlags.Instance );
		var missileCooldown = typeof( CombatController ).GetField( "m_playerMissileCooldown", BindingFlags.NonPublic | BindingFlags.Instance );
		var hitsAt0 = 0;
		var hitsAt250 = 0;
		var shotsAt0 = 0;
		var shotsAt250 = 0;

		navigator.m_navigation = 0;

		for ( var shot = 0; shot < 20; shot++ )
		{
			laserCooldown.SetValue( combat, 0.0f );
			BringAliensClose();

			var before = alien.m_armorPoints;

			if ( combat.FirePlayerLaser() )
			{
				shotsAt0++;
			}

			if ( alien.m_armorPoints < before )
			{
				hitsAt0++;
			}
		}

		navigator.m_navigation = 250;

		for ( var shot = 0; shot < 5; shot++ )
		{
			laserCooldown.SetValue( combat, 0.0f );
			BringAliensClose();

			var before = alien.m_armorPoints;

			if ( combat.FirePlayerLaser() )
			{
				shotsAt250++;
			}

			if ( alien.m_armorPoints < before )
			{
				hitsAt250++;
			}
		}

		// ---- 5. the Endurium a shot uses: a tenth of a cubic meter for the laser, half for a missile (WF1DC, WF1B6)
		laserCooldown.SetValue( combat, 0.0f );
		BringAliensClose();

		var beforeLaser = EnduriumTenths();
		var laserFired = combat.FirePlayerLaser();
		var laserUsed = beforeLaser - EnduriumTenths();

		missileCooldown.SetValue( combat, 0.0f );

		var beforeMissile = EnduriumTenths();
		var missileFired = combat.FirePlayerMissile();
		var missileUsed = beforeMissile - EnduriumTenths();

		yield return Frames( 5 );

		Log( "aimandfuel: on target of 2000 at skill 250/200/150/0: " + at250 + "/" + at200 + "/" + at150 + "/" + at0 + ", widest at 150 " + widest150 + " and at 0 " + widest0 + " | lasers that hit: skill 0 " + hitsAt0 + " of " + shotsAt0 + ", skill 250 " + hitsAt250 + " of " + shotsAt250 + " | Endurium a shot uses, in tenths: laser " + laserUsed + " (fired " + laserFired + "), missile " + missileUsed + " (fired " + missileFired + ")" );

		Check( "aimandfuel: a navigator of skill 200 or more always aims on target", ( at250 == 2000 ) && ( at200 == 2000 ), at250 + "/" + at200 );
		Check( "aimandfuel: a weaker navigator is on target with the chance (50 / (250 - skill)) squared: a quarter at 150, one in 25 at 0", ( at150 >= 400 ) && ( at150 <= 600 ) && ( at0 >= 35 ) && ( at0 <= 125 ), at150 + " and " + at0 + " of 2000" );
		Check( "aimandfuel: a shot off target is off by whole cells, at most 1 at skill 150 and 4 at skill 0", ( widest150 == 1 ) && ( widest0 == 4 ), widest150 + " / " + widest0 );
		Check( "aimandfuel: end to end, a navigator of skill 0 mostly misses (no damage), one of skill 250 always hits", ( shotsAt0 == 20 ) && ( hitsAt0 <= 6 ) && ( shotsAt250 == 5 ) && ( hitsAt250 == 5 ), hitsAt0 + " of " + shotsAt0 + " / " + hitsAt250 + " of " + shotsAt250 );
		Check( "aimandfuel: a laser shot uses a tenth of a cubic meter of Endurium, a missile half a cubic meter", laserFired && missileFired && ( laserUsed == 1 ) && ( missileUsed == 5 ), laserUsed + " / " + missileUsed );

		Finish( "scenario=aimandfuel checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// renders every camera in its order of depth (as RenderScreenPicture) and gives back the picture's pixels, 1920 x 1080, bottom row first
	static Color32[] RenderScreenPixels()
	{
		var renderTexture = new RenderTexture( 1920, 1080, 24, RenderTextureFormat.ARGB32 );
		var picture = new Texture2D( 1920, 1080, TextureFormat.RGB24, false );
		var cameras = new List<Camera>( Camera.allCameras );

		cameras.Sort( ( a, b ) => a.depth.CompareTo( b.depth ) );

		var active = RenderTexture.active;

		RenderTexture.active = renderTexture;
		GL.Clear( true, true, Color.black );

		foreach ( var camera in cameras )
		{
			if ( !camera.enabled || ( camera.targetTexture != null ) )
			{
				continue;
			}

			camera.targetTexture = renderTexture;
			camera.Render();
			camera.targetTexture = null;
		}

		RenderTexture.active = renderTexture;
		picture.ReadPixels( new Rect( 0, 0, 1920, 1080 ), 0, 0 );
		picture.Apply();
		RenderTexture.active = active;

		var pixels = picture.GetPixels32();

		UnityEngine.Object.Destroy( picture );
		renderTexture.Release();
		UnityEngine.Object.Destroy( renderTexture );

		return pixels;
	}

	// the relative luminance of a colour as the screen shows it (WCAG 2)
	static float DoorLabelLuminance( Color colour )
	{
		Func<float, float> channel = c => ( c <= 0.04045f ) ? ( c / 12.92f ) : Mathf.Pow( ( c + 0.055f ) / 1.055f, 2.4f );

		return 0.2126f * channel( colour.r ) + 0.7152f * channel( colour.g ) + 0.0722f * channel( colour.b );
	}

	// the contrast of two luminances (WCAG 2: 1 to 21)
	static float DoorLabelContrast( float a, float b )
	{
		return ( Mathf.Max( a, b ) + 0.05f ) / ( Mathf.Min( a, b ) + 0.05f );
	}

	// how well a text can be read against the screen behind it: the screen is drawn without the text, and the text's colour is compared with every pixel of
	// the hall in the text's box - gives back the contrast over 95% and over 80% of the box (WCAG 2), and the picture with the text into the path if one is given
	static Vector2 DoorLabelContrasts( TMPro.TMP_Text text, string picturePath, out string box )
	{
		var withText = RenderScreenPixels();

		text.enabled = false;

		var behind = RenderScreenPixels();

		text.enabled = true;

		// the box of the text on the picture (the UI camera's viewport, so the picture's size does not have to be the screen's)
		text.ForceMeshUpdate();

		var bounds = text.textBounds;
		var uiCamera = ( text.canvas != null ) ? text.canvas.worldCamera : null;
		var xMin = 1919;
		var xMax = 0;
		var yMin = 1079;
		var yMax = 0;

		for ( var corner = 0; corner < 4; corner++ )
		{
			var local = new Vector3( ( ( corner & 1 ) == 0 ) ? bounds.min.x : bounds.max.x, ( ( corner & 2 ) == 0 ) ? bounds.min.y : bounds.max.y, 0.0f );
			var viewport = ( uiCamera != null ) ? uiCamera.WorldToViewportPoint( text.rectTransform.TransformPoint( local ) ) : Vector3.zero;

			xMin = Mathf.Min( xMin, Mathf.FloorToInt( viewport.x * 1920.0f ) );
			xMax = Mathf.Max( xMax, Mathf.CeilToInt( viewport.x * 1920.0f ) );
			yMin = Mathf.Min( yMin, Mathf.FloorToInt( viewport.y * 1080.0f ) );
			yMax = Mathf.Max( yMax, Mathf.CeilToInt( viewport.y * 1080.0f ) );
		}

		xMin = Mathf.Clamp( xMin, 0, 1919 );
		xMax = Mathf.Clamp( xMax, 0, 1919 );
		yMin = Mathf.Clamp( yMin, 0, 1079 );
		yMax = Mathf.Clamp( yMax, 0, 1079 );

		box = xMin + ".." + xMax + " x " + yMin + ".." + yMax;

		var textLuminance = DoorLabelLuminance( text.color );
		var contrasts = new List<float>();

		for ( var y = yMin; y <= yMax; y++ )
		{
			for ( var x = xMin; x <= xMax; x++ )
			{
				contrasts.Add( DoorLabelContrast( textLuminance, DoorLabelLuminance( behind[ y * 1920 + x ] ) ) );
			}
		}

		contrasts.Sort();

		if ( !string.IsNullOrEmpty( picturePath ) )
		{
			var picture = new Texture2D( 1920, 1080, TextureFormat.RGB24, false );

			picture.SetPixels32( withText );
			picture.Apply();

			System.IO.File.WriteAllBytes( picturePath, picture.EncodeToPNG() );

			UnityEngine.Object.Destroy( picture );
		}

		return ( contrasts.Count > 0 ) ? new Vector2( contrasts[ contrasts.Count / 20 ], contrasts[ contrasts.Count / 5 ] ) : Vector2.zero;
	}

	// the name of the door the astronaut stands at (the label at the top of the screen in the Starport's hall) can be read in every scheme of the UI kit, in its
	// dark and its light mode: it takes the colours of the 3D views (the scheme's dark theme in either mode, UIKitOverView), as the hall behind it does, and
	// with -Graphics, against the picture of the hall behind it without the text, the label's colour has a contrast of at least 4.5 to 1 (WCAG AA) over most of
	// its box and of at least 3 to 1 (AA for large text) over nearly all of it, at the Operations door in every scheme and at each of the seven doors
	IEnumerator ScenarioStarportDoorLabels()
	{
		var folder = ScreenPictureFolder( "starport-door-labels" );

		yield return Frames( 60 );

		// the scene's fade in has to be over, or the hall is darker in the first pictures (it turns its black image off when it is done)
		for ( var frame = 0; ( frame < 600 ) && ( SceneFadeController.m_instance != null ) && ( SceneFadeController.m_instance.m_fadeImage != null ) && SceneFadeController.m_instance.m_fadeImage.gameObject.activeInHierarchy; frame++ )
		{
			yield return null;
		}

		var astronaut = FindFirstObjectByType<AstronautController>();
		var doorName = ( astronaut != null ) ? astronaut.m_doorNameController : null;

		if ( ( doorName == null ) || ( doorName.m_doorNameText == null ) )
		{
			Finish( "abort: the Starport has no astronaut with a door name", 2 );

			yield break;
		}

		// the doors' triggers (each one's tag is its door's name)
		var doorNames = new[] { "Operations", "Personnel", "Crew Assignment", "Bank", "Ship Configuration", "Trade Depot", "Docking Bay" };
		var doors = new Dictionary<string, Collider>();

		foreach ( var collider in FindObjectsByType<Collider>( FindObjectsSortMode.None ) )
		{
			if ( collider.isTrigger && ( Array.IndexOf( doorNames, collider.tag ) >= 0 ) )
			{
				doors[ collider.tag ] = collider;
			}
		}

		var text = doorName.m_doorNameText;
		var start = astronaut.transform.position;
		var failures = new List<string>();
		var wrongColours = new List<string>();
		var shownNames = new List<string>();
		var measured = 0;
		var pictureNumber = 0;
		var box = "";

		// ---- each door: the astronaut walks onto its trigger from the middle of the hall (so that leaving one door's trigger cannot hide the next one's name),
		// and its name is read in the classic scheme's dark and light modes
		foreach ( var name in doorNames )
		{
			if ( !doors.ContainsKey( name ) )
			{
				continue;
			}

			// (the triggers are met in physics steps, and a frame without a graphics device is much shorter than one, so the waits are in game time)
			astronaut.m_navMeshAgent.Warp( start );

			for ( var end = Time.time + 2.0f; ( Time.time < end ) && doorName.IsShowingDoorName(); )
			{
				yield return null;
			}

			astronaut.m_navMeshAgent.Warp( doors[ name ].bounds.center );

			for ( var end = Time.time + 2.0f; ( Time.time < end ) && !( doorName.IsShowingDoorName() && ( doorName.GetCurrentDoorName() == name ) ); )
			{
				yield return null;
			}

			yield return Frames( 3 );

			if ( doorName.IsShowingDoorName() && ( doorName.GetCurrentDoorName() == name ) )
			{
				shownNames.Add( name );
			}

			for ( var light = 0; ( light < 2 ) && ( folder != "" ); light++ )
			{
				UIKitTheme.SetScheme( 0, false );
				UIKitTheme.SetMode( ( light == 1 ) ? UIKitTheme.Mode.Light : UIKitTheme.Mode.Dark, false );

				yield return Frames( 3 );

				var label = name + " in Classic " + ( ( light == 1 ) ? "light" : "dark" );
				var contrast = DoorLabelContrasts( text, System.IO.Path.Combine( folder, ( ++pictureNumber ).ToString( "00" ) + "_" + label.Replace( ' ', '_' ) + ".png" ), out box );

				measured++;

				Log( "starport-doorlabels: " + label + ": text " + ColorUtility.ToHtmlStringRGB( text.color ) + ", box " + box + ", contrast (95%) " + contrast.x.ToString( "F2" ) + ", (80%) " + contrast.y.ToString( "F2" ) );

				if ( ( contrast.x < 3.0f ) || ( contrast.y < 4.5f ) )
				{
					failures.Add( label + " " + contrast.x.ToString( "F1" ) + "/" + contrast.y.ToString( "F1" ) );
				}
			}
		}

		Log( "starport-doorlabels: door triggers found " + doors.Count + ", names shown at their doors: " + string.Join( ", ", shownNames ) + "; screen " + Screen.width + " x " + Screen.height );

		Check( "starport-doorlabels: standing at each of the seven doors shows its name", shownNames.Count == doorNames.Length, shownNames.Count + " of " + doorNames.Length + ": " + string.Join( ", ", shownNames ) );

		// ---- the Operations door in every scheme, dark and light
		if ( doors.ContainsKey( "Operations" ) )
		{
			astronaut.m_navMeshAgent.Warp( start );

			for ( var end = Time.time + 2.0f; ( Time.time < end ) && doorName.IsShowingDoorName(); )
			{
				yield return null;
			}

			astronaut.m_navMeshAgent.Warp( doors[ "Operations" ].bounds.center );

			for ( var end = Time.time + 2.0f; ( Time.time < end ) && !( doorName.IsShowingDoorName() && ( doorName.GetCurrentDoorName() == "Operations" ) ); )
			{
				yield return null;
			}
		}

		if ( !doorName.IsShowingDoorName() )
		{
			doorName.SetText( "Operations" );

			yield return Frames( 3 );
		}

		for ( var scheme = 0; scheme < UIKitTheme.c_schemes.Length; scheme++ )
		{
			for ( var light = 0; light < 2; light++ )
			{
				UIKitTheme.SetScheme( scheme, false );
				UIKitTheme.SetMode( ( light == 1 ) ? UIKitTheme.Mode.Light : UIKitTheme.Mode.Dark, false );

				yield return Frames( 3 );

				var label = UIKitTheme.c_schemes[ scheme ].m_name + ( ( light == 1 ) ? " light" : " dark" );

				// the label's colour is the views' primary text colour (the scheme's dark theme), in the light mode too
				var viewText = UIKitTheme.GetViewTheme().GetColor( UIKitTheme.ColorRole.TextPrimary );

				if ( ( Mathf.Abs( text.color.r - viewText.r ) > 1.5f / 255.0f ) || ( Mathf.Abs( text.color.g - viewText.g ) > 1.5f / 255.0f ) || ( Mathf.Abs( text.color.b - viewText.b ) > 1.5f / 255.0f ) )
				{
					wrongColours.Add( label + " " + ColorUtility.ToHtmlStringRGB( text.color ) + " not " + ColorUtility.ToHtmlStringRGB( viewText ) );
				}

				if ( folder == "" )
				{
					continue;
				}

				var contrast = DoorLabelContrasts( text, System.IO.Path.Combine( folder, ( ++pictureNumber ).ToString( "00" ) + "_Operations_in_" + label.Replace( ' ', '_' ) + ".png" ), out box );

				measured++;

				Log( "starport-doorlabels: Operations in " + label + ": text " + ColorUtility.ToHtmlStringRGB( text.color ) + ", box " + box + ", contrast (95%) " + contrast.x.ToString( "F2" ) + ", (80%) " + contrast.y.ToString( "F2" ) );

				if ( ( contrast.x < 3.0f ) || ( contrast.y < 4.5f ) )
				{
					failures.Add( "Operations in " + label + " " + contrast.x.ToString( "F1" ) + "/" + contrast.y.ToString( "F1" ) );
				}
			}
		}

		UIKitTheme.SetScheme( 0, false );
		UIKitTheme.SetMode( UIKitTheme.Mode.Dark, false );

		Check( "starport-doorlabels: the door's name takes the 3D views' text colour (the scheme's dark theme) in every scheme, dark and light", wrongColours.Count == 0, wrongColours.Count + " of " + ( UIKitTheme.c_schemes.Length * 2 ) + " wrong: " + string.Join( ", ", wrongColours.GetRange( 0, Mathf.Min( 6, wrongColours.Count ) ) ) );

		if ( folder == "" )
		{
			Log( "starport-doorlabels: no graphics device (-nographics), so no pictures to measure the contrast in; run probe.ps1 with -Graphics" );
		}
		else
		{
			Check( "starport-doorlabels: the door's name can be read at every door and in every scheme, dark and light (contrast at least 3:1 over 95% and 4.5:1 over 80% of its box)", ( measured == doorNames.Length * 2 + UIKitTheme.c_schemes.Length * 2 ) && ( failures.Count == 0 ), measured + " measured, " + failures.Count + " too faint: " + string.Join( ", ", failures.GetRange( 0, Mathf.Min( 8, failures.Count ) ) ) );

			Log( "starport-doorlabels: " + pictureNumber + " pictures in " + folder );
		}

		Finish( "scenario=starport-doorlabels checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// flies in hyperspace in one direction with the engines on for some real seconds from a standstill - gives back the fuel used (in cubic meters) and the
	// distance flown along the longer axis (in coordinates), measured while the engines run (before the ship coasts to a stop)
	static IEnumerator HyperspaceFuelOnHeading( Vector3 heading, float seconds, float[] fuelAndDistance )
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;

		controller.m_playerShip.TurnOffEngines();
		playerData.m_general.m_currentSpeed = 0.0f;
		playerData.m_general.m_currentDirection = heading.normalized;

		yield return Frames( 2 );

		var enduriumBefore = Endurium();
		var fuelUsedBefore = playerData.m_playerShip.m_fuelUsed;
		var start = controller.m_playerShip.transform.position;

		controller.m_playerShip.TurnOnEngines();

		for ( var end = Time.realtimeSinceStartup + seconds; Time.realtimeSinceStartup < end; )
		{
			playerData.m_general.m_currentDirection = heading.normalized;

			yield return null;
		}

		var moved = controller.m_playerShip.transform.position - start;

		controller.m_playerShip.TurnOffEngines();

		fuelAndDistance[ 0 ] = ( enduriumBefore - Endurium() ) * 0.1f + ( playerData.m_playerShip.m_fuelUsed - fuelUsedBefore );
		fuelAndDistance[ 1 ] = Mathf.Max( Mathf.Abs( moved.x ), Mathf.Abs( moved.z ) ) / 256.0f;
	}

	// the engines burn their fuel at every step of the ship in hyperspace, an eighth of a coordinate, as the original's (HYPER-OV FLY and -ENDURIUM): a step on the
	// diagonal moves the ship along both axes for the fuel of one, so the fuel goes by the longer of the two distances flown along the axes (class 1 engines: 6
	// hundredths a step, 0.48 m3 a coordinate, straight or diagonal), and the Tesseract halves a step's fuel in whole hundredths (PORTMENU-OV WEAF0: class 2,
	// 5 hundredths, 2 with it, 0.16 m3 a coordinate)
	IEnumerator ScenarioHyperspaceFuel()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var controller = SpaceflightController.m_instance;
		var ship = playerData.m_playerShip;
		var tesseractId = gameData.FindArtifactId( "Tesseract" );
		var measured = new float[ 2 ];

		EnsureCrew();

		// plenty of Endurium, class 1 engines and no Tesseract to begin with
		ship.AddElement( 5, 500 );
		ship.m_enginesClass = 1;

		for ( var guard = 0; ( guard < 10 ) && ( ship.m_artifactStorage.Find( tesseractId ) != null ); guard++ )
		{
			ship.RemoveArtifact( tesseractId );
		}

		// out in hyperspace, in a corner of it and flying away from its edges, with no encounter able to begin
		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		playerData.m_general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 6.0f, 0.0f, 6.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		// ---- 1. class 1 engines, straight along an axis (the control) and on the diagonal
		yield return HyperspaceFuelOnHeading( new Vector3( 1.0f, 0.0f, 0.0f ), 4.0f, measured );

		var straightFuel = measured[ 0 ];
		var straightDistance = measured[ 1 ];
		var straightRate = ( straightDistance > 0.0f ) ? ( straightFuel / straightDistance ) : -1.0f;

		yield return Frames( 30 );

		yield return HyperspaceFuelOnHeading( new Vector3( 1.0f, 0.0f, 1.0f ), 4.0f, measured );

		var diagonalFuel = measured[ 0 ];
		var diagonalDistance = measured[ 1 ];
		var diagonalRate = ( diagonalDistance > 0.0f ) ? ( diagonalFuel / diagonalDistance ) : -1.0f;

		Log( "hyperspacefuel: class 1 engines: straight " + straightFuel.ToString( "0.0000" ) + " m3 over " + straightDistance.ToString( "0.000" ) + " coordinates (" + straightRate.ToString( "0.000" ) + " a coordinate), diagonal " + diagonalFuel.ToString( "0.0000" ) + " m3 over " + diagonalDistance.ToString( "0.000" ) + " along the longer axis (" + diagonalRate.ToString( "0.000" ) + "); location " + playerData.m_general.m_location );

		Check( "hyperspacefuel: class 1 engines burn 0.48 m3 a coordinate flying straight along an axis (control)", ( straightRate > 0.456f ) && ( straightRate < 0.504f ), straightRate.ToString( "0.000" ) );
		Check( "hyperspacefuel: on the diagonal they burn the same 0.48 m3 a coordinate of the longer axis, not 1.41 times it", ( diagonalRate > 0.456f ) && ( diagonalRate < 0.504f ), diagonalRate.ToString( "0.000" ) + " (straight " + straightRate.ToString( "0.000" ) + ")" );

		// ---- 2. class 2 engines with the Tesseract: 5 hundredths a step halved to 2
		ship.m_enginesClass = 2;
		ship.AddArtifact( tesseractId );

		yield return Frames( 30 );

		yield return HyperspaceFuelOnHeading( new Vector3( 0.0f, 0.0f, 1.0f ), 4.0f, measured );

		var tesseractRate = ( measured[ 1 ] > 0.0f ) ? ( measured[ 0 ] / measured[ 1 ] ) : -1.0f;
		var estimate = ship.GetFuelForDistance( 10.0f );

		Log( "hyperspacefuel: class 2 engines with the Tesseract: " + measured[ 0 ].ToString( "0.0000" ) + " m3 over " + measured[ 1 ].ToString( "0.000" ) + " coordinates (" + tesseractRate.ToString( "0.000" ) + " a coordinate), the starmap's estimate for 10 coordinates " + estimate.ToString( "0.00" ) );

		Check( "hyperspacefuel: with the Tesseract class 2 engines burn 2 hundredths a step, 0.16 m3 a coordinate (the original's whole hundredths, not 0.20)", ( tesseractRate > 0.152f ) && ( tesseractRate < 0.168f ), tesseractRate.ToString( "0.000" ) );
		Check( "hyperspacefuel: the starmap's estimate goes by the same step (1.6 m3 for 10 coordinates)", Mathf.Abs( estimate - 1.6f ) < 0.001f, estimate.ToString( "0.000" ) );

		ship.RemoveArtifact( tesseractId );
		ship.m_enginesClass = 1;
		controller.m_encounterRange = encounterRange;

		Finish( "scenario=hyperspacefuel checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// puts the ship onto the near end of a flux in hyperspace and waits until it has jumped - gives back the seconds of play since the jump began
	static IEnumerator FluxJumpFrom( GD_Flux flux, bool[] jumped )
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;

		controller.m_playerShip.TurnOffEngines();
		playerData.m_general.m_currentSpeed = 0.0f;
		playerData.m_general.m_coordinates = flux.GetFrom();
		controller.m_playerShip.transform.position = flux.GetFrom();

		jumped[ 0 ] = false;

		for ( var frame = 0; ( frame < 30 ) && !jumped[ 0 ]; frame++ )
		{
			yield return null;

			jumped[ 0 ] = Equals( GetField( controller.m_hyperspace, "m_travelingThroughFlux" ), true );
		}
	}

	// a flux jump is the original's (HYPER-OV >FLUX-NODE, JMPSHP): instant, with the ship a step of 4 of the original's units (128) off the far end in one of the
	// eight directions, and the navigator loses the ship's bearings for (250 - skill) half seconds: meanwhile the starmap says "I can't get our bearings, captain."
	// (MAP-OV (/STARMAP), WEC57) and the coordinates above the main view are anything (.COORDINATES while ?CAN-NAVIGATE is false); a navigator of skill 250 keeps
	// them (the control)
	IEnumerator ScenarioFluxJump()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var controller = SpaceflightController.m_instance;
		var flux = gameData.m_fluxList[ 0 ];
		var jumped = new bool[ 1 ];

		EnsureCrew();

		var navigator = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.Navigator );

		playerData.m_playerShip.AddElement( 5, 500 );

		// out in hyperspace a little way from the flux, with no encounter able to begin
		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		playerData.m_general.m_lastHyperspaceCoordinates = flux.GetFrom() + new Vector3( 1024.0f, 0.0f, 0.0f );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		// ---- 1. a navigator of skill 250: the ship is at the far end at once, and the starmap works once the warp effect is over
		navigator.m_navigation = 250;

		yield return FluxJumpFrom( flux, jumped );
		yield return Frames( 2 );

		var offset = controller.m_playerShip.transform.position - flux.GetTo();
		var offAxisOrDiagonal = ( Mathf.Abs( Mathf.Abs( offset.x ) - 128.0f ) < 1.0f || Mathf.Abs( offset.x ) < 1.0f ) && ( Mathf.Abs( Mathf.Abs( offset.z ) - 128.0f ) < 1.0f || Mathf.Abs( offset.z ) < 1.0f ) && ( offset.magnitude > 100.0f );

		Log( "fluxjump: flux 0 from " + Tools.WorldToGameCoordinates( flux.GetFrom() ) + " to " + Tools.WorldToGameCoordinates( flux.GetTo() ) + ": jumped " + jumped[ 0 ] + ", 2 frames later the ship is " + offset + " from the far end (" + offset.magnitude.ToString( "0" ) + " units)" );

		Check( "fluxjump: flying into a flux the ship is at its far end at once, a step of 128 off it along an axis or a diagonal", jumped[ 0 ] && offAxisOrDiagonal, jumped[ 0 ] + ", " + offset + " " + offset.magnitude.ToString( "0" ) );

		for ( var end = Time.time + 5.0f; ( Time.time < end ) && Equals( GetField( controller.m_hyperspace, "m_travelingThroughFlux" ), true ); )
		{
			yield return null;
		}

		controller.m_messages.Clear();

		new StarmapButton().Execute();

		var openedWithSkill250 = controller.m_starmap.IsOpen();

		controller.m_starmap.Hide();

		yield return Frames( 3 );

		Check( "fluxjump: with a navigator of skill 250 the starmap opens right after the jump (control)", openedWithSkill250, openedWithSkill250 + ", " + MessageList() );

		// ---- 2. a navigator of skill 240 loses the bearings for 5 s
		navigator.m_navigation = 240;

		yield return FluxJumpFrom( flux, jumped );

		var jumpTime = Time.time;

		Log( "fluxjump: just after the second jump: time " + Time.time.ToString( "0.00" ) + ", bearings lost until " + FieldOrNull( controller, "m_bearingsLostUntil" ) + ", navigator skill " + navigator.m_navigation + " (" + navigator.m_name + "), location " + playerData.m_general.m_location );

		for ( var end = Time.time + 5.0f; ( Time.time < end ) && Equals( GetField( controller.m_hyperspace, "m_travelingThroughFlux" ), true ); )
		{
			yield return null;
		}

		yield return Frames( 5 );

		var real = Tools.WorldToGameCoordinates( playerData.m_general.m_lastHyperspaceCoordinates );
		var realText = Mathf.RoundToInt( real.x ) + "   " + Mathf.RoundToInt( real.z );
		var shownWhileLost = controller.m_viewport.m_label.text;

		controller.m_messages.Clear();

		new StarmapButton().Execute();

		var openedWhileLost = controller.m_starmap.IsOpen();
		var refusal = MessageList();
		var lostAt = Time.time - jumpTime;

		controller.m_starmap.Hide();

		while ( Time.time < jumpTime + 5.5f )
		{
			yield return null;
		}

		yield return Frames( 3 );

		var shownAfter = controller.m_viewport.m_label.text;

		controller.m_messages.Clear();

		new StarmapButton().Execute();

		var openedAfter = controller.m_starmap.IsOpen();

		controller.m_starmap.Hide();

		Log( "fluxjump: navigator of skill 240: " + lostAt.ToString( "0.0" ) + " s after the jump the starmap opened " + openedWhileLost + " ('" + refusal + "') and the coordinates read '" + shownWhileLost + "' (really '" + realText + "'); at 5.5 s it opened " + openedAfter + " and they read '" + shownAfter + "'" );

		Check( "fluxjump: with a navigator of skill 240 the starmap is refused for a while after the jump: \"I can't get our bearings, captain.\"", jumped[ 0 ] && !openedWhileLost && refusal.Contains( "bearings" ), openedWhileLost + ", '" + refusal + "'" );
		Check( "fluxjump: meanwhile the coordinates above the main view are two numbers that are not the ship's", System.Text.RegularExpressions.Regex.IsMatch( shownWhileLost, "^[0-9]+   [0-9]+$" ) && ( shownWhileLost != realText ), "'" + shownWhileLost + "' / '" + realText + "'" );
		Check( "fluxjump: after (250 - 240) half seconds the bearings are back: the starmap opens and the coordinates are the ship's", openedAfter && ( shownAfter == realText ), openedAfter + ", '" + shownAfter + "' / '" + realText + "'" );

		navigator.m_navigation = 250;
		controller.m_encounterRange = encounterRange;

		Finish( "scenario=fluxjump checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the steps of the original's terrain vehicle between two places, in its kilometers: the longer of the east-west and north-south distances (a step is a map cell
	// along one axis or both; 6.4 km a degree of longitude, 5.3 a degree of latitude, as the port's display)
	static float ProbeSurfaceSteps( Vector3 from, Vector3 to )
	{
		Tools.WorldToLatLongCoordinates( from, out var fromLongitude, out var fromLatitude );
		Tools.WorldToLatLongCoordinates( to, out var toLongitude, out var toLatitude );

		var degreesEastWest = Mathf.Repeat( toLongitude - fromLongitude + 180.0f, 360.0f ) - 180.0f;

		return Mathf.Max( Mathf.Abs( degreesEastWest * 6.4f ), Mathf.Abs( ( toLatitude - fromLatitude ) * 5.3f ) );
	}

	// holds the surface's weather at this sky, rolled for the hour it is (so that no new hour changes it while it is measured)
	static void HoldWeather( PlanetWeather.Sky sky )
	{
		var general = DataController.m_instance.m_playerData.m_general;
		var skyField = typeof( PlanetWeather ).GetField( "s_sky", BindingFlags.NonPublic | BindingFlags.Static );
		var codeField = typeof( PlanetWeather ).GetField( "s_code", BindingFlags.NonPublic | BindingFlags.Static );
		var hoursLeftField = typeof( PlanetWeather ).GetField( "s_hoursLeft", BindingFlags.NonPublic | BindingFlags.Static );
		var hourField = typeof( PlanetWeather ).GetField( "s_rolledHour", BindingFlags.NonPublic | BindingFlags.Static );

		if ( hourField != null )
		{
			hourField.SetValue( null, general.m_day * 24 + general.m_hour );
		}

		if ( skyField != null )
		{
			skyField.SetValue( null, sky );
		}

		// (the weather is the original's code since the storms were redone: 0 clear, 10 a windstorm, held for the spell)
		if ( codeField != null )
		{
			codeField.SetValue( null, ( sky == PlanetWeather.Sky.Windstorm ) ? 10 : ( sky == PlanetWeather.Sky.ElectricalStorm ) ? 6 : ( sky == PlanetWeather.Sky.SnowingHeavily ) ? 11 : 0 );
		}

		if ( hoursLeftField != null )
		{
			hoursLeftField.SetValue( null, 12 );
		}
	}

	// drives the terrain vehicle with its engines on from this place in this direction for some seconds of play under this sky - gives back the fuel used (of the
	// full tank), the original's steps driven and the distance (in units)
	static IEnumerator DriveMeasuringFuel( Vector3 start, Vector3 direction, float seconds, PlanetWeather.Sky sky, float[] fuelStepsDistance )
	{
		var playerData = DataController.m_instance.m_playerData;
		var general = playerData.m_general;
		var vehicle = SpaceflightController.m_instance.m_terrainVehicle;

		// (Move, while it runs, turns the engines off whenever the stick is centered)
		if ( GetField( SpaceflightController.m_instance.m_buttonController, "m_currentButton" ) is MoveButton )
		{
			SpaceflightController.m_instance.m_buttonController.DeactivateButton();
		}

		vehicle.TurnOffEngines();
		general.m_currentSpeed = 0.0f;
		general.m_coordinates = start;
		general.m_lastDisembarkedCoordinates = start;
		vehicle.transform.localPosition = start;
		general.m_currentDirection = direction;
		playerData.m_terrainVehicle.m_fuelRemaining = 1.0f;

		HoldWeather( sky );

		yield return Frames( 3 );

		var from = general.m_coordinates;
		var fuelBefore = playerData.m_terrainVehicle.m_fuelRemaining;

		vehicle.TurnOnEngines();

		for ( var end = Time.time + seconds; Time.time < end; )
		{
			// (at a set speed, as the uphill scenario drives: the vehicle's acceleration comes from the ship's)
			general.m_currentDirection = direction;
			general.m_currentSpeed = 10.0f;

			HoldWeather( sky );

			yield return null;
		}

		var to = general.m_coordinates;

		fuelStepsDistance[ 0 ] = fuelBefore - playerData.m_terrainVehicle.m_fuelRemaining;

		vehicle.TurnOffEngines();
		general.m_currentSpeed = 0.0f;

		var delta = to - from;

		delta.y = 0.0f;

		fuelStepsDistance[ 1 ] = ProbeSurfaceSteps( from, to );
		fuelStepsDistance[ 2 ] = delta.magnitude;

		yield return Frames( 5 );
	}

	// the terrain vehicle burns its fuel as the original's (MOVE-OV SET-SPEED and WF29C): at every step, a map cell (a kilometer of the display), E/M times 100 over
	// the weather's %EFF of a tank of 30767 above its reserve - E/M is 170 in a liquid, so there a step takes 170 whatever the place, a storm (%EFF 50) makes each
	// step dear twice over and leaves the speed alone, land costs one and a half times its contour (16 to 127), and the tank is empty only at 6.5% below its 0%
	IEnumerator ScenarioTerrainVehicleFuel()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var general = playerData.m_general;
		var done = new bool[ 1 ];

		EnsureCrew();
		ProbeKeyboard();

		// planet 92 of the Arth system, which has seas
		yield return LandInTheArthSystemAt( 92, Vector3.zero, done );

		var populator = FieldOrNull( controller.m_disembarked.m_terrainGrid, "m_terrainLifeforms" ) as TerrainLifeforms;
		var planetGenerator = controller.m_starSystem.GetPlanetController( general.m_currentPlanetId ).GetPlanetGenerator();

		if ( ( populator == null ) || ( planetGenerator == null ) || ( general.m_location != PD_General.Location.Disembarked ) )
		{
			Finish( "scenario=tvfuel abort: not out in the terrain vehicle (" + general.m_location + ")", 2 );
			yield break;
		}

		var start = general.m_coordinates;
		var waterLevel = planetGenerator.m_waterElevation * controller.m_terrainVehicle.m_elevationScale;

		// a stretch of sea near the landing place: a place and a direction with liquid under the next 60 units, the farther from the shore the better
		var seaPlace = Vector3.zero;
		var seaDirection = Vector3.forward;
		var seaFound = false;

		for ( var ring = 1; ( ring <= 40 ) && !seaFound; ring++ )
		{
			for ( var i = 0; ( i < 16 ) && !seaFound; i++ )
			{
				var angle = i * 22.5f * Mathf.Deg2Rad;
				var place = start + new Vector3( Mathf.Sin( angle ), 0.0f, Mathf.Cos( angle ) ) * ring * 40.0f;

				for ( var d = 0; ( d < 8 ) && !seaFound; d++ )
				{
					var dAngle = d * 45.0f * Mathf.Deg2Rad;
					var direction = new Vector3( Mathf.Sin( dAngle ), 0.0f, Mathf.Cos( dAngle ) );
					var allSea = true;

					for ( var k = -20; ( k <= 80 ) && allSea; k += 4 )
					{
						// (over a liquid GetGround says no, and gives the liquid's surface; off the maps it gives 0)
						allSea = !populator.GetGround( place + direction * k, out var ground ) && ( ground > 0.0f );
					}

					if ( allSea )
					{
						seaPlace = place;
						seaDirection = direction;
						seaFound = true;
					}
				}
			}
		}

		Log( "tvfuel: planet " + general.m_currentPlanetId + ", water level " + waterLevel.ToString( "0.0" ) + ", a stretch of sea " + ( seaFound ? "at " + seaPlace + " towards " + seaDirection + " (" + Vector3.Distance( start, seaPlace ).ToString( "0" ) + " from the landing place)" : "not found" ) );

		Check( "tvfuel: there is a stretch of sea near the landing place to drive on (control)", seaFound, seaFound.ToString() );

		if ( !seaFound )
		{
			Finish( "scenario=tvfuel checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
			yield break;
		}

		// ---- 1. on the sea, clear: 170 a step
		var measured = new float[ 3 ];

		yield return DriveMeasuringFuel( seaPlace, seaDirection, 2.0f, PlanetWeather.Sky.Clear, measured );

		var clearFuel = measured[ 0 ];
		var clearSteps = measured[ 1 ];
		var clearDistance = measured[ 2 ];
		var clearPerStep = ( clearSteps > 0.0f ) ? ( clearFuel / clearSteps * 30767.0f ) : -1.0f;

		// ---- 2. the same in a windstorm
		yield return DriveMeasuringFuel( seaPlace, seaDirection, 2.0f, PlanetWeather.Sky.Windstorm, measured );

		var stormPerStep = ( measured[ 1 ] > 0.0f ) ? ( measured[ 0 ] / measured[ 1 ] * 30767.0f ) : -1.0f;
		var stormDistance = measured[ 2 ];

		Log( "tvfuel: on the sea, clear: " + clearFuel.ToString( "0.00000" ) + " of the tank over " + clearSteps.ToString( "0.00" ) + " steps (" + clearDistance.ToString( "0.0" ) + " units): " + clearPerStep.ToString( "0.0" ) + " a step; in a windstorm " + stormPerStep.ToString( "0.0" ) + " a step over " + stormDistance.ToString( "0.0" ) + " units" );

		Check( "tvfuel: on a sea a step of the vehicle takes 170 of the tank's 30767 (E/M in a liquid, whatever the place)", ( clearPerStep > 161.5f ) && ( clearPerStep < 178.5f ), clearPerStep.ToString( "0.0" ) );
		Check( "tvfuel: in a storm each step takes twice as much (%EFF 50)", ( clearPerStep > 0.0f ) && ( stormPerStep / clearPerStep > 1.9f ) && ( stormPerStep / clearPerStep < 2.1f ), stormPerStep.ToString( "0.0" ) + " / " + clearPerStep.ToString( "0.0" ) );
		Check( "tvfuel: and the storm does not slow the vehicle down", ( clearDistance > 1.0f ) && ( stormDistance / clearDistance > 0.95f ) && ( stormDistance / clearDistance < 1.05f ), stormDistance.ToString( "0.0" ) + " / " + clearDistance.ToString( "0.0" ) );

		// ---- 3. on land near the landing place (the control: one and a half times a contour of 16 to 127)
		var landPlace = start;
		var landDirection = Vector3.forward;
		var landFound = false;

		for ( var ring = 0; ( ring <= 40 ) && !landFound; ring++ )
		{
			for ( var i = 0; ( i < 16 ) && !landFound; i++ )
			{
				var angle = i * 22.5f * Mathf.Deg2Rad;
				var place = start + new Vector3( Mathf.Sin( angle ), 0.0f, Mathf.Cos( angle ) ) * ring * 40.0f;

				for ( var d = 0; ( d < 8 ) && !landFound; d++ )
				{
					var dAngle = d * 45.0f * Mathf.Deg2Rad;
					var direction = new Vector3( Mathf.Sin( dAngle ), 0.0f, Mathf.Cos( dAngle ) );
					var allLand = true;

					for ( var k = -10; ( k <= 60 ) && allLand; k += 4 )
					{
						allLand = populator.GetGround( place + direction * k, out var ground ) && ( ground > waterLevel + 2.0f );
					}

					if ( allLand )
					{
						landPlace = place;
						landDirection = direction;
						landFound = true;
					}
				}
			}
		}

		yield return DriveMeasuringFuel( landPlace, landDirection, 2.0f, PlanetWeather.Sky.Clear, measured );

		var landPerStep = ( measured[ 1 ] > 0.0f ) ? ( measured[ 0 ] / measured[ 1 ] * 30767.0f ) : -1.0f;

		Log( "tvfuel: on land (" + landFound + ") at " + landPlace + " towards " + landDirection + ": " + landPerStep.ToString( "0.0" ) + " a step over " + measured[ 1 ].ToString( "0.00" ) + " steps" );

		Check( "tvfuel: on land a step takes one and a half times the contour, 24 to 190 (control)", landFound && ( landPerStep >= 23.0f ) && ( landPerStep <= 191.0f ), landFound + ", " + landPerStep.ToString( "0.0" ) );

		// ---- 4. the reserve: at 6% below the display's 0% the vehicle still drives, at 7% it is out of fuel
		general.m_coordinates = start;
		general.m_lastDisembarkedCoordinates = start;
		controller.m_terrainVehicle.transform.localPosition = start;
		general.m_currentDirection = landDirection;
		playerData.m_terrainVehicle.m_fuelRemaining = -0.06f;
		playerData.m_general.m_messageList.Clear();

		yield return Frames( 5 );

		PressButton( ButtonController.ButtonSet.TerrainVehicle, 1 );

		for ( var end = Time.time + 0.5f; Time.time < end; )
		{
			yield return null;
		}

		var at6 = System.Text.RegularExpressions.Regex.Replace( string.Join( " | ", general.m_messageList ), "<[^>]*>", "" );
		var drivingAt6 = !at6.Contains( "Out of fuel." ) && ( general.m_location == PD_General.Location.Disembarked );

		playerData.m_terrainVehicle.m_fuelRemaining = -0.07f;

		for ( var end = Time.time + 1.0f; ( Time.time < end ) && ( general.m_location == PD_General.Location.Disembarked ); )
		{
			yield return null;
		}

		var at7 = System.Text.RegularExpressions.Regex.Replace( string.Join( " | ", general.m_messageList ), "<[^>]*>", "" );

		Log( "tvfuel: at -6% the messages read '" + at6 + "'; at -7% '" + at7 + "', location " + general.m_location );

		Check( "tvfuel: at 6% below the display's 0% the vehicle still drives on its reserve (the original's tank is empty at 6.5%)", drivingAt6, at6 );
		Check( "tvfuel: at 7% below it the vehicle is out of fuel (control)", at7.Contains( "Out of fuel." ), at7 );

		Finish( "scenario=tvfuel checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// moves the game clock on by whole star hours (the aliens' moves go by the hours the clock shows)
	static void AdvanceGameHours( int hours )
	{
		var general = DataController.m_instance.m_playerData.m_general;

		general.m_hour += hours;

		while ( general.m_hour >= 24 )
		{
			general.m_hour -= 24;
			general.m_day++;
		}
	}

	// puts a group of aliens this many coordinates east of the ship in hyperspace, with its home this many coordinates west of where it is now
	static void PlaceAlienGroup( PD_Encounter pdEncounter, float coordinatesEast, float homeCoordinatesWest )
	{
		var ship = DataController.m_instance.m_playerData.m_general.m_coordinates;

		pdEncounter.m_currentCoordinates = ship + new Vector3( coordinatesEast * 256.0f, 0.0f, 0.0f );
		pdEncounter.m_homeCoordinates = pdEncounter.m_currentCoordinates - new Vector3( homeCoordinatesWest * 256.0f, 0.0f, 0.0f );
	}

	// the distance from the ship to a group of aliens, in hyperspace coordinates
	static float AlienGroupCoordinates( PD_Encounter pdEncounter )
	{
		var ship = DataController.m_instance.m_playerData.m_general.m_coordinates;

		return Vector3.Distance( ship, pdEncounter.m_currentCoordinates ) / 256.0f;
	}

	// the aliens come after the ship as the original's (HYPERMSG-OV TRAK-E, run by TRAK-ENCS every 2 star hours): not at all between the moves, then in hyperspace half
	// the way along each axis in whole coordinates (5 coordinates away: 2 nearer), the whole way when that comes to none (1.5 away: onto the ship), and only the
	// groups of the region around the ship (12 coordinates away: none)
	IEnumerator ScenarioAlienPursuit()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var general = playerData.m_general;

		EnsureCrew();

		// in hyperspace, in a quiet corner, the ship standing still, with no encounter able to begin while the aliens are watched
		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 20.0f, 0.0f, 20.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		controller.m_playerShip.TurnOffEngines();
		general.m_currentSpeed = 0.0f;

		var pdEncounter = playerData.FindEncounter( FindEncounter( 0, 1, 1, 0 ) );

		// (no hour to come of itself while the aliens are watched: a star hour is 10 s)
		general.m_minute = 0;
		general.m_second = 0;

		yield return Frames( 10 );

		// ---- 1. 5 coordinates away: nothing for an hour, then 2 coordinates nearer at the second hour
		PlaceAlienGroup( pdEncounter, 5.0f, 0.0f );

		AdvanceGameHours( 1 );

		for ( var end = Time.time + 1.0f; Time.time < end; )
		{
			yield return null;
		}

		var afterAnHour = AlienGroupCoordinates( pdEncounter );

		AdvanceGameHours( 1 );

		yield return Frames( 3 );

		var afterTwoHours = AlienGroupCoordinates( pdEncounter );

		// ---- 2. 1.5 coordinates away: onto the ship
		general.m_minute = 0;
		general.m_second = 0;

		PlaceAlienGroup( pdEncounter, 1.5f, 0.0f );

		AdvanceGameHours( 2 );

		yield return Frames( 3 );

		var landed = AlienGroupCoordinates( pdEncounter );

		// ---- 3. 12 coordinates away, beyond the region around the ship: they stay (the control)
		general.m_minute = 0;
		general.m_second = 0;

		PlaceAlienGroup( pdEncounter, 12.0f, 0.0f );

		AdvanceGameHours( 2 );

		yield return Frames( 3 );

		var farAway = AlienGroupCoordinates( pdEncounter );

		controller.m_encounterRange = encounterRange;

		Log( "alienpursuit: a group 5 coordinates away is " + afterAnHour.ToString( "0.000" ) + " away after a star hour and " + afterTwoHours.ToString( "0.000" ) + " after two; one 1.5 away is " + landed.ToString( "0.000" ) + " away after two hours; one 12 away is " + farAway.ToString( "0.000" ) + " away" );

		Check( "alienpursuit: between the moves of every 2 star hours the aliens stay where they are", Mathf.Abs( afterAnHour - 5.0f ) < 0.01f, afterAnHour.ToString( "0.000" ) );
		Check( "alienpursuit: at the move a group 5 coordinates away comes half the way along the axis in whole coordinates, 2 nearer", Mathf.Abs( afterTwoHours - 3.0f ) < 0.01f, afterTwoHours.ToString( "0.000" ) );
		Check( "alienpursuit: a group 1.5 coordinates away comes the whole way, onto the ship (half of it is no whole coordinate)", landed < 0.01f, landed.ToString( "0.000" ) );
		Check( "alienpursuit: a group 12 coordinates away, beyond the region around the ship, does not move (control)", Mathf.Abs( farAway - 12.0f ) < 0.01f, farAway.ToString( "0.000" ) );

		Finish( "scenario=alienpursuit checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the ship's speeds in flight as the original's (HYPER-OV CSPEED, !MAXSPEED, ACCELERATE), for class 5 engines (D8 gives lower classes less): in a star system the
	// step grows from 1 to 12 of the system's units, to a top speed of 12 units a step at the original's 12.2 steps a second at GOG's speed (2998 of the port's units
	// a second); in hyperspace 371.2; with no direction held the ship stops at once; and the engines' health does not change the speed, though destroyed engines move
	// nothing (DAMAGE-OV WF2AC)
	IEnumerator ScenarioShipSpeeds()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var general = playerData.m_general;
		var starSystem = controller.m_starSystem;

		EnsureCrew();

		// a ship that survives whatever it meets, and no encounter able to begin
		playerData.m_playerShip.m_armorPoints = 100000;

		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		SetSystemHealth( 0, 100 );

		// class 5 engines, whose top speeds are the original's at GOG's pace (D8), in a ship of 5 G (16 pods, class 5 armor), which gets there in a second as the
		// original's 12 steps do
		FitShip( 5, 16, 5 );

		// ---- 1. the star system of Arth, after Maneuver from the Starport
		controller.SwitchLocation( PD_General.Location.JustLaunched );

		for ( var end = Time.realtimeSinceStartup + 60.0f; ( Time.realtimeSinceStartup < end ) && starSystem.GeneratingPlanets(); )
		{
			yield return null;
		}

		yield return Frames( 10 );

		PressButton( ButtonController.ButtonSet.NavigationA, 0 );

		yield return Frames( 10 );

		// (Maneuver, while it runs, turns the engines off when no direction is held)
		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		yield return Frames( 3 );

		var inStarSystem = general.m_location == PD_General.Location.StarSystem;

		general.m_currentSpeed = 0.0f;
		general.m_currentDirection = Vector3.right;

		controller.m_playerShip.TurnOnEngines();

		yield return Frames( 2 );

		var firstSteps = general.m_currentSpeed;

		// (the step grows from 1 to 12 in 11 / 12.2 = 0.9 s, and at the top speed the ship crosses from Arth's orbit to the system's edge in about 3 s)
		for ( var end = Time.time + 1.5f; Time.time < end; )
		{
			general.m_currentDirection = Vector3.right;

			yield return null;
		}

		var systemTop = general.m_currentSpeed;
		var stillInStarSystem = general.m_location == PD_General.Location.StarSystem;

		controller.m_playerShip.TurnOffEngines();

		yield return Frames( 3 );

		var systemStopped = general.m_currentSpeed;

		Log( "shipspeeds: in the star system (" + general.m_location + "): " + firstSteps.ToString( "0.0" ) + " two frames after the engines went on, " + systemTop.ToString( "0.0" ) + " after 1.5 s, " + systemStopped.ToString( "0.0" ) + " three frames after they went off" );

		Check( "shipspeeds: in a star system the ship starts at a twelfth of its top speed or more, and less than half of it (the original's step grows from 1 to 12)", inStarSystem && ( firstSteps >= 2998.272f / 12.0f - 0.01f ) && ( firstSteps < 2998.272f / 2.0f ), firstSteps.ToString( "0.0" ) );
		Check( "shipspeeds: its top speed in a star system is 12 units of 20.48 a step at the original's 12.2 steps a second at GOG's speed (2998.3)", stillInStarSystem && ( Mathf.Abs( systemTop - 2998.272f ) < 0.5f ), systemTop.ToString( "0.0" ) );
		Check( "shipspeeds: with no direction held it stops at once", systemStopped == 0.0f, systemStopped.ToString( "0.0" ) );

		// ---- 2. hyperspace, in a quiet corner
		general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 6.0f, 0.0f, 6.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		general.m_currentSpeed = 0.0f;
		general.m_currentDirection = Vector3.right;

		controller.m_playerShip.TurnOnEngines();

		// (the speed grows in hyperspace too since D8, here in a second)
		for ( var end = Time.time + 1.5f; Time.time < end; )
		{
			yield return null;
		}

		var hyperspaceAtOnce = general.m_currentSpeed;

		SetSystemHealth( 0, 50 );

		yield return Frames( 3 );

		var hyperspaceHalfEngines = general.m_currentSpeed;

		SetSystemHealth( 0, 0 );

		yield return Frames( 3 );

		var hyperspaceNoEngines = general.m_currentSpeed;

		SetSystemHealth( 0, 100 );

		controller.m_playerShip.TurnOffEngines();
		controller.m_encounterRange = encounterRange;

		Log( "shipspeeds: in hyperspace: " + hyperspaceAtOnce.ToString( "0.0" ) + " 1.5 s after the engines went on, " + hyperspaceHalfEngines.ToString( "0.0" ) + " with the engines at half health, " + hyperspaceNoEngines.ToString( "0.0" ) + " with them destroyed" );

		Check( "shipspeeds: in hyperspace class 5 engines' top speed is the original's 11.6 steps of 32 a second at GOG's speed (371.2)", Mathf.Abs( hyperspaceAtOnce - 371.2f ) < 0.05f, hyperspaceAtOnce.ToString( "0.0" ) );
		Check( "shipspeeds: engines at half health do not slow the ship (the original's engine damage counts only in an encounter)", Mathf.Abs( hyperspaceHalfEngines - 371.2f ) < 0.05f, hyperspaceHalfEngines.ToString( "0.0" ) );
		Check( "shipspeeds: destroyed engines move nothing (DAMAGE-OV WF2AC; the old code left the ship at the speed it had)", hyperspaceNoEngines < 0.01f, hyperspaceNoEngines.ToString( "0.0" ) );

		Finish( "scenario=shipspeeds checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the first wave of an encounter is the original's (HYPERMSG-OV +A-VESS): from 2 fewer than the encounter's ships at a time up to that many, at random, and at
	// least one - a Spemin encounter of 6 ships, 3 at a time, entered 30 times, comes with 1, 2 and 3 ships, never more (the old code always brought 3)
	IEnumerator ScenarioEncounterWaves()
	{
		var gameData = DataController.m_instance.m_gameData;
		var encounterId = FindEncounter( 1, 6, 3, 0 );
		var counts = new int[ 5 ];
		var outside = 0;

		EnsureCrew();

		for ( var entry = 0; entry < 30; entry++ )
		{
			EnterEncounterRaw( encounterId );
			yield return Frames( 5 );

			var present = 0;

			foreach ( var alienShip in SpaceflightController.m_instance.m_encounter.m_pdEncounter.GetAlienShipList() )
			{
				if ( alienShip.m_addedToEncounter && !alienShip.m_isDead )
				{
					present++;
				}
			}

			if ( ( present >= 1 ) && ( present <= 3 ) )
			{
				counts[ present ]++;
			}
			else
			{
				outside++;
			}

			ClearMissiles();
			LeaveEncounter();
			yield return Frames( 5 );
		}

		Log( "encounterwaves: encounter " + encounterId + " (" + gameData.m_encounterList[ encounterId ].m_maxNumShipsAtOnce + " at a time): first waves of 1 ship " + counts[ 1 ] + ", 2 ships " + counts[ 2 ] + ", 3 ships " + counts[ 3 ] + ", other " + outside + " in 30 entries" );

		Check( "encounterwaves: a first wave is never more than the encounter's ships at a time, nor none", outside == 0, outside.ToString() );
		Check( "encounterwaves: first waves of 1, 2 and 3 ships all come (the original's M - 2 to M, not always M)", ( counts[ 1 ] > 0 ) && ( counts[ 2 ] > 0 ) && ( counts[ 3 ] > 0 ), counts[ 1 ] + "/" + counts[ 2 ] + "/" + counts[ 3 ] );

		Finish( "scenario=encounterwaves checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the aliens' distress call (COMM-OV <AUX> CALL-FOR-SHIPS, SHIPS-ARRIVE)

	// leaves this many of the encounter's added living ships in it (the others out of it, as not yet come), the aliens hostile and no call pending
	static void KeepAlienShips( int keep )
	{
		var encounter = SpaceflightController.m_instance.m_encounter;
		var kept = 0;

		foreach ( var alienShip in encounter.m_pdEncounter.GetAlienShipList() )
		{
			alienShip.m_isDead = false;

			if ( alienShip.m_addedToEncounter && ( kept < keep ) )
			{
				kept++;
			}
			else
			{
				alienShip.m_addedToEncounter = false;
			}
		}

		// (a ship that is not in it yet is put in when the probe needs it)
		foreach ( var alienShip in encounter.m_pdEncounter.GetAlienShipList() )
		{
			if ( kept >= keep )
			{
				break;
			}

			if ( !alienShip.m_addedToEncounter )
			{
				alienShip.m_addedToEncounter = true;
				alienShip.m_coordinates = new Vector3( 1000.0f, 0.0f, 1000.0f );
				kept++;
			}
		}

		encounter.m_pdEncounter.m_alienStance = GD_Comm.Stance.Hostile;

		var called = typeof( PD_Encounter ).GetField( "m_distressCalled" );

		if ( called != null )
		{
			called.SetValue( encounter.m_pdEncounter, false );
		}
	}

	// the living ships in the encounter
	static int AlienShipsPresent()
	{
		var present = 0;

		foreach ( var alienShip in SpaceflightController.m_instance.m_encounter.m_pdEncounter.GetAlienShipList() )
		{
			if ( alienShip.m_addedToEncounter && !alienShip.m_isDead )
			{
				present++;
			}
		}

		return present;
	}

	// runs the distress call's passes until one returns the wanted result (1 a call, 2 the ships warping in), at most a number of passes; -1 if it never did
	// (int.MinValue on the code before the distress call)
	static int PassesUntil( int wanted, int most )
	{
		var method = typeof( Encounter ).GetMethod( "DistressCallPass" );

		if ( method == null )
		{
			return int.MinValue;
		}

		for ( var pass = 1; pass <= most; pass++ )
		{
			if ( (int) method.Invoke( SpaceflightController.m_instance.m_encounter, null ) == wanted )
			{
				return pass;
			}
		}

		return -1;
	}

	// the aliens' distress call as the original's: a Spemin group (135, 6 ships, 3 at a time) of one hostile ship calls for help with a chance of 1 in 1500 a pass
	// (60 tries average 1000 to 2100 passes), and once it has called more ships warp in with a chance of 1 in 50 / 3 = 16 a pass (60 tries average 9 to 25),
	// as a new wave of 1 to 3, with the original's lines; neutral or friendly aliens, three ships, and a race that does not call (the Minstrels, 311) never call
	// (6000 passes each); the Thrynn home fleet (165) of one ship calls at its first pass
	IEnumerator ScenarioDistressCalls()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var encounter = controller.m_encounter;

		EnsureCrew();
		playerData.m_playerShip.m_armorPoints = 100000;
		controller.m_encounterRange = 0.0f;

		// ---- 1. Spemin group 135, one hostile ship: passes to the call, then to the ships warping in
		EnterEncounter( 135 );
		yield return Frames( 3 );

		var callPasses = new List<int>();
		var arrivePasses = new List<int>();
		var waveSizes = new List<int>();
		var callText = "";
		var arriveText = "";

		for ( var trial = 0; trial < 60; trial++ )
		{
			KeepAlienShips( 1 );
			controller.m_messages.Clear();

			var toCall = PassesUntil( 1, 20000 );

			callPasses.Add( toCall );

			if ( trial == 0 )
			{
				callText = MessageList();
			}

			controller.m_messages.Clear();

			var toArrive = PassesUntil( 2, 2000 );

			arrivePasses.Add( toArrive );
			waveSizes.Add( AlienShipsPresent() - 1 );

			if ( trial == 0 )
			{
				arriveText = MessageList();
			}
		}

		var calls = callPasses.FindAll( p => p > 0 );
		var arrivals = arrivePasses.FindAll( p => p > 0 );
		var callSum = 0;
		var arriveSum = 0;
		var waveMin = int.MaxValue;
		var waveMax = int.MinValue;

		foreach ( var p in calls )
		{
			callSum += p;
		}

		foreach ( var p in arrivals )
		{
			arriveSum += p;
		}

		foreach ( var w in waveSizes )
		{
			waveMin = Mathf.Min( waveMin, w );
			waveMax = Mathf.Max( waveMax, w );
		}

		var meanCall = ( calls.Count > 0 ) ? (float) callSum / calls.Count : 0.0f;
		var meanArrive = ( arrivals.Count > 0 ) ? (float) arriveSum / arrivals.Count : 0.0f;

		// ---- 2. the controls: neutral aliens, three ships, and the Minstrels
		KeepAlienShips( 1 );
		encounter.m_pdEncounter.m_alienStance = GD_Comm.Stance.Neutral;

		var neutral = PassesUntil( 1, 6000 );

		KeepAlienShips( 3 );

		var three = PassesUntil( 1, 6000 );

		LeaveEncounter();
		yield return Frames( 10 );

		EnterEncounter( 311 );
		yield return Frames( 3 );

		KeepAlienShips( 1 );

		var minstrel = PassesUntil( 1, 6000 );

		LeaveEncounter();
		yield return Frames( 10 );

		// ---- 3. the Thrynn home fleet (165, orbit 4 of 129,33), down to one ship: a call at the first pass
		var thrynnStar = StarAt( 129, 33 );

		yield return GoIntoOrbit( thrynnStar, PlanetInOrbit( thrynnStar, 4 ) );

		var homeBegun = ( playerData.m_general.m_location == PD_General.Location.Encounter ) && ( playerData.m_general.m_currentEncounterId == 165 );

		KeepAlienShips( 1 );

		var home = homeBegun ? PassesUntil( 1, 3 ) : -2;

		ClearMissiles();
		LeaveEncounter();
		yield return Frames( 10 );

		Log( "distresscalls: Spemin 135, one hostile ship, 60 tries: calls " + calls.Count + ", mean " + meanCall.ToString( "F0" ) + " passes; ships warped in " + arrivals.Count + ", mean " + meanArrive.ToString( "F1" ) + " passes, waves of " + waveMin + " to " + waveMax + " | call '" + callText + "' | arrival '" + arriveText + "' || neutral " + neutral + ", three ships " + three + ", Minstrels " + minstrel + " || Thrynn home fleet begun " + homeBegun + ", call at pass " + home );

		Check( "distresscalls: one hostile Spemin ship calls for help with a chance of 1 in 1500 a pass (COMM-OV WE80E), saying so", ( calls.Count == 60 ) && ( meanCall >= 1000.0f ) && ( meanCall <= 2100.0f ) && callText.Contains( "Captain, I'm picking up an alien distress call." ), calls.Count + " calls, mean " + meanCall.ToString( "F0" ) + " | " + callText );
		Check( "distresscalls: after the call more ships warp in with a chance of 1 in 16 a pass (WE850, 50 / 3), a new wave of 1 to 3 (+A-VESS), saying so", ( arrivals.Count == 60 ) && ( meanArrive >= 9.0f ) && ( meanArrive <= 25.0f ) && ( waveMin >= 1 ) && ( waveMax <= 3 ) && arriveText.Contains( "Captain, more alien ships have warped in." ), arrivals.Count + " arrivals, mean " + meanArrive.ToString( "F1" ) + ", waves " + waveMin + " to " + waveMax + " | " + arriveText );
		Check( "distresscalls: neutral aliens, three ships and a race that does not call never call (control)", ( neutral == -1 ) && ( three == -1 ) && ( minstrel == -1 ), neutral + " / " + three + " / " + minstrel );
		Check( "distresscalls: a home fleet calls at once (SPACIAL-CONTEXT 2)", home == 1, homeBegun + ", " + home );

		Finish( "scenario=distresscalls calls=" + calls.Count + " mean=" + meanCall.ToString( "F0" ) + " arrive=" + meanArrive.ToString( "F1" ), 0 );
	}

	// ---------------------------------------------------------------- the speeds in an encounter (COMBAT-OV COMBAT, HYPER-OV #VES-SPEED, ACCELERATE)

	// the path length an alien ship flies in this many seconds of game time, over the time
	// watches an alien ship's turns for this long: each time it is given a new cell, how far that is across and along in cells and how far short of its last cell it
	// still was. Fills result with the turns, the largest step's longer side in cells, the shortest step's (of those that moved), how far short a ship was at most
	// when its next turn came, and the diagonal steps
	static IEnumerator WatchAlienTurns( int alienIndex, float seconds, float[] result )
	{
		var ship = EncounterShip( alienIndex );
		var lastTarget = ship.m_targetCoordinates;
		var start = Time.time;
		var turns = 0;
		var largest = 0.0f;
		var shortest = float.MaxValue;
		var mostShort = 0.0f;
		var diagonals = 0;

		while ( Time.time - start < seconds )
		{
			var before = ship.m_coordinates;

			yield return null;

			if ( ( ship.m_targetCoordinates - lastTarget ).sqrMagnitude < 0.01f )
			{
				continue;
			}

			// a new cell: the step from the last one, and how far from that one the ship was in the frame before
			var step = ( ship.m_targetCoordinates - lastTarget ) / CombatController.c_unitsPerCell;
			var longer = Mathf.Max( Mathf.Abs( step.x ), Mathf.Abs( step.z ) );

			turns++;
			largest = Mathf.Max( largest, longer );
			shortest = Mathf.Min( shortest, longer );
			mostShort = Mathf.Max( mostShort, Vector3.Distance( before, lastTarget ) );

			if ( ( Mathf.Abs( step.x ) > 0.5f ) && ( Mathf.Abs( step.z ) > 0.5f ) )
			{
				diagonals++;
			}

			lastTarget = ship.m_targetCoordinates;
		}

		result[ 0 ] = turns;
		result[ 1 ] = largest;
		result[ 2 ] = ( turns > 0 ) ? shortest : 0.0f;
		result[ 3 ] = mostShort;
		result[ 4 ] = diagonals;
	}

	// the turns watched are whole cells (at least one), and a ship was never more than a frame's way short of its cell when its next turn came
	static bool TurnsAreWholeCells( float[] turns )
	{
		return ( turns[ 0 ] >= 1.0f ) && ( Mathf.Abs( turns[ 1 ] - 1.0f ) < 0.05f ) && ( Mathf.Abs( turns[ 2 ] - 1.0f ) < 0.05f ) && ( turns[ 3 ] < 6.0f );
	}

	static string TurnsText( float[] turns )
	{
		return turns[ 0 ].ToString( "F0" ) + " steps (cells " + turns[ 2 ].ToString( "F2" ) + " to " + turns[ 1 ].ToString( "F2" ) + ", " + turns[ 4 ].ToString( "F0" ) + " diagonal, short by " + turns[ 3 ].ToString( "F1" ) + " at most)";
	}

	// the seconds between an alien ship's turns (Encounter.GetTurnSeconds; -1 on code without it)
	static float AlienTurnSeconds()
	{
		var encounter = SpaceflightController.m_instance.m_encounter;
		var method = ( encounter != null ) ? typeof( Encounter ).GetMethod( "GetTurnSeconds", BindingFlags.Instance | BindingFlags.Public | BindingFlags.NonPublic ) : null;

		return ( method != null ) ? (float) method.Invoke( encounter, null ) : -1.0f;
	}

	static IEnumerator MeasureAlienSpeed( int alienIndex, float seconds, float[] result )
	{
		var ship = EncounterShip( alienIndex );
		var last = ship.m_coordinates;
		var path = 0.0f;
		var start = Time.time;

		while ( Time.time - start < seconds )
		{
			yield return null;

			path += Vector3.Distance( ship.m_coordinates, last );
			last = ship.m_coordinates;
		}

		result[ 0 ] = path / Mathf.Max( 0.001f, Time.time - start );
	}

	// holds a direction (turning round a circle, so the ship stays in the encounter) and samples the ship's path speed over the half seconds that end at the given
	// times of game time: the path of the frames that end in the window over the time those frames took (a frame that began before the window counts its whole
	// path and its whole time, so the speed is right whatever the frames' lengths)
	static IEnumerator MeasurePlayerSpeeds( float[] times, float[] speeds )
	{
		var controller = SpaceflightController.m_instance;
		var general = DataController.m_instance.m_playerData.m_general;
		var start = Time.time;
		var last = general.m_coordinates;
		var window = new List<KeyValuePair<float, Vector2>>();

		controller.m_playerShip.TurnOnEngines();

		for ( var i = 0; i < times.Length; i++ )
		{
			while ( Time.time - start < times[ i ] )
			{
				var t = Time.time - start;

				general.m_currentDirection = new Vector3( Mathf.Cos( t ), 0.0f, Mathf.Sin( t ) );

				yield return null;

				window.Add( new KeyValuePair<float, Vector2>( Time.time - start, new Vector2( Vector3.Distance( general.m_coordinates, last ), Time.deltaTime ) ) );
				last = general.m_coordinates;
			}

			var path = 0.0f;
			var took = 0.0f;
			var from = times[ i ] - 0.5f;

			foreach ( var kv in window )
			{
				if ( kv.Key > from )
				{
					path += kv.Value.x;
					took += kv.Value.y;
				}
			}

			speeds[ i ] = ( took > 0.0f ) ? path / took : 0.0f;
		}
	}

	// the speeds in an encounter as the original's: an alien ship moves a cell (80) every (ships + 1) passes of a quarter of a second, 160 a second with one ship
	// and 80 with three; the player's ship (7 G) moves a cell a pass at first (320) and a cell more every 96 / 7 + 1 = 14 passes (640 from 3.5 s, 960 from 7),
	// up to 6 cells with one alien ship and 2 with three, and stops at once with no direction held
	IEnumerator ScenarioEncounterSpeeds()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;

		EnsureCrew();
		playerData.m_playerShip.m_armorPoints = 100000;
		playerData.m_playerShip.m_acceleration = 7;
		controller.m_encounterRange = 0.0f;
		SetSystemHealth( 0, 100 );

		// game time a sixtieth of a second a frame, however slowly the frames come: the speeds are measured over windows of game time, and one long frame under
		// load (another Unity running, up to Time.maximumDeltaTime) counted its whole path in a window it only ended in (755 for 640 in a full run, 641 alone)
		Time.captureDeltaTime = 1.0f / 60.0f;

		// ---- 1. Spemin encounter 96, one ship
		EnterEncounter( 96 );
		yield return Frames( 5 );

		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		var oneTurns = new float[ 5 ];

		yield return WatchAlienTurns( FirstLivingAlien(), 4.0f, oneTurns );

		var oneTurnSeconds = AlienTurnSeconds();

		// in the Combat menu, as in a fight: out of it the encounter ends by itself once the aliens are over 22 cells away (the original's ?UNNEST), and they move
		// off by their posture while the player's ship circles
		controller.m_buttonController.ChangeButtonSet( ButtonController.ButtonSet.Combat );

		var times = new[] { 0.75f, 5.0f, 9.0f };
		var oneShipSpeeds = new float[ times.Length ];

		yield return MeasurePlayerSpeeds( times, oneShipSpeeds );

		controller.m_playerShip.TurnOffEngines();

		yield return Frames( 2 );

		var stopped = playerData.m_general.m_currentSpeed;

		LeaveEncounter();
		yield return Frames( 10 );

		// ---- 2. Spemin group 135, three ships
		EnterEncounter( 135 );
		yield return Frames( 5 );

		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		var threePresent = AlienShipsPresent();
		var threeTurns = new float[ 5 ];

		yield return WatchAlienTurns( FirstLivingAlien(), 6.0f, threeTurns );

		var threeTurnSeconds = AlienTurnSeconds();

		controller.m_buttonController.ChangeButtonSet( ButtonController.ButtonSet.Combat );

		var threeTimes = new[] { 10.0f };
		var threeShipSpeeds = new float[ 1 ];

		yield return MeasurePlayerSpeeds( threeTimes, threeShipSpeeds );

		controller.m_playerShip.TurnOffEngines();

		LeaveEncounter();
		yield return Frames( 10 );

		Log( "encounterspeeds: one ship: a turn every " + oneTurnSeconds.ToString( "F2" ) + " s, " + TurnsText( oneTurns ) + ", player at 0.75/5/9 s " + oneShipSpeeds[ 0 ].ToString( "F0" ) + "/" + oneShipSpeeds[ 1 ].ToString( "F0" ) + "/" + oneShipSpeeds[ 2 ].ToString( "F0" ) + ", after letting go " + stopped.ToString( "F1" ) + " || " + threePresent + " ships: a turn every " + threeTurnSeconds.ToString( "F2" ) + " s, " + TurnsText( threeTurns ) + ", player after 10 s " + threeShipSpeeds[ 0 ].ToString( "F0" ) );

		Check( "encounterspeeds: an alien ship's turn comes every (ships + 1) passes of the original's loop, 0.5 s with one ship and 1 s with three (COMBAT-OV COMBAT, WEDCE)", ( Mathf.Abs( oneTurnSeconds - 0.5f ) < 0.01f ) && ( threePresent == 3 ) && ( Mathf.Abs( threeTurnSeconds - 1.0f ) < 0.01f ), oneTurnSeconds.ToString( "F2" ) + " / " + threePresent + " ships " + threeTurnSeconds.ToString( "F2" ) );
		Check( "encounterspeeds: a turn moves a ship a cell across, along or both, and it is there by its next turn, a diagonal step too (the code before left a diagonal step a third short)", TurnsAreWholeCells( oneTurns ) && TurnsAreWholeCells( threeTurns ) && ( oneTurns[ 4 ] + threeTurns[ 4 ] >= 1.0f ), TurnsText( oneTurns ) + " / " + TurnsText( threeTurns ) );
		Check( "encounterspeeds: the player's ship moves a cell a pass at first and a cell more every 14 passes with 7 G (320, 640, 960: HYPER-OV ACCELERATE)", ( Mathf.Abs( oneShipSpeeds[ 0 ] - 320.0f ) < 25.0f ) && ( Mathf.Abs( oneShipSpeeds[ 1 ] - 640.0f ) < 40.0f ) && ( Mathf.Abs( oneShipSpeeds[ 2 ] - 960.0f ) < 60.0f ), oneShipSpeeds[ 0 ].ToString( "F0" ) + " / " + oneShipSpeeds[ 1 ].ToString( "F0" ) + " / " + oneShipSpeeds[ 2 ].ToString( "F0" ) );
		Check( "encounterspeeds: with three alien ships the step stops at 2 cells (640: HYPER-OV #VES-SPEED)", Mathf.Abs( threeShipSpeeds[ 0 ] - 640.0f ) < 40.0f, threeShipSpeeds[ 0 ].ToString( "F0" ) );
		Check( "encounterspeeds: with no direction held the ship stops at once", stopped < 0.1f, stopped.ToString( "F1" ) );

		Time.captureDeltaTime = 0.0f;

		Finish( "scenario=encounterspeeds turns=" + oneTurnSeconds.ToString( "F2" ) + "/" + threeTurnSeconds.ToString( "F2" ), 0 );
	}

	// ---------------------------------------------------------------- the survey's marks on the landing map (TerrainMapDisplay, SurveyMarks: ROADMAP D6)

	// the image of the survey's marks over the landing map (null if it has not been made)
	static UnityEngine.UI.RawImage SurveyMarksImage()
	{
		var map = SpaceflightController.m_instance.m_displayController.m_terrainMapDisplay;
		var marks = ( map.m_map != null ) ? map.m_map.transform.Find( "Survey Marks" ) : null;

		return ( marks != null ) ? marks.GetComponent<UnityEngine.UI.RawImage>() : null;
	}

	// whether the marks show on the landing map
	static bool SurveyMarksShown()
	{
		var image = SurveyMarksImage();

		return ( image != null ) && image.enabled && image.gameObject.activeInHierarchy && ( image.texture != null );
	}

	// the colours drawn around this place of the planet on the marks (offset by pixels of their texture): for each of the 9 pixels about it (a mark's middle
	// falls between pixels), the index of the colour of these it is nearest to, -1 if nothing is drawn on it and -2 if what is drawn is faint
	static HashSet<int> SurveyMarkColors( float eastWest, float northSouth, float offsetX, float offsetY, params Color[] colors )
	{
		var found = new HashSet<int>();
		var image = SurveyMarksImage();
		var texture = ( image != null ) ? image.texture as Texture2D : null;

		if ( texture == null )
		{
			found.Add( -1 );

			return found;
		}

		var pixel = SurveyMarks.GetPixel( texture.width, texture.height, eastWest, northSouth );
		var centerX = Mathf.FloorToInt( pixel.x + offsetX );
		var centerY = Mathf.FloorToInt( pixel.y + offsetY );

		for ( var y = centerY - 1; y <= centerY + 1; y++ )
		{
			for ( var x = centerX - 1; x <= centerX + 1; x++ )
			{
				var color = texture.GetPixel( ( x + texture.width ) % texture.width, Mathf.Clamp( y, 0, texture.height - 1 ) );

				if ( color.a <= 0.0f )
				{
					found.Add( -1 );

					continue;
				}

				if ( color.a <= 0.5f )
				{
					found.Add( -2 );

					continue;
				}

				var nearestIndex = -1;
				var nearest = float.MaxValue;

				for ( var i = 0; i < colors.Length; i++ )
				{
					var distance = Mathf.Abs( color.r - colors[ i ].r ) + Mathf.Abs( color.g - colors[ i ].g ) + Mathf.Abs( color.b - colors[ i ].b );

					if ( distance < nearest )
					{
						nearest = distance;
						nearestIndex = i;
					}
				}

				found.Add( nearestIndex );
			}
		}

		return found;
	}

	// which of these colours is drawn around this place of the planet on the marks: the one a pixel of the 9 about it comes nearest to (-1 if nothing is
	// drawn there), and how near (the sum of the channels' differences)
	static int SurveyMarkNearest( float eastWest, float northSouth, out float nearest, params Color[] colors )
	{
		var image = SurveyMarksImage();

		return SurveyMarkNearest( ( image != null ) ? image.texture as Texture2D : null, eastWest, northSouth, out nearest, colors );
	}

	static int SurveyMarkNearest( Texture2D texture, float eastWest, float northSouth, out float nearest, params Color[] colors )
	{
		var nearestIndex = -1;

		nearest = float.MaxValue;

		if ( texture == null )
		{
			return -1;
		}

		var pixel = SurveyMarks.GetPixel( texture.width, texture.height, eastWest, northSouth );

		for ( var y = Mathf.FloorToInt( pixel.y ) - 1; y <= Mathf.FloorToInt( pixel.y ) + 1; y++ )
		{
			for ( var x = Mathf.FloorToInt( pixel.x ) - 1; x <= Mathf.FloorToInt( pixel.x ) + 1; x++ )
			{
				var color = texture.GetPixel( ( x + texture.width ) % texture.width, Mathf.Clamp( y, 0, texture.height - 1 ) );

				if ( color.a <= 0.5f )
				{
					continue;
				}

				for ( var i = 0; i < colors.Length; i++ )
				{
					var distance = Mathf.Abs( color.r - colors[ i ].r ) + Mathf.Abs( color.g - colors[ i ].g ) + Mathf.Abs( color.b - colors[ i ].b );

					if ( distance < nearest )
					{
						nearest = distance;
						nearestIndex = i;
					}
				}
			}
		}

		return nearestIndex;
	}

	// whether this place shows a mark of this kind in this theme's colours (0 minerals, 1 life, 2 a ruin)
	static bool SurveyMarkIs( int kind, float eastWest, float northSouth, float offsetX, float offsetY, UIKitTheme theme )
	{
		return SurveyMarkColors( eastWest, northSouth, offsetX, offsetY, theme.m_statusArmor, theme.m_statusFuel, theme.m_statusDanger, theme.m_backgroundApp ).Contains( kind );
	}

	IEnumerator ScenarioSurveyMap()
	{
		var controller = SpaceflightController.m_instance;
		var gameData = DataController.m_instance.m_gameData;
		var playerData = DataController.m_instance.m_playerData;
		var displays = controller.m_displayController;
		var grid = controller.m_disembarked.m_terrainGrid;
		var errorsBefore = s_errorCount;

		EnsureCrew();

		UIKitTheme.SetScheme( 0, false );
		UIKitTheme.SetMode( UIKitTheme.Mode.Dark, false );

		var classic = UIKitTheme.GetViewTheme();
		var scienceOfficer = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.ScienceOfficer );

		// ---- 1. in orbit around planet 92 of Arth's system, not analysed yet: no marks (the control)
		yield return GoIntoOrbit( 25, 92 );
		yield return WaitForPlanetMaps( 90.0f );
		yield return Frames( 5 );

		controller.m_planetSurvey = null;

		displays.ChangeDisplay( displays.m_terrainMapDisplay );

		yield return Frames( 2 );

		var shownBeforeAnalysis = SurveyMarksShown();

		// ---- 2. analysed by a science officer of full skill: every mark found is on the map, in its colour
		displays.ChangeDisplay( displays.m_sensorsDisplay );

		yield return Frames( 3 );

		scienceOfficer.m_science = 250;

		AnalyzeNewReading( true );

		var survey = controller.m_planetSurvey;

		displays.ChangeDisplay( displays.m_terrainMapDisplay );

		yield return Frames( 2 );

		var shownAfterAnalysis = SurveyMarksShown();

		// (with -Graphics, a picture of the landing map with its marks)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "surveymap-planet-92.png" ) );
		}

		var minerals = 0;
		var mineralsMarked = 0;
		var lifeforms = 0;
		var lifeformsMarked = 0;
		var notMarked = new List<string>();

		if ( survey != null )
		{
			foreach ( var mark in survey.m_marks )
			{
				// (a mineral field's cross under a lifeform's dot is not looked at)
				var underDot = ( mark.m_kind == PlanetSurvey.Kind.Minerals ) && survey.m_marks.Exists( other => ( other.m_kind == PlanetSurvey.Kind.Life ) && ( Mathf.Abs( Mathf.DeltaAngle( other.m_eastWest, mark.m_eastWest ) ) < 4.0f ) && ( Mathf.Abs( other.m_northSouth - mark.m_northSouth ) < 4.0f ) );

				if ( underDot )
				{
					continue;
				}

				var kind = ( mark.m_kind == PlanetSurvey.Kind.Minerals ) ? 0 : 1;
				var marked = SurveyMarkIs( kind, mark.m_eastWest, mark.m_northSouth, 0.0f, 0.0f, classic );

				if ( mark.m_kind == PlanetSurvey.Kind.Minerals )
				{
					minerals++;
					mineralsMarked += marked ? 1 : 0;
				}
				else
				{
					lifeforms++;
					lifeformsMarked += marked ? 1 : 0;
				}

				if ( !marked && ( notMarked.Count < 5 ) )
				{
					notMarked.Add( ( ( kind == 0 ) ? "minerals" : "life" ) + " at " + mark.m_eastWest.ToString( "F1" ) + "," + mark.m_northSouth.ToString( "F1" ) );
				}
			}
		}

		// a place far from every mark is clear (the control)
		var clearPlace = new Vector2( float.NaN, float.NaN );

		for ( var eastWest = -170.0f; ( eastWest < 180.0f ) && float.IsNaN( clearPlace.x ); eastWest += 10.0f )
		{
			for ( var northSouth = -80.0f; ( northSouth <= 80.0f ) && float.IsNaN( clearPlace.x ); northSouth += 10.0f )
			{
				var ew = eastWest;
				var ns = northSouth;

				if ( ( survey != null ) && !survey.m_marks.Exists( mark => ( Mathf.Abs( Mathf.DeltaAngle( mark.m_eastWest, ew ) ) < 10.0f ) && ( Mathf.Abs( mark.m_northSouth - ns ) < 10.0f ) ) )
				{
					clearPlace = new Vector2( ew, ns );
				}
			}
		}

		var clearColors = float.IsNaN( clearPlace.x ) ? null : SurveyMarkColors( clearPlace.x, clearPlace.y, 0.0f, 0.0f, classic.m_statusArmor );
		var clearAway = ( clearColors != null ) && ( clearColors.Count == 1 ) && clearColors.Contains( -1 );

		Log( "surveymap: planet 92: before the analysis shown " + shownBeforeAnalysis + "; after it shown " + shownAfterAnalysis + ", minerals " + mineralsMarked + "/" + minerals + ", lifeforms " + lifeformsMarked + "/" + lifeforms + ( ( notMarked.Count > 0 ) ? " (not marked: " + string.Join( "; ", notMarked ) + ")" : "" ) + ", clear at " + clearPlace + ": " + clearAway );

		// ---- 3. another scheme picked while the map is open: the marks take its colours; the light mode keeps the views' (dark) colours
		var otherScheme = -1;

		for ( var scheme = 1; ( scheme < UIKitTheme.c_schemes.Length ) && ( otherScheme < 0 ); scheme++ )
		{
			var theme = UIKitTheme.LoadScheme( scheme, UIKitTheme.Mode.Dark );

			if ( ( theme != null ) && ( Mathf.Abs( theme.m_statusArmor.r - classic.m_statusArmor.r ) + Mathf.Abs( theme.m_statusArmor.g - classic.m_statusArmor.g ) + Mathf.Abs( theme.m_statusArmor.b - classic.m_statusArmor.b ) > 0.3f ) )
			{
				otherScheme = scheme;
			}
		}

		var firstField = ( survey != null ) ? survey.m_marks.Find( mark => mark.m_kind == PlanetSurvey.Kind.Minerals ) : default( PlanetSurvey.Mark );
		var inOtherScheme = false;
		var inLightMode = false;
		var otherSchemeDetail = "";
		var lightModeDetail = "";

		if ( otherScheme > 0 )
		{
			UIKitTheme.SetScheme( otherScheme, false );

			yield return Frames( 2 );

			var other = UIKitTheme.GetViewTheme();

			// (the cross's middle in the other scheme's mineral colour, not the classic one's)
			var inOther = SurveyMarkNearest( firstField.m_eastWest, firstField.m_northSouth, out var otherNearest, other.m_statusArmor, classic.m_statusArmor );

			inOtherScheme = ( other != classic ) && ( inOther == 0 ) && ( otherNearest < 0.05f );
			otherSchemeDetail = inOther + " at " + otherNearest.ToString( "F3" );

			UIKitTheme.SetMode( UIKitTheme.Mode.Light, false );

			yield return Frames( 2 );

			// (the views' colours are the scheme's dark theme's, not its light theme's)
			var light = UIKitTheme.LoadScheme( otherScheme, UIKitTheme.Mode.Light );
			var inLight = SurveyMarkNearest( firstField.m_eastWest, firstField.m_northSouth, out var lightNearest, other.m_statusArmor, ( light != null ) ? light.m_statusArmor : other.m_statusArmor );

			inLightMode = ( inLight == 0 ) && ( lightNearest < 0.05f );
			lightModeDetail = inLight + " at " + lightNearest.ToString( "F3" ) + ( ( light != null ) ? " (light " + ColorUtility.ToHtmlStringRGB( light.m_statusArmor ) + ")" : "" );

			UIKitTheme.SetMode( UIKitTheme.Mode.Dark, false );
			UIKitTheme.SetScheme( 0, false );

			yield return Frames( 2 );
		}

		Log( "surveymap: in scheme " + otherScheme + " (" + ( ( otherScheme > 0 ) ? ColorUtility.ToHtmlStringRGB( UIKitTheme.LoadScheme( otherScheme, UIKitTheme.Mode.Dark ).m_statusArmor ) : "" ) + ", classic " + ColorUtility.ToHtmlStringRGB( classic.m_statusArmor ) + ") the first field's cross in its colours " + inOtherScheme + " (" + otherSchemeDetail + "), in the light mode in the views' colours " + inLightMode + " (" + lightModeDetail + ")" );

		// ---- 4. the Red Cylinder at 145,107, around the planet of the documented ancient ruins (not analysed): no marks without it, the ruins with it
		var ruinPlaces = new List<Vector2>();
		var shownWithout = true;
		var shownWith = false;
		var shownAfter = true;
		var ruinsMarked = 0;
		var ruinStar = System.Array.Find( gameData.m_starList, star => ( star.m_xCoordinate == 145 ) && ( star.m_yCoordinate == 107 ) );

		if ( ruinStar != null )
		{
			var firstPlanet = System.Array.Find( ruinStar.GetPlanetList(), p => ( p != null ) && ( p.m_id >= 0 ) );

			if ( firstPlanet != null )
			{
				yield return GoIntoOrbit( ruinStar.m_id, firstPlanet.m_id );
				yield return WaitForPlanetMaps( 90.0f );
				yield return Frames( 5 );

				GD_Planet ruinPlanet = null;

				foreach ( var candidate in ruinStar.GetPlanetList() )
				{
					var candidateController = ( ( candidate != null ) && ( candidate.m_id >= 0 ) ) ? controller.m_starSystem.GetPlanetController( candidate.m_id ) : null;

					if ( ( candidateController != null ) && candidateController.HasMaps() && !candidate.IsGasGiant() && ( TerrainRuins.GetAncientRuinPlaces( candidateController.GetPlanetGenerator(), grid.m_elevationScale, candidate ).Count > 0 ) )
					{
						ruinPlanet = candidate;
						break;
					}
				}

				if ( ruinPlanet != null )
				{
					if ( ruinPlanet.m_id != firstPlanet.m_id )
					{
						yield return GoIntoOrbit( ruinStar.m_id, ruinPlanet.m_id );
						yield return WaitForPlanetMaps( 90.0f );
						yield return Frames( 5 );
					}

					var redCylinder = gameData.FindArtifactId( "Red Cylinder" );

					displays.ChangeDisplay( displays.m_terrainMapDisplay );

					yield return Frames( 2 );

					shownWithout = SurveyMarksShown();

					playerData.m_playerShip.AddArtifact( redCylinder );

					displays.ChangeDisplay( displays.m_sensorsDisplay );
					displays.ChangeDisplay( displays.m_terrainMapDisplay );

					yield return Frames( 2 );

					shownWith = SurveyMarksShown();
					ruinPlaces = new List<Vector2>( RedCylinder.GetAncientRuinPlaces() );

					if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
					{
						RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "surveymap-ruins.png" ) );
					}

					// (a box is hollow: its right side is SurveyMarks.c_boxHalfSize pixels of the texture east of its middle)
					foreach ( var place in ruinPlaces )
					{
						ruinsMarked += SurveyMarkIs( 2, place.x, place.y, SurveyMarks.c_boxHalfSize, 0.0f, classic ) ? 1 : 0;
					}

					playerData.m_playerShip.RemoveArtifact( redCylinder );

					displays.ChangeDisplay( displays.m_sensorsDisplay );
					displays.ChangeDisplay( displays.m_terrainMapDisplay );

					yield return Frames( 2 );

					shownAfter = SurveyMarksShown();
				}
			}
		}

		Log( "surveymap: at 145,107: without the Red Cylinder shown " + shownWithout + ", with it shown " + shownWith + " and " + ruinsMarked + " of " + ruinPlaces.Count + " ruins marked, after it is gone shown " + shownAfter );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "surveymap: before the planet is analysed from orbit, the landing map has no marks", !shownBeforeAnalysis, shownBeforeAnalysis.ToString() );
		Check( "surveymap: after the analysis, every mineral field and lifeform found is marked on the landing map in its colour, and the map is clear away from them", shownAfterAnalysis && ( survey != null ) && ( minerals > 0 ) && ( mineralsMarked == minerals ) && ( lifeforms > 0 ) && ( lifeformsMarked == lifeforms ) && clearAway, shownAfterAnalysis + " " + mineralsMarked + "/" + minerals + " " + lifeformsMarked + "/" + lifeforms + " " + clearAway );
		Check( "surveymap: the marks take the colours of another scheme picked while the map is open, and the views' colours in the light mode", ( otherScheme > 0 ) && inOtherScheme && inLightMode, otherScheme + " " + inOtherScheme + " " + inLightMode );
		Check( "surveymap: with the Red Cylinder aboard every ancient ruin is marked on the landing map; without it a planet not analysed has no marks", !shownWithout && shownWith && ( ruinPlaces.Count > 0 ) && ( ruinsMarked == ruinPlaces.Count ) && !shownAfter, shownWithout + " " + shownWith + " " + ruinsMarked + "/" + ruinPlaces.Count + " " + shownAfter );
		Check( "surveymap: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=surveymap minerals=" + mineralsMarked + "/" + minerals + " lifeforms=" + lifeformsMarked + "/" + lifeforms + " ruins=" + ruinsMarked + "/" + ruinPlaces.Count + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the survey's marks on the sensor picture (SensorsDisplay, Sensor Planet shader: ROADMAP D6)

	// the colour the sensor picture's planet material draws at the middle of its disc, turned and tilted so that this place of the planet is there, with the
	// survey's marks at this strength and their pulse held still (on the graphics card; clear without graphics)
	static Color SensorPlanetPixelAt( Material material, float eastWest, float northSouth, float surveyStrength )
	{
		if ( ( material == null ) || ( SystemInfo.graphicsDeviceType == UnityEngine.Rendering.GraphicsDeviceType.Null ) )
		{
			return Color.clear;
		}

		var copy = new Material( material );

		// the middle of the disc shows longitude 0 at the latitude of the tilt; the marks' texture runs up the planet's maps from 0.125 to 0.875
		var mapV = 0.125f + 0.75f * ( northSouth + 90.0f ) / 180.0f;

		copy.SetFloat( "_Spin", 0.5f - ( eastWest + 180.0f ) / 360.0f );
		copy.SetFloat( "_Tilt", ( mapV - 0.5f ) * Mathf.PI );
		copy.SetFloat( "_Reveal", 1.0f );
		copy.SetFloat( "_SurveyStrength", surveyStrength );
		copy.SetFloat( "_SurveyPulse", 0.0f );
		copy.SetTexture( "_MaskTex", Texture2D.whiteTexture );

		// (2 to 1, as the picture is, so that the disc is round; odd, so that the middle pixel is its middle)
		var renderTexture = new RenderTexture( 257, 129, 0, RenderTextureFormat.ARGB32 );
		var picture = new Texture2D( 257, 129, TextureFormat.RGBA32, false );
		var active = RenderTexture.active;

		Graphics.Blit( Texture2D.whiteTexture, renderTexture, copy );

		RenderTexture.active = renderTexture;
		picture.ReadPixels( new Rect( 0, 0, 257, 129 ), 0, 0 );
		picture.Apply();
		RenderTexture.active = active;

		var pixel = picture.GetPixel( 128, 64 );

		renderTexture.Release();
		UnityEngine.Object.DestroyImmediate( renderTexture );
		UnityEngine.Object.DestroyImmediate( picture );
		UnityEngine.Object.DestroyImmediate( copy );

		return pixel;
	}

	// how far apart two colours are (the sum of their channels' differences)
	static float ColorDistance( Color a, Color b )
	{
		return Mathf.Abs( a.r - b.r ) + Mathf.Abs( a.g - b.g ) + Mathf.Abs( a.b - b.b );
	}

	IEnumerator ScenarioSurveySensor()
	{
		var controller = SpaceflightController.m_instance;
		var gameData = DataController.m_instance.m_gameData;
		var playerData = DataController.m_instance.m_playerData;
		var displays = controller.m_displayController;
		var sensors = displays.m_sensorsDisplay;
		var errorsBefore = s_errorCount;

		EnsureCrew();

		UIKitTheme.SetScheme( 0, false );
		UIKitTheme.SetMode( UIKitTheme.Mode.Dark, false );

		var classic = UIKitTheme.GetViewTheme();
		var scienceOfficer = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.ScienceOfficer );

		scienceOfficer.m_science = 250;

		// ---- 1. in orbit around planet 92 of Arth's system, a scan of the planet before any analysis: no marks on it (the control)
		yield return GoIntoOrbit( 25, 92 );
		yield return WaitForPlanetMaps( 90.0f );
		yield return Frames( 5 );

		var planet = gameData.m_planetList[ 92 ];

		controller.m_planetSurvey = null;

		displays.ChangeDisplay( sensors );

		yield return Frames( 3 );

		sensors.m_hasSensorData = false;
		sensors.StartScanning( SensorsDisplay.ScanType.Planet, 18, planet.m_mass, planet.m_bioDensity, planet.m_mineralDensity );

		var until = Time.realtimeSinceStartup + sensors.m_maxDuration + 5.0f;

		while ( !sensors.m_hasSensorData && ( Time.realtimeSinceStartup < until ) )
		{
			yield return null;
		}

		yield return Frames( 2 );

		var material = sensors.m_maskImage.material;
		var showsPlanet = ShowsPlanetSurface( sensors );
		var strengthBefore = showsPlanet ? material.GetFloat( "_SurveyStrength" ) : -1.0f;

		// ---- 2. the reading analysed: the survey's marks go on the planet in the picture
		AnalyzeNewReading( false );

		var survey = controller.m_planetSurvey;

		yield return Frames( 3 );

		var strengthAfter = ShowsPlanetSurface( sensors ) ? material.GetFloat( "_SurveyStrength" ) : -1.0f;
		var sensorMarks = ShowsPlanetSurface( sensors ) ? material.GetTexture( "_SurveyTex" ) as Texture2D : null;

		// ---- 3. on the graphics card (with -Graphics): a lifeform's mark shows on the sphere where the lifeform is, and not without the marks
		var lifeform = ( survey != null ) ? survey.m_marks.Find( mark => mark.m_kind == PlanetSurvey.Kind.Life ) : default( PlanetSurvey.Mark );
		var hasLifeform = ( survey != null ) && survey.m_marks.Exists( mark => mark.m_kind == PlanetSurvey.Kind.Life );
		var withGraphics = SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null;
		var withMarks = hasLifeform ? SensorPlanetPixelAt( material, lifeform.m_eastWest, lifeform.m_northSouth, 1.0f ) : Color.clear;
		var withoutMarks = hasLifeform ? SensorPlanetPixelAt( material, lifeform.m_eastWest, lifeform.m_northSouth, 0.0f ) : Color.clear;
		var distanceWith = ColorDistance( withMarks, classic.m_statusFuel );
		var distanceWithout = ColorDistance( withoutMarks, classic.m_statusFuel );

		// (with -Graphics, a picture of the sensor window with the marks on the planet)
		if ( withGraphics )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "surveysensor-planet-92.png" ) );
		}

		Log( "surveysensor: planet 92: before the analysis strength " + strengthBefore + " (planet shown " + showsPlanet + "); after it strength " + strengthAfter + " | the lifeform at " + lifeform.m_eastWest.ToString( "F1" ) + "," + lifeform.m_northSouth.ToString( "F1" ) + " on the graphics card: with the marks " + ColorUtility.ToHtmlStringRGB( withMarks ) + " (" + distanceWith.ToString( "F2" ) + " from " + ColorUtility.ToHtmlStringRGB( classic.m_statusFuel ) + "), without " + ColorUtility.ToHtmlStringRGB( withoutMarks ) + " (" + distanceWithout.ToString( "F2" ) + ")" + ( withGraphics ? "" : " (no graphics)" ) );

		// ---- 4. another scheme picked while the picture shows the planet: its marks are drawn again in that scheme's colours
		var otherScheme = -1;

		for ( var scheme = 1; ( scheme < UIKitTheme.c_schemes.Length ) && ( otherScheme < 0 ); scheme++ )
		{
			var theme = UIKitTheme.LoadScheme( scheme, UIKitTheme.Mode.Dark );

			if ( ( theme != null ) && ( ColorDistance( theme.m_statusFuel, classic.m_statusFuel ) > 0.3f ) )
			{
				otherScheme = scheme;
			}
		}

		var inOtherScheme = false;
		var otherDetail = "";

		if ( ( otherScheme > 0 ) && hasLifeform )
		{
			UIKitTheme.SetScheme( otherScheme, false );

			yield return Frames( 2 );

			var other = UIKitTheme.GetViewTheme();
			var shown = ShowsPlanetSurface( sensors ) ? material.GetTexture( "_SurveyTex" ) as Texture2D : null;
			var nearest = SurveyMarkNearest( shown, lifeform.m_eastWest, lifeform.m_northSouth, out var nearness, other.m_statusFuel, classic.m_statusFuel );

			inOtherScheme = ( shown != null ) && ( material.GetFloat( "_SurveyStrength" ) > 0.5f ) && ( nearest == 0 ) && ( nearness < 0.05f );
			otherDetail = nearest + " at " + nearness.ToString( "F3" );

			UIKitTheme.SetScheme( 0, false );

			yield return Frames( 2 );
		}

		Log( "surveysensor: in scheme " + otherScheme + " the lifeform's dot in its colours " + inOtherScheme + " (" + otherDetail + ")" );

		// ---- 5. the landing map shows the very same marks
		displays.ChangeDisplay( displays.m_terrainMapDisplay );

		yield return Frames( 2 );

		var mapImage = SurveyMarksImage();
		var sameMarks = ( sensorMarks != null ) && ( mapImage != null ) && ( mapImage.texture == sensorMarks ) && ( sensorMarks == SurveyMarks.GetTexture() );

		Log( "surveysensor: the landing map's marks are the sensor picture's " + sameMarks );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "surveysensor: before the planet is analysed, the planet in the sensor picture has no marks", showsPlanet && Mathf.Approximately( strengthBefore, 0.0f ), showsPlanet + " " + strengthBefore );
		Check( "surveysensor: once the reading is analysed, the planet in the sensor picture shows the survey's marks, the landing map's", ( survey != null ) && Mathf.Approximately( strengthAfter, 1.0f ) && sameMarks, ( survey != null ) + " " + strengthAfter + " " + sameMarks );

		if ( withGraphics )
		{
			Check( "surveysensor: on the graphics card a lifeform's mark shows on the turning planet where the lifeform is, and not without the marks", hasLifeform && ( distanceWith < distanceWithout * 0.5f ) && ( distanceWithout - distanceWith > 0.3f ), distanceWith.ToString( "F2" ) + " with, " + distanceWithout.ToString( "F2" ) + " without" );
		}

		Check( "surveysensor: another scheme picked while the picture shows the planet draws its marks again in that scheme's colours", ( otherScheme > 0 ) && inOtherScheme, otherScheme + " " + inOtherScheme + " " + otherDetail );
		Check( "surveysensor: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=surveysensor strength=" + strengthBefore + "/" + strengthAfter + " gpu=" + ( withGraphics ? distanceWith.ToString( "F2" ) + "/" + distanceWithout.ToString( "F2" ) : "none" ) + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the terrain vehicle's mining laser (TVMineButton, since 2026-10-17)

	// cuts the deposit nearest the terrain vehicle into its hold with the mining laser, as the player does it: Tools, then Mine, waiting while the laser runs (at
	// most limitSeconds of game time); started[ 0 ] tells whether the Mine button was there and began to cut (the code before the mining laser has none)
	static IEnumerator MineWithTheLaser( float limitSeconds, bool[] started )
	{
		var buttonController = SpaceflightController.m_instance.m_buttonController;
		var index = Array.IndexOf( ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicleWeapon ).Split( ',' ), "Mine" );

		started[ 0 ] = false;

		if ( index < 0 )
		{
			yield break;
		}

		PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, index );

		var mine = GetField( buttonController, "m_currentButton" );

		started[ 0 ] = ( mine != null ) && ( mine.GetType().Name == "TVMineButton" );

		for ( var end = Time.time + limitSeconds; started[ 0 ] && ( Time.time < end ) && ( GetField( buttonController, "m_currentButton" ) == mine ); )
		{
			yield return null;
		}

		// a laser still cutting at the limit is stopped, as the fire button stops it
		if ( started[ 0 ] && ( GetField( buttonController, "m_currentButton" ) == mine ) )
		{
			Call( mine, "Stop", "the probe's time limit" );
		}

		// the vehicle's own buttons again, as Back gives them
		buttonController.ChangeButtonSet( ButtonController.ButtonSet.TerrainVehicle );
	}

	// the beam of the mining laser being drawn, if it is (a LaserBeam under the disembarked location with its glow on), and how wide it is drawn: the width it is set
	// to (LaserBeam.SetScale), not the line's in this frame, which fades with each pulse of the beam (a frame late in a pulse read 0.10 on a busy PC)
	static bool MiningBeamShows( out float width )
	{
		width = 0.0f;

		foreach ( var beam in SpaceflightController.m_instance.m_disembarked.GetComponentsInChildren<LaserBeam>( false ) )
		{
			if ( beam.TryGetComponent<LineRenderer>( out var line ) && line.enabled && beam.IsActive() )
			{
				var setWidth = FieldOrNull( beam, "m_startWidth" );

				width = ( setWidth is float ) ? (float) setWidth : line.startWidth;

				return true;
			}
		}

		return false;
	}

	// on planet 90 (Arth's system, a mineral density of 43%): Cargo beside a deposit no longer takes it in one press but points to the mining laser; Tools has a
	// Mine button whose laser cuts the deposit into the hold a tenth of a cubic meter at a time (gradually, on the vehicle's energy, the beam drawn at the ground's
	// scale, the deposit shrinking) until it is gone (remembered on the planet, hidden, the button off); the fire button stops it with the rest remembered; no
	// deposit in reach, a full hold and an empty tank are refused
	IEnumerator ScenarioMiningLaser()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;

		EnsureCrew();
		ProbeKeyboard();

		yield return EnterOrbit( 90 );

		// land without the 35 second landing animation, then out in the terrain vehicle with the real button
		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );

		PressButton( ButtonController.ButtonSet.CommandA, 1 );

		yield return WaitForLocation( PD_General.Location.Disembarked, 15.0f );
		yield return Frames( 10 );

		if ( playerData.m_general.m_location != PD_General.Location.Disembarked )
		{
			Finish( "scenario=mininglaser abort: never got into the terrain vehicle (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		// Move is on when the vehicle comes out: stop it, as the player does before using the console
		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		var terrainVehicle = controller.m_terrainVehicle;
		var deposits = controller.m_disembarked.m_terrainGrid.m_terrainElements.transform.GetComponentsInChildren<TerrainElement>( true );

		if ( deposits.Length < 3 )
		{
			Finish( "scenario=mininglaser abort: the planet has " + deposits.Length + " deposits", 2 );
			yield break;
		}

		// every deposit out of reach, then one at a time beside the vehicle
		foreach ( var other in deposits )
		{
			if ( Vector3.Distance( other.transform.position, terrainVehicle.transform.position ) < 100.0f )
			{
				other.transform.position += Vector3.right * 1000.0f;
			}
		}

		var deposit = deposits[ 0 ];

		deposit.m_volume = 60;
		deposit.transform.position = BesideTheVehicle( terrainVehicle );

		var elementId = deposit.m_elementId;
		var startScale = deposit.transform.localScale.x;

		yield return Frames( 3 );

		// ---- 1. Cargo beside the deposit takes nothing and points to the laser
		var holdBefore = TerrainVehicleCargo( elementId );

		new TVCargoButton().Execute();

		var holdAfterCargo = TerrainVehicleCargo( elementId );
		var cargoMessage = MessageList();

		// ---- 2. Tools has Mine
		var toolLabels = ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicleWeapon );
		var mainLabels = ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicle );

		// ---- 3. Mine: part way through the cut
		var fuelBefore = playerData.m_terrainVehicle.m_fuelRemaining;
		var mineIndex = Array.IndexOf( toolLabels.Split( ',' ), "Mine" );
		var midHold = holdAfterCargo;
		var midDeposit = deposit.m_volume;
		var midScale = startScale;
		var beamWidth = 0.0f;
		var beamShows = false;
		var mineRunning = false;

		if ( mineIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, mineIndex );

			for ( var end = Time.time + 1.5f; Time.time < end; )
			{
				yield return null;
			}

			var current = GetField( buttonController, "m_currentButton" );

			mineRunning = ( current != null ) && ( current.GetType().Name == "TVMineButton" );
			midHold = TerrainVehicleCargo( elementId );
			midDeposit = deposit.m_volume;
			midScale = deposit.transform.localScale.x;
			beamShows = MiningBeamShows( out beamWidth );

			// ---- 4. to the end of the cut
			for ( var end = Time.time + 10.0f; ( Time.time < end ) && ( GetField( buttonController, "m_currentButton" ) == current ); )
			{
				yield return null;
			}
		}

		var endHold = TerrainVehicleCargo( elementId );
		var endMessage = MessageList();
		var fuelUsed = fuelBefore - playerData.m_terrainVehicle.m_fuelRemaining;
		var stillRunning = GetField( buttonController, "m_currentButton" ) != null;
		var depositGone = ( deposit != null ) && deposit.HasBeenPickedUp() && !deposit.gameObject.activeSelf;
		var remembered = playerData.m_planetSurfaces.GetDepositVolumeLeft( deposit.m_planetId, deposit.m_depositIndex );

		// ---- 5. stopped with the fire button: the rest of the deposit is remembered
		var second = deposits[ 1 ];

		second.m_volume = 80;
		second.transform.position = BesideTheVehicle( terrainVehicle );

		yield return Frames( 3 );

		var secondHoldBefore = TerrainVehicleCargo( second.m_elementId );
		var stoppedLeft = -1;
		var stoppedRemembered = -2;
		var stoppedOff = false;

		if ( mineIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, mineIndex );

			for ( var end = Time.time + 0.6f; Time.time < end; )
			{
				yield return null;
			}

			yield return Tap( Key.Enter );
			yield return Frames( 5 );

			stoppedOff = GetField( buttonController, "m_currentButton" ) == null;
			stoppedLeft = second.m_volume;
			stoppedRemembered = playerData.m_planetSurfaces.GetDepositVolumeLeft( second.m_planetId, second.m_depositIndex );
		}

		var secondMined = TerrainVehicleCargo( second.m_elementId ) - secondHoldBefore;

		second.transform.position += Vector3.right * 1000.0f;

		yield return Frames( 3 );

		// ---- 6. refused: no deposit in reach, a full hold, an empty tank
		var holdBeforeRefusals = playerData.m_terrainVehicle.m_volumeUsed;
		var started = new bool[ 1 ];

		yield return MineWithTheLaser( 2.0f, started );

		var noDepositRefused = !started[ 0 ] && MessageList().Contains( "no mineral deposit within reach" );

		var third = deposits[ 2 ];

		third.m_volume = 50;
		third.transform.position = BesideTheVehicle( terrainVehicle );

		yield return Frames( 3 );

		var room = playerData.m_terrainVehicle.GetRemainingVolume();

		playerData.m_terrainVehicle.AddElement( third.m_elementId, room );

		yield return MineWithTheLaser( 2.0f, started );

		var fullRefused = !started[ 0 ] && MessageList().Contains( "full" ) && ( third.m_volume == 50 );

		playerData.m_terrainVehicle.RemoveElement( third.m_elementId, room );

		var fuel = playerData.m_terrainVehicle.m_fuelRemaining;

		// (the reserve below the display's 0% goes too, PD_TerrainVehicle.IsOutOfFuel)
		playerData.m_terrainVehicle.m_fuelRemaining = -1.0f;

		yield return MineWithTheLaser( 2.0f, started );

		var emptyRefused = !started[ 0 ] && MessageList().Contains( "not enough energy" ) && ( third.m_volume == 50 );

		playerData.m_terrainVehicle.m_fuelRemaining = fuel;

		Log( "mininglaser: Cargo beside a deposit of 6.0: hold " + holdBefore + " -> " + holdAfterCargo + ", message [" + cargoMessage + "]; Tools [" + toolLabels + "], the vehicle's buttons [" + mainLabels + "]" );
		Log( "mininglaser: after 1.5 s of Mine: running " + mineRunning + ", hold " + midHold + ", deposit " + midDeposit + ", scale " + startScale.ToString( "F2" ) + " -> " + midScale.ToString( "F2" ) + ", beam " + beamShows + " " + beamWidth.ToString( "F2" ) + " wide; at the end: hold " + endHold + ", energy used " + fuelUsed.ToString( "F4" ) + " of the tank, running " + stillRunning + ", deposit gone " + depositGone + ", remembered " + remembered + ", message [" + endMessage + "]" );
		Log( "mininglaser: stopped with Enter after 0.6 s: off " + stoppedOff + ", mined " + secondMined + ", left " + stoppedLeft + ", remembered " + stoppedRemembered + "; refused with no deposit " + noDepositRefused + ", a full hold " + fullRefused + ", an empty tank " + emptyRefused + " (hold used " + holdBeforeRefusals + ")" );

		Check( "mininglaser: Cargo beside a deposit takes nothing and points to Tools, Mine (it took the deposit in one press)", ( holdAfterCargo == holdBefore ) && cargoMessage.Contains( "Mine" ), holdBefore + " -> " + holdAfterCargo );
		Check( "mininglaser: the vehicle's Weapon button is Tools, with Mine first", mainLabels.Contains( "Tools" ) && toolLabels.StartsWith( "Mine" ), mainLabels + " / " + toolLabels );
		Check( "mininglaser: 1.5 s into the cut part of the deposit is in the hold and the rest still in the deposit (a tenth at a time, 15 a second), and it has shrunk", mineRunning && ( midHold > holdBefore + 10 ) && ( midHold < holdBefore + 60 ) && ( midHold - holdBefore + midDeposit == 60 ) && ( midScale < startScale ), "hold +" + ( midHold - holdBefore ) + ", deposit " + midDeposit + ", scale " + midScale.ToString( "F2" ) );
		Check( "mininglaser: the beam is drawn while it cuts, at the ground's scale (not the 9 units of the ships' lasers)", beamShows && ( beamWidth > 0.2f ) && ( beamWidth < 3.0f ), beamWidth.ToString( "F2" ) );
		Check( "mininglaser: the whole deposit ends up in the hold, the deposit is gone and remembered as empty, and the laser is off", ( endHold == holdBefore + 60 ) && depositGone && ( remembered == 0 ) && !stillRunning && endMessage.Contains( "Mined 6.0 cubic meters" ), "hold " + endHold + ", gone " + depositGone + ", remembered " + remembered + ", running " + stillRunning );
		Check( "mininglaser: the cut takes the vehicle's energy, 10 of its tank a tenth (60 tenths)", Mathf.Abs( fuelUsed - 60.0f * 10.0f / TerrainVehicle.c_tankUnits ) < 0.0005f, fuelUsed.ToString( "F4" ) );
		Check( "mininglaser: the fire button stops the laser, and what is left of the deposit is remembered", stoppedOff && ( secondMined > 0 ) && ( secondMined < 80 ) && ( stoppedLeft == 80 - secondMined ) && ( stoppedRemembered == stoppedLeft ), "mined " + secondMined + ", left " + stoppedLeft + ", remembered " + stoppedRemembered );
		Check( "mininglaser: Mine with no deposit in reach, with a full hold and with an empty tank does nothing and says why", noDepositRefused && fullRefused && emptyRefused, noDepositRefused + "/" + fullRefused + "/" + emptyRefused );

		Finish( "scenario=mininglaser checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the terrain vehicle's Return order (TVReturnButton, since 2026-10-17)

	// puts the terrain vehicle at a place on the ground, as driving keeps it (flat: the ground's height is only drawn)
	static void PutTheVehicleAt( Vector3 place )
	{
		var playerData = DataController.m_instance.m_playerData;

		playerData.m_general.m_coordinates = place;
		playerData.m_general.m_lastDisembarkedCoordinates = place;
		SpaceflightController.m_instance.m_terrainVehicle.transform.localPosition = place;
	}

	// a place in the liquid and the nearest place on solid ground to it (within 10 pixels of the planet's map, 40 units, in one of eight directions); false if there is none
	static bool FindSolidGroundByTheLiquid( out Vector3 solid, out Vector3 liquid )
	{
		solid = Vector3.zero;
		liquid = Vector3.zero;

		var planetGenerator = FieldOrNull( SpaceflightController.m_instance.m_terrainVehicle, "m_planetGenerator" ) as PlanetGenerator;

		if ( planetGenerator == null )
		{
			return false;
		}

		var width = planetGenerator.m_textureMapWidth;
		var height = planetGenerator.m_textureMapHeight;
		var water = planetGenerator.m_waterElevation;

		var directions = new Vector2Int[] { new Vector2Int( 1, 0 ), new Vector2Int( -1, 0 ), new Vector2Int( 0, 1 ), new Vector2Int( 0, -1 ), new Vector2Int( 1, 1 ), new Vector2Int( -1, 1 ), new Vector2Int( 1, -1 ), new Vector2Int( -1, -1 ) };

		for ( var y = height / 4; y < height * 3 / 4; y += 8 )
		{
			for ( var x = 48; x < width - 48; x += 8 )
			{
				if ( planetGenerator.GetBicubicSmoothedElevation( x, y ) >= water - 0.005f )
				{
					continue;
				}

				for ( var r = 3; r <= 10; r++ )
				{
					foreach ( var d in directions )
					{
						var sx = x + d.x * r;
						var sy = Mathf.Clamp( y + d.y * r, 0, height - 1 );

						if ( planetGenerator.GetBicubicSmoothedElevation( sx, sy ) > water + 0.005f )
						{
							solid = new Vector3( ( sx + 0.5f - width * 0.5f ) * 4.0f, 0.0f, ( sy + 0.5f - height * 0.5f ) * 4.0f );
							liquid = new Vector3( ( x + 0.5f - width * 0.5f ) * 4.0f, 0.0f, ( y + 0.5f - height * 0.5f ) * 4.0f );

							return true;
						}
					}
				}
			}
		}

		Log( "returnorder: no solid ground by the liquid; the liquid's level is " + water.ToString( "F3" ) );

		return false;
	}

	// on planet 94 with the ship on raised ground: Tools has Return; from 6 km out it drives the vehicle back by itself (the stick never touched), on the vehicle's
	// fuel, and takes it aboard on the ship's own cell; the fire button stops it on the way, nearer than it was; a vehicle that makes no headway stops and says the
	// way is blocked; and on planet 29 (molten) it stops short of lava between the vehicle and the ship
	IEnumerator ScenarioReturnOrder()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;
		var done = new bool[ 1 ];

		EnsureCrew();
		ProbeKeyboard();

		// no encounter may begin on the way
		controller.m_encounterRange = 0.0f;

		yield return LandOnPlanet94At( Tools.LatLongToWorldCoordinates( 4.3f, -16.0f ), done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=returnorder abort: no landing (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		var toolLabels = ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicleWeapon );
		var returnIndex = Array.IndexOf( toolLabels.Split( ',' ), "Return" );
		var ship = Tools.LatLongToWorldCoordinates( playerData.m_general.m_selectedLatitude, playerData.m_general.m_selectedLongitude );
		var unitsPerKm = 2048.0f / 225.0f;

		// Move runs when the vehicle comes out: stop it, as the player does before using the console
		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		// ---- 1. Return from 6 km out
		PutTheVehicleAt( new Vector3( ship.x + 6.0f * unitsPerKm, 0.0f, ship.z ) );

		yield return Frames( 5 );

		var fuelBefore = playerData.m_terrainVehicle.m_fuelRemaining;
		var lowestFuel = fuelBefore;
		var nearestKm = 6.0f;
		var seconds = -1.0f;

		if ( returnIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, returnIndex );

			var start = Time.time;
			var nextTrace = Time.time;

			for ( var end = Time.time + 40.0f; ( Time.time < end ) && ( playerData.m_general.m_location == PD_General.Location.Disembarked ); )
			{
				lowestFuel = Mathf.Min( lowestFuel, playerData.m_terrainVehicle.m_fuelRemaining );

				var toShip = ship - playerData.m_general.m_lastDisembarkedCoordinates;

				toShip.y = 0.0f;
				nearestKm = Mathf.Min( nearestKm, toShip.magnitude / unitsPerKm );

				if ( Time.time >= nextTrace )
				{
					nextTrace = Time.time + 3.0f;

					var current = GetField( buttonController, "m_currentButton" );

					Log( "returnorder: at " + ( Time.time - start ).ToString( "F1" ) + " s, " + ( toShip.magnitude / unitsPerKm ).ToString( "F2" ) + " km, speed " + playerData.m_general.m_currentSpeed.ToString( "F2" ) + ", direction " + playerData.m_general.m_currentDirection.ToString( "F2" ) + ", running " + ( ( current == null ) ? "nothing" : current.GetType().Name ) + ", message [" + MessageList() + "]" );
				}

				yield return null;
			}

			seconds = Time.time - start;
		}

		yield return Frames( 10 );

		var locationAfterReturn = playerData.m_general.m_location;

		// ---- 2. out again, from 8 km: the fire button stops it on the way
		yield return DisembarkNow( done );

		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		PutTheVehicleAt( new Vector3( ship.x, 0.0f, ship.z + 8.0f * unitsPerKm ) );

		yield return Frames( 5 );

		var stoppedKm = 8.0f;
		var stoppedRunning = true;
		var stoppedLocation = playerData.m_general.m_location;

		if ( returnIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, returnIndex );

			for ( var end = Time.time + 2.0f; Time.time < end; )
			{
				yield return null;
			}

			yield return Tap( Key.Enter );
			yield return Frames( 30 );

			var toShip = ship - playerData.m_general.m_lastDisembarkedCoordinates;

			toShip.y = 0.0f;
			stoppedKm = toShip.magnitude / unitsPerKm;
			stoppedRunning = GetField( buttonController, "m_currentButton" ) != null;
			stoppedLocation = playerData.m_general.m_location;
		}

		// ---- 3. no headway (the vehicle cannot move): it stops and says the way is blocked (once it has stopped coasting from the stop before)
		var speedMultiplier = controller.m_terrainVehicle.m_speedMultiplier;
		var blockedMessage = "";
		var blockedRunning = true;

		controller.m_terrainVehicle.m_speedMultiplier = 0.0f;

		for ( var end = Time.time + 5.0f; ( Time.time < end ) && ( playerData.m_general.m_currentSpeed >= 0.1f ); )
		{
			yield return null;
		}

		if ( returnIndex >= 0 )
		{
			PressButtonLabelled( ButtonController.ButtonSet.TerrainVehicleWeapon, "Return" );

			for ( var end = Time.time + 10.0f; ( Time.time < end ) && ( GetField( buttonController, "m_currentButton" ) != null ); )
			{
				yield return null;
			}

			blockedMessage = MessageList();
			blockedRunning = GetField( buttonController, "m_currentButton" ) != null;
		}

		controller.m_terrainVehicle.m_speedMultiplier = speedMultiplier;

		if ( blockedRunning )
		{
			buttonController.DeactivateButton();
		}

		// ---- 4. planet 29 (molten): lava between the vehicle and the ship
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 5 );
		yield return GoIntoOrbit( 7, 29 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );
		yield return DisembarkNow( done );

		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		var lavaFound = FindSolidGroundByTheLiquid( out var solid, out var lava );
		var lavaMessage = "";
		var lavaRunning = true;
		var reachedLava = false;
		var lavaLocation = playerData.m_general.m_location;

		if ( lavaFound && ( returnIndex >= 0 ) )
		{
			// the ship beyond the lava, 50 units past it on the line from the vehicle
			var across = lava - solid;
			float longitude, latitude;

			Tools.WorldToLatLongCoordinates( lava + across.normalized * 50.0f, out longitude, out latitude );

			playerData.m_general.m_selectedLatitude = latitude;
			playerData.m_general.m_selectedLongitude = longitude;

			PutTheVehicleAt( solid );

			yield return Frames( 5 );

			PressButtonLabelled( ButtonController.ButtonSet.TerrainVehicleWeapon, "Return" );

			for ( var end = Time.time + 10.0f; ( Time.time < end ) && ( GetField( buttonController, "m_currentButton" ) != null ); )
			{
				var driven = playerData.m_general.m_lastDisembarkedCoordinates - solid;

				reachedLava |= Vector3.Dot( driven, across.normalized ) >= across.magnitude - 2.0f;

				yield return null;
			}

			lavaMessage = MessageList();
			lavaRunning = GetField( buttonController, "m_currentButton" ) != null;
			lavaLocation = playerData.m_general.m_location;
		}

		Log( "returnorder: Tools [" + toolLabels + "]; Return from 6 km: " + locationAfterReturn + " after " + seconds.ToString( "F1" ) + " s, nearest " + nearestKm.ToString( "F2" ) + " km, fuel " + fuelBefore.ToString( "F4" ) + " -> " + lowestFuel.ToString( "F4" ) + " at the lowest" );
		Log( "returnorder: from 8 km, Enter after 2 s: " + stoppedLocation + " at " + stoppedKm.ToString( "F2" ) + " km, still running " + stoppedRunning + "; no headway: running " + blockedRunning + " [" + blockedMessage + "]; lava (found " + lavaFound + " at " + solid + "): " + lavaLocation + ", running " + lavaRunning + ", reached the lava " + reachedLava + " [" + lavaMessage + "]" );

		Check( "returnorder: the vehicle's Tools have Return", returnIndex >= 0, toolLabels );
		Check( "returnorder: from 6 km Return drives the vehicle back by itself and takes it aboard beside the ship (within 1.5 km), on its fuel", ( locationAfterReturn == PD_General.Location.Planetside ) && ( nearestKm <= 1.55f ) && ( seconds < 20.0f ) && ( lowestFuel < fuelBefore - 0.001f ), locationAfterReturn + ", nearest " + nearestKm.ToString( "F2" ) + " km, fuel " + fuelBefore.ToString( "F4" ) + " -> " + lowestFuel.ToString( "F4" ) );
		Check( "returnorder: the fire button stops it on the way, nearer than it started", ( stoppedLocation == PD_General.Location.Disembarked ) && !stoppedRunning && ( stoppedKm < 7.5f ) && ( stoppedKm > MoveButton.c_boardingDistanceKm ), stoppedLocation + " at " + stoppedKm.ToString( "F2" ) + " km, running " + stoppedRunning );
		Check( "returnorder: a vehicle that makes no headway stops and says the way is blocked", !blockedRunning && blockedMessage.Contains( "blocked" ), "running " + blockedRunning + " [" + blockedMessage + "]" );
		Check( "returnorder: lava between the vehicle and the ship stops it short of the lava, and says so", lavaFound && !lavaRunning && !reachedLava && ( lavaLocation == PD_General.Location.Disembarked ) && lavaMessage.Contains( "lava" ), "found " + lavaFound + ", running " + lavaRunning + ", reached " + reachedLava + ", " + lavaLocation + " [" + lavaMessage + "]" );

		Finish( "scenario=returnorder checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the terrain vehicle's Send button (TVSendCargoButton, since 2026-10-17)

	// how much of an element the ship is carrying
	static int ShipCargo( int elementId )
	{
		var elementStorage = DataController.m_instance.m_playerData.m_playerShip.m_elementStorage;
		var elementReference = ( elementStorage == null ) ? null : elementStorage.Find( elementId );

		return ( elementReference == null ) ? 0 : elementReference.m_volume;
	}

	// on planet 94: the terrain vehicle's cargo list has Send; 10 km from the ship it beams what the vehicle carries into the ship's hold (a crate shimmers away on
	// the vehicle) and the list closes; 25 km out it refuses; with room for 0.2 cubic meters in the ship's hold it sends what fits and keeps the rest in the list,
	// and with none it sends nothing
	IEnumerator ScenarioSendCargo()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;
		var done = new bool[ 1 ];

		EnsureCrew();

		controller.m_encounterRange = 0.0f;

		yield return LandOnPlanet94At( Tools.LatLongToWorldCoordinates( 4.3f, -16.0f ), done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=sendcargo abort: no landing (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		// Move runs when the vehicle comes out: stop it, as the player does before using the console
		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		var iron = gameData.FindElementId( "Iron" );
		var ship = Tools.LatLongToWorldCoordinates( playerData.m_general.m_selectedLatitude, playerData.m_general.m_selectedLongitude );
		var unitsPerKm = 2048.0f / 225.0f;
		var vehicle = playerData.m_terrainVehicle;

		// the vehicle at a distance from the ship (flat, as driving keeps it), with the cargo list open
		Action<float> putTheVehicle = ( km ) =>
		{
			var place = new Vector3( ship.x + km * unitsPerKm, 0.0f, ship.z );

			playerData.m_general.m_coordinates = place;
			playerData.m_general.m_lastDisembarkedCoordinates = place;
			controller.m_terrainVehicle.transform.localPosition = place;
		};

		var cargoLabels = ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicleCargo );
		var sendIndex = Array.IndexOf( cargoLabels.Split( ',' ), "Send" );

		// ---- 1. 10 km out with 5.0 cubic meters of iron
		putTheVehicle( 10.0f );
		vehicle.AddElement( iron, 50 );

		yield return Frames( 5 );

		var shipIronBefore = ShipCargo( iron );

		new TVCargoButton().Execute();

		var listOpen = buttonController.GetCurrentButtonSet() == ButtonController.ButtonSet.TerrainVehicleCargo;
		var crateShown = false;

		if ( sendIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleCargo, sendIndex );

			yield return Frames( 3 );

			crateShown = GameObject.Find( "Transported Cargo" ) != null;
		}

		var sentMessage = MessageList();
		var vehicleAfterSend = vehicle.m_volumeUsed;
		var shipIronAfterSend = ShipCargo( iron );
		var setAfterSend = buttonController.GetCurrentButtonSet();

		// ---- 2. 25 km out with 3.0 cubic meters: beyond the transporter's reach
		putTheVehicle( 25.0f );
		vehicle.AddElement( iron, 30 );

		yield return Frames( 5 );

		new TVCargoButton().Execute();

		if ( sendIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleCargo, sendIndex );
		}

		yield return Frames( 3 );

		var farMessage = MessageList();
		var vehicleAfterFar = vehicle.m_volumeUsed;

		// ---- 3. back at 10 km, with room for 0.2 cubic meters in the ship's hold: what fits goes, the rest stays in the list
		putTheVehicle( 10.0f );
		playerData.m_playerShip.AddElement( iron, playerData.m_playerShip.GetRemainingVolume() - 2 );

		yield return Frames( 5 );

		if ( buttonController.GetCurrentButtonSet() != ButtonController.ButtonSet.TerrainVehicleCargo )
		{
			new TVCargoButton().Execute();
		}

		if ( sendIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleCargo, sendIndex );
		}

		yield return Frames( 3 );

		var partMessage = MessageList();
		var vehicleAfterPart = vehicle.m_volumeUsed;
		var setAfterPart = buttonController.GetCurrentButtonSet();

		// ---- 4. and with no room at all, nothing goes
		if ( sendIndex >= 0 )
		{
			PressButton( ButtonController.ButtonSet.TerrainVehicleCargo, sendIndex );
		}

		yield return Frames( 3 );

		var fullMessage = MessageList();
		var vehicleAfterFull = vehicle.m_volumeUsed;

		Log( "sendcargo: the cargo list [" + cargoLabels + "] (open " + listOpen + "); from 10 km with 5.0 of iron: the vehicle " + vehicleAfterSend + ", the ship's iron " + shipIronBefore + " -> " + shipIronAfterSend + ", crate " + crateShown + ", then " + setAfterSend + " [" + sentMessage + "]" );
		Log( "sendcargo: from 25 km with 3.0: the vehicle " + vehicleAfterFar + " [" + farMessage + "]; with room for 0.2: the vehicle " + vehicleAfterPart + ", " + setAfterPart + " [" + partMessage + "]; with none: " + vehicleAfterFull + " [" + fullMessage + "]" );

		Check( "sendcargo: the terrain vehicle's cargo list has Send", listOpen && ( sendIndex >= 0 ), cargoLabels );
		Check( "sendcargo: 10 km from the ship Send beams the vehicle's cargo into the ship's hold, a crate shimmers away on the vehicle, and the list closes", ( vehicleAfterSend == 0 ) && ( shipIronAfterSend == shipIronBefore + 50 ) && crateShown && ( setAfterSend == ButtonController.ButtonSet.TerrainVehicle ) && sentMessage.Contains( "5.0 cubic meters of cargo transported" ), "vehicle " + vehicleAfterSend + ", ship " + shipIronBefore + " -> " + shipIronAfterSend + ", crate " + crateShown + ", " + setAfterSend );
		Check( "sendcargo: 25 km out it is beyond the transporter's reach and nothing goes", ( vehicleAfterFar == 30 ) && farMessage.Contains( "beyond the transporter" ), vehicleAfterFar + " [" + farMessage + "]" );
		Check( "sendcargo: with room for 0.2 cubic meters in the ship, that much goes and the rest stays in the open list", ( vehicleAfterPart == 28 ) && ( setAfterPart == ButtonController.ButtonSet.TerrainVehicleCargo ) && partMessage.Contains( "did not fit" ), vehicleAfterPart + ", " + setAfterPart + " [" + partMessage + "]" );
		Check( "sendcargo: with no room in the ship nothing goes, and it says so", ( vehicleAfterFull == 28 ) && fullMessage.Contains( "no room" ), vehicleAfterFull + " [" + fullMessage + "]" );

		Finish( "scenario=sendcargo checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the ground detail setting (GroundDetail, since 2026-10-17)

	// sets the ground detail for a test, leaving the player's setting as it is (looked up by name: the code before has no ground detail)
	static void SetGroundDetailForTheTest( string setting )
	{
		var type = typeof( PlayerData ).Assembly.GetType( "GroundDetail" );

		if ( type == null )
		{
			return;
		}

		type.GetMethod( "SetSetting" ).Invoke( null, new object[] { Enum.Parse( type.GetNestedType( "Setting" ), setting ), false } );
	}

	// on planet 94 in the terrain vehicle: the ground detail makes the terrain grid 129 vertices to a ring's side in 3 rings at Low (16 bit indices), 257 in 3 at
	// Medium and 257 in 4 at High (more than 65535 vertices, 32 bit indices), at once when it changes; Auto takes Low without a graphics device; the save panel's
	// Colors screen has a Ground row with Auto, Low, Medium and High that marks the setting in use and changes it; the player's own setting is put back
	// afterwards; with -Graphics, a picture of the ground at each level and of the Colors screen in Logs/screen-pictures/ground-detail/
	IEnumerator ScenarioGroundDetail()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var done = new bool[ 1 ];
		var hasGraphics = SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null;
		var folder = ScreenPictureFolder( "ground-detail" );

		EnsureCrew();

		controller.m_encounterRange = 0.0f;

		// the player's own setting, put back at the end (the probe runs in the editor, whose settings are the player's)
		var key = "Ground Detail";
		var savedSetting = PlayerPrefs.HasKey( key ) ? PlayerPrefs.GetString( key ) : null;

		// the project's shadows, before the terrain vehicle goes out
		Func<string> shadowsNow = () => QualitySettings.shadows + "/" + QualitySettings.shadowResolution + "/" + QualitySettings.shadowCascades + "/" + QualitySettings.shadowDistance.ToString( "F0" );
		var projectShadows = shadowsNow();

		yield return LandOnPlanet94At( Tools.LatLongToWorldCoordinates( 4.3f, -16.0f ), done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=grounddetail abort: no landing (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		var type = typeof( PlayerData ).Assembly.GetType( "GroundDetail" );
		var autoLevel = ( type != null ) ? type.GetMethod( "DetectLevel" ).Invoke( null, null ).ToString() : "(none)";
		var grid = controller.m_disembarked.m_terrainGrid;
		var details = new Dictionary<string, int>();
		var grains = new Dictionary<string, string>();
		var cavities = new Dictionary<string, float>();
		var shadows = new Dictionary<string, string>();
		var randomStateBefore = UnityEngine.Random.state;
		var rings = new Dictionary<string, int>();
		var vertices = new Dictionary<string, int>();
		var formats = new Dictionary<string, string>();

		// ---- 1. each level, the grid made again at once
		foreach ( var level in new[] { "Low", "Medium", "High" } )
		{
			SetGroundDetailForTheTest( level );

			yield return Frames( 5 );

			var mesh = grid.GetComponent<MeshFilter>().sharedMesh;

			// (the grain laid over the ground at this level, as the material has it: GroundGrain)
			var groundMaterial = FieldOrNull( grid, "m_material" ) as Material;

			cavities[ level ] = ( groundMaterial == null ) ? -1.0f : groundMaterial.GetFloat( "SF_GroundCavityStrength" );
			shadows[ level ] = shadowsNow();
			grains[ level ] = ( groundMaterial == null ) ? "(no material)" : groundMaterial.GetVector( "SF_GroundGrainParams" ).x.ToString( "F2" ) + " " + ( ( groundMaterial.GetTexture( "SF_GroundGrainMap" ) is Texture grainMapOf ) ? grainMapOf.name : "none" );

			if ( groundMaterial != null )
			{
				var grainMap = groundMaterial.GetTexture( "SF_GroundGrainMap" );

				if ( hasGraphics && ( grainMap is Texture2D grainTexture ) && ( level == "High" ) )
				{
					// the grain texture itself, as a picture (copied through a render texture, as the texture is not readable)
					var copy = RenderTexture.GetTemporary( grainTexture.width, grainTexture.height, 0, RenderTextureFormat.ARGB32, RenderTextureReadWrite.Linear );

					Graphics.Blit( grainTexture, copy );

					var previous = RenderTexture.active;

					RenderTexture.active = copy;

					var readable = new Texture2D( grainTexture.width, grainTexture.height, TextureFormat.RGBA32, false, true );

					readable.ReadPixels( new Rect( 0, 0, grainTexture.width, grainTexture.height ), 0, 0 );
					readable.Apply();

					RenderTexture.active = previous;
					RenderTexture.ReleaseTemporary( copy );

					System.IO.File.WriteAllBytes( System.IO.Path.Combine( folder, "grain.png" ), readable.EncodeToPNG() );
					UnityEngine.Object.Destroy( readable );
				}

				Log( "grounddetail: the camera is " + Vector3.Distance( Camera.main.transform.position, controller.m_terrainVehicle.transform.position ).ToString( "F0" ) + " from the vehicle, field of view " + Camera.main.fieldOfView.ToString( "F1" ) + ", far plane " + Camera.main.farClipPlane.ToString( "F0" ) );
				Log( "grounddetail: at " + level + " the ground's grain " + groundMaterial.GetVector( "SF_GroundGrainParams" ).ToString( "F3" ) + ", map " + ( ( grainMap != null ) ? grainMap.name : "none" ) + ", shader " + groundMaterial.shader.name + ", renderer's material is it " + ( grid.GetComponent<MeshRenderer>().sharedMaterial == groundMaterial ) );
			}

			details[ level ] = grid.m_detail;
			rings[ level ] = grid.m_numLevels;
			vertices[ level ] = ( mesh != null ) ? mesh.vertexCount : 0;
			formats[ level ] = ( mesh != null ) ? mesh.indexFormat.ToString() : "(none)";

			if ( hasGraphics )
			{
				RenderWholeFramePicture( Camera.main, System.IO.Path.Combine( folder, level.ToLowerInvariant() + ".png" ) );
			}
		}

		// ---- 2. the Colors screen's Ground row, with Auto in use
		SetGroundDetailForTheTest( "Auto" );

		PressEscape();

		yield return new WaitForSecondsRealtime( 1.5f );

		var savePanel = PanelController.m_instance.m_saveGamePanel;

		Call( savePanel, "ColorsClicked" );

		yield return Frames( 10 );

		var groundButtons = FieldOrNull( savePanel, "m_groundDetailButtons" ) as UnityEngine.UI.Button[];
		var groundMarkers = FieldOrNull( savePanel, "m_groundDetailMarkers" ) as UnityEngine.UI.Image[];
		var groundLabels = ( groundButtons != null ) ? string.Join( ",", Array.ConvertAll( groundButtons, button => button.GetComponentInChildren<TMPro.TMP_Text>( true ).text ) ) : "(none)";
		var markedBefore = ( groundMarkers != null ) ? Array.FindIndex( groundMarkers, marker => ( marker != null ) && marker.enabled ) : -1;

		if ( hasGraphics )
		{
			RenderScreenPicture( System.IO.Path.Combine( folder, "colors.png" ) );
		}

		// its Medium button: the setting, the marker and the grid follow
		var markedAfter = -1;
		var detailAfter = 0;

		if ( ( groundButtons != null ) && ( groundButtons.Length == 4 ) )
		{
			groundButtons[ 2 ].onClick.Invoke();

			yield return Frames( 5 );

			markedAfter = Array.FindIndex( groundMarkers, marker => ( marker != null ) && marker.enabled );
			detailAfter = grid.m_detail;
		}

		var settingAfter = ( type != null ) ? type.GetMethod( "GetSetting" ).Invoke( null, null ).ToString() : "(none)";

		// the player's own setting back, in the file and in the game
		if ( savedSetting == null )
		{
			PlayerPrefs.DeleteKey( key );
		}
		else
		{
			PlayerPrefs.SetString( key, savedSetting );
		}

		PlayerPrefs.Save();

		SetGroundDetailForTheTest( savedSetting ?? "Auto" );

		Call( savePanel, "CancelClicked" );

		// back in the ship: the project's shadows again
		yield return Frames( 5 );

		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 5 );

		var shadowsInTheShip = shadowsNow();

		Func<string, string> state = level => details[ level ] + " x " + rings[ level ] + " rings, " + vertices[ level ] + " vertices, " + formats[ level ];

		Log( "grounddetail: Auto takes " + autoLevel + " here (graphics device " + hasGraphics + ", " + SystemInfo.graphicsMemorySize + " MB); Low " + state( "Low" ) + "; Medium " + state( "Medium" ) + "; High " + state( "High" ) );
		Log( "grounddetail: the Colors screen's Ground row [" + groundLabels + "], marked " + markedBefore + " with Auto in use; after its Medium button: marked " + markedAfter + ", setting " + settingAfter + ", grid " + detailAfter + "; the player's setting put back: " + ( savedSetting ?? "(none)" ) );

		Check( "grounddetail: Auto takes Low without a graphics device (a headless run)", hasGraphics || ( autoLevel == "Low" ), autoLevel );
		Check( "grounddetail: at Low the terrain grid is 129 vertices to a ring's side in 3 rings, with 16 bit indices", ( details[ "Low" ] == 129 ) && ( rings[ "Low" ] == 3 ) && ( formats[ "Low" ] == "UInt16" ), state( "Low" ) );
		Check( "grounddetail: at Medium it is 257 to a side in 3 rings, more than 65535 vertices with 32 bit indices", ( details[ "Medium" ] == 257 ) && ( rings[ "Medium" ] == 3 ) && ( vertices[ "Medium" ] > 65535 ) && ( formats[ "Medium" ] == "UInt32" ), state( "Medium" ) );
		Check( "grounddetail: at High it is 257 to a side in 4 rings", ( details[ "High" ] == 257 ) && ( rings[ "High" ] == 4 ) && ( formats[ "High" ] == "UInt32" ), state( "High" ) );
		var randomUntouched = UnityEngine.Random.state.Equals( randomStateBefore );

		Check( "grounddetail: the grain of the ground up close is laid over it at Medium and High and not at Low, and making it draws no random numbers (everything on a planet is placed from them)", grains[ "Low" ].StartsWith( "0.00" ) && grains[ "Medium" ].StartsWith( "0.60 Ground Grain" ) && grains[ "High" ].StartsWith( "0.80 Ground Grain" ) && randomUntouched, "Low " + grains[ "Low" ] + ", Medium " + grains[ "Medium" ] + ", High " + grains[ "High" ] + ", random numbers untouched " + randomUntouched );
		Check( "grounddetail: the ground's curves are shaded at Medium (0.6) and High (0.9) and not at Low", ( cavities[ "Low" ] == 0.0f ) && ( Mathf.Abs( cavities[ "Medium" ] - 0.6f ) < 0.01f ) && ( Mathf.Abs( cavities[ "High" ] - 0.9f ) < 0.01f ), cavities[ "Low" ].ToString( "F2" ) + " / " + cavities[ "Medium" ].ToString( "F2" ) + " / " + cavities[ "High" ].ToString( "F2" ) );
		Check( "grounddetail: out in the terrain vehicle the shadows are hard, medium, 2 cascades to 300 at Low and very high, 4 cascades to 768 at High, and the project's are back in the ship", ( shadows[ "Low" ] == "HardOnly/Medium/2/300" ) && ( shadows[ "High" ] == "All/VeryHigh/4/768" ) && ( shadowsInTheShip == projectShadows ), "Low " + shadows[ "Low" ] + ", Medium " + shadows[ "Medium" ] + ", High " + shadows[ "High" ] + "; project " + projectShadows + ", in the ship " + shadowsInTheShip );
		Check( "grounddetail: the Colors screen has a Ground row of Auto, Low, Medium and High that marks the setting in use, and its Medium button sets Medium and remakes the grid", ( groundLabels == "Auto,Low,Medium,High" ) && ( markedBefore == 0 ) && ( markedAfter == 2 ) && ( settingAfter == "Medium" ) && ( detailAfter == 257 ), groundLabels + ", marked " + markedBefore + " -> " + markedAfter + ", " + settingAfter + ", grid " + detailAfter );

		Finish( "scenario=grounddetail checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- grass and pebbles on the ground (GroundClutter, since 2026-10-17)

	// how many grass tufts or pebbles the ground clutter drew in the last frame (looked up by name: the code before has none; -1 if there is no clutter)
	static int ClutterDrawn( string method )
	{
		var clutter = FieldOrNull( SpaceflightController.m_instance.m_disembarked, "m_groundClutter" );

		return ( clutter == null ) ? -1 : (int) Call( clutter, method );
	}

	// a cell's grass tufts and pebbles, as text of their places (empty if there is no clutter)
	static string ClutterCell( Vector2Int cell, out Matrix4x4[] grass, out Matrix4x4[] pebbles )
	{
		grass = new Matrix4x4[ 0 ];
		pebbles = new Matrix4x4[ 0 ];

		var clutter = FieldOrNull( SpaceflightController.m_instance.m_disembarked, "m_groundClutter" );

		if ( clutter == null )
		{
			return "";
		}

		var args = new object[] { cell, null, null };

		clutter.GetType().GetMethod( "GetCell" ).Invoke( clutter, args );

		grass = (Matrix4x4[]) args[ 1 ];
		pebbles = (Matrix4x4[]) args[ 2 ];

		var text = "";

		foreach ( var matrix in grass )
		{
			text += matrix.GetColumn( 3 ).ToString( "F2" );
		}

		foreach ( var matrix in pebbles )
		{
			text += matrix.GetColumn( 3 ).ToString( "F2" );
		}

		return text;
	}

	// on planet 92 (life): no grass or pebbles at Low, and both at High about the terrain vehicle; a cell's grass and pebbles are where they were after the vehicle
	// has driven far away and come back; filling the cells draws no random numbers; nothing stands in water or lava; on planet 94 (no life) pebbles and no grass;
	// with -Graphics, pictures in Logs/screen-pictures/ground-clutter/
	IEnumerator ScenarioGroundClutter()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var done = new bool[ 1 ];
		var hasGraphics = SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null;
		var folder = ScreenPictureFolder( "ground-clutter" );

		EnsureCrew();

		controller.m_encounterRange = 0.0f;

		// the player's own setting, put back at the end
		var key = "Ground Detail";
		var savedSetting = PlayerPrefs.HasKey( key ) ? PlayerPrefs.GetString( key ) : null;

		// ---- 1. planet 92, which has life
		yield return LandInTheArthSystemAt( 92, Vector3.zero, done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=groundclutter abort: no landing on planet 92 (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		SetGroundDetailForTheTest( "Low" );

		yield return Frames( 3 );

		var grassLow = ClutterDrawn( "GetGrassDrawn" );
		var pebblesLow = ClutterDrawn( "GetPebblesDrawn" );

		SetGroundDetailForTheTest( "High" );

		yield return Frames( 3 );

		var grassHigh = ClutterDrawn( "GetGrassDrawn" );
		var pebblesHigh = ClutterDrawn( "GetPebblesDrawn" );

		if ( hasGraphics )
		{
			RenderWholeFramePicture( Camera.main, System.IO.Path.Combine( folder, "planet92_high.png" ) );
		}

		// the cells about the vehicle: nothing in water (or lava), and one cell's places, again after driving far away and back
		var vehicle = controller.m_terrainVehicle.transform.position;
		var generator = FieldOrNull( controller.m_disembarked, "m_planetGenerator" ) as PlanetGenerator;
		var center = new Vector2Int( Mathf.FloorToInt( vehicle.x / 8.0f ), Mathf.FloorToInt( vehicle.z / 8.0f ) );
		var inLiquid = 0;
		var counted = 0;
		var busiest = center;
		var busiestCount = -1;

		for ( var z = -4; z <= 4; z++ )
		{
			for ( var x = -4; x <= 4; x++ )
			{
				var cell = new Vector2Int( center.x + x, center.y + z );

				ClutterCell( cell, out var grass, out var pebbles );

				var both = new List<Matrix4x4>( grass );

				both.AddRange( pebbles );

				foreach ( var matrix in both )
				{
					var place = matrix.GetColumn( 3 );

					Tools.WorldToMapCoordinates( place, out var mapX, out var mapY, generator.m_textureMapWidth, generator.m_textureMapHeight );

					counted++;

					if ( generator.GetBicubicSmoothedElevation( mapX, mapY ) <= generator.m_waterElevation )
					{
						inLiquid++;
					}
				}

				if ( grass.Length + pebbles.Length > busiestCount )
				{
					busiestCount = grass.Length + pebbles.Length;
					busiest = cell;
				}
			}
		}

		// filling a cell draws no random numbers (a cell far off, not filled yet, with no frame in between: the game draws its own as it runs)
		var randomBefore = UnityEngine.Random.state;

		ClutterCell( new Vector2Int( center.x + 500, center.y + 500 ), out _, out _ );

		var randomUntouched = UnityEngine.Random.state.Equals( randomBefore );
		var placesBefore = ClutterCell( busiest, out _, out _ );
		var home = playerData.m_general.m_coordinates;
		var away = home + new Vector3( 2000.0f, 0.0f, 0.0f );

		playerData.m_general.m_coordinates = away;
		playerData.m_general.m_lastDisembarkedCoordinates = away;
		controller.m_terrainVehicle.transform.localPosition = away;

		yield return Frames( 5 );

		playerData.m_general.m_coordinates = home;
		playerData.m_general.m_lastDisembarkedCoordinates = home;
		controller.m_terrainVehicle.transform.localPosition = home;

		yield return Frames( 5 );

		var placesAfter = ClutterCell( busiest, out _, out _ );

		// ---- 2. planet 94, which has no life
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 5 );
		yield return LandOnPlanet94At( Tools.LatLongToWorldCoordinates( 4.3f, -16.0f ), done );
		yield return Frames( 3 );

		var grass94 = ClutterDrawn( "GetGrassDrawn" );
		var pebbles94 = ClutterDrawn( "GetPebblesDrawn" );

		if ( hasGraphics )
		{
			RenderWholeFramePicture( Camera.main, System.IO.Path.Combine( folder, "planet94_high.png" ) );
		}

		// the player's own setting back
		if ( savedSetting == null )
		{
			PlayerPrefs.DeleteKey( key );
		}
		else
		{
			PlayerPrefs.SetString( key, savedSetting );
		}

		PlayerPrefs.Save();

		SetGroundDetailForTheTest( savedSetting ?? "Auto" );

		Log( "groundclutter: planet 92 (bio " + DataController.m_instance.m_gameData.m_planetList[ 92 ].m_bioDensity + "): Low " + grassLow + " grass, " + pebblesLow + " pebbles; High " + grassHigh + " grass, " + pebblesHigh + " pebbles; random numbers untouched " + randomUntouched + "; " + inLiquid + " of " + counted + " in liquid; cell " + busiest + " (" + busiestCount + ") the same after driving away and back " + ( placesBefore == placesAfter ) + "; planet 94 (bio " + DataController.m_instance.m_gameData.m_planetList[ 94 ].m_bioDensity + "): " + grass94 + " grass, " + pebbles94 + " pebbles" );

		Check( "groundclutter: at Low no grass or pebbles are drawn", ( grassLow == 0 ) && ( pebblesLow == 0 ), grassLow + " / " + pebblesLow );
		Check( "groundclutter: at High grass and pebbles are drawn about the terrain vehicle on a planet with life", ( grassHigh > 50 ) && ( pebblesHigh > 50 ), grassHigh + " / " + pebblesHigh );
		Check( "groundclutter: filling the cells draws no random numbers (everything on a planet is placed from them)", randomUntouched, randomUntouched.ToString() );
		Check( "groundclutter: nothing stands in water or lava", ( counted > 0 ) && ( inLiquid == 0 ), inLiquid + " of " + counted );
		Check( "groundclutter: a cell's grass and pebbles are in the same places after the vehicle has driven far away and come back", ( busiestCount > 0 ) && ( placesBefore == placesAfter ), busiest + ": " + busiestCount + ", same " + ( placesBefore == placesAfter ) );
		Check( "groundclutter: on a planet with no life there are pebbles and no grass", ( grass94 == 0 ) && ( pebbles94 > 50 ), grass94 + " / " + pebbles94 );

		// a build keeps the shader's instanced variants only for the materials in it that have instancing on: the clutter's materials are made from such an asset
		// (made from the shader alone, a build drew none of them; the probe runs in the Editor, which never strips, so this checks what the build relies on)
		var clutterTemplate = Resources.Load<Material>( "Materials/Ground Clutter" );
		var templateFits = ( clutterTemplate != null ) && clutterTemplate.enableInstancing && ( clutterTemplate.shader != null ) && ( clutterTemplate.shader.name == "Starflight/Ground Clutter" );

		Check( "groundclutter: the clutter's materials come from a material asset with instancing on (or a build strips the instanced variants)", templateFits, ( clutterTemplate == null ) ? "no asset" : ( clutterTemplate.shader.name + ", instancing " + clutterTemplate.enableInstancing ) );

		Finish( "scenario=groundclutter checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the ship's steering (ManeuverButton, since 2026-10-17)

	// with Maneuver running and the ship flying east, hold the right arrow, then the up arrow, and measure how far the flight direction is from north three frames
	// later; then up and right together, and how far it is from the diagonal; then how far the ship's model is from the flight direction half a second on (the code
	// before the change has no model direction of its own, and its model faced the flight direction); then no key, and the speed
	IEnumerator SteerAndMeasure( float[] measured )
	{
		var controller = SpaceflightController.m_instance;
		var general = DataController.m_instance.m_playerData.m_general;

		if ( !( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton ) )
		{
			PressButton( ButtonController.ButtonSet.NavigationA, 0 );

			yield return Frames( 10 );
		}

		measured[ 4 ] = ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton ) ? 1.0f : 0.0f;

		// flying east already, so that the code before (which eased the heading round) is there too
		general.m_currentDirection = Vector3.right;

		HoldKeys( Key.RightArrow );

		for ( var end = Time.time + 0.3f; Time.time < end; )
		{
			yield return null;
		}

		measured[ 5 ] = Vector3.Angle( general.m_currentDirection, Vector3.right );

		HoldKeys( Key.UpArrow );

		yield return Frames( 3 );

		measured[ 0 ] = Vector3.Angle( general.m_currentDirection, Vector3.forward );

		HoldKeys( Key.UpArrow, Key.RightArrow );

		yield return Frames( 3 );

		measured[ 1 ] = Vector3.Angle( general.m_currentDirection, new Vector3( 1.0f, 0.0f, 1.0f ) );

		for ( var end = Time.time + 0.5f; Time.time < end; )
		{
			yield return null;
		}

		var model = FieldOrNull( controller.m_playerShip, "m_modelDirection" );
		var modelDirection = ( model is Vector3 ) ? (Vector3) model : general.m_currentDirection;

		measured[ 2 ] = Vector3.Angle( modelDirection, general.m_currentDirection );

		HoldKeys();

		yield return Frames( 3 );

		measured[ 3 ] = general.m_currentSpeed;

		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		yield return Frames( 3 );
	}

	// the ship flies the way the stick points at once, as the original's (each step goes the way of the key held, HYPER-OV (XYSCAN)): in a star system and in
	// hyperspace the up arrow after the right turns the flight from east to north within three frames (the code before eased the heading round over a second,
	// which swung the ship wide past the planets at the original's speed), up and right together fly the diagonal at once, the ship's model turns after the flight
	// direction within half a second, and with no key held the ship stops at once
	IEnumerator ScenarioSteering()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var general = playerData.m_general;
		var starSystem = controller.m_starSystem;
		var system = new float[ 6 ];
		var hyperspace = new float[ 6 ];

		EnsureCrew();

		// a ship that survives whatever it meets, and no encounter able to begin
		playerData.m_playerShip.m_armorPoints = 100000;

		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		SetSystemHealth( 0, 100 );

		// ---- 1. the star system of Arth, after launching from the Starport
		controller.SwitchLocation( PD_General.Location.JustLaunched );

		for ( var end = Time.realtimeSinceStartup + 60.0f; ( Time.realtimeSinceStartup < end ) && starSystem.GeneratingPlanets(); )
		{
			yield return null;
		}

		yield return Frames( 10 );

		yield return SteerAndMeasure( system );

		var inStarSystem = general.m_location == PD_General.Location.StarSystem;

		// ---- 2. hyperspace, in a quiet corner
		general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 6.0f, 0.0f, 6.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		yield return SteerAndMeasure( hyperspace );

		var inHyperspace = general.m_location == PD_General.Location.Hyperspace;

		controller.m_encounterRange = encounterRange;

		Log( "steering: star system (" + inStarSystem + ", Maneuver " + system[ 4 ] + "): east " + system[ 5 ].ToString( "0.0" ) + " deg off after 0.3 s; north " + system[ 0 ].ToString( "0.0" ) + " deg off 3 frames after the up arrow; diagonal " + system[ 1 ].ToString( "0.0" ) + " off; model " + system[ 2 ].ToString( "0.0" ) + " off after 0.5 s; speed with no key " + system[ 3 ].ToString( "0.0" ) );
		Log( "steering: hyperspace (" + inHyperspace + ", Maneuver " + hyperspace[ 4 ] + "): east " + hyperspace[ 5 ].ToString( "0.0" ) + " deg off after 0.3 s; north " + hyperspace[ 0 ].ToString( "0.0" ) + " deg off 3 frames after the up arrow; diagonal " + hyperspace[ 1 ].ToString( "0.0" ) + " off; model " + hyperspace[ 2 ].ToString( "0.0" ) + " off after 0.5 s; speed with no key " + hyperspace[ 3 ].ToString( "0.0" ) );

		Check( "steering: Maneuver runs and the right arrow flies the ship east, in a star system and in hyperspace (control)", inStarSystem && inHyperspace && ( system[ 4 ] > 0.0f ) && ( hyperspace[ 4 ] > 0.0f ) && ( system[ 5 ] < 1.0f ) && ( hyperspace[ 5 ] < 1.0f ), system[ 5 ].ToString( "0.0" ) + " / " + hyperspace[ 5 ].ToString( "0.0" ) );
		Check( "steering: in a star system the up arrow turns the ship from east to north at once (the code before eased it round over a second)", system[ 0 ] < 1.0f, system[ 0 ].ToString( "0.0" ) + " deg" );
		Check( "steering: in hyperspace the up arrow turns the ship from east to north at once", hyperspace[ 0 ] < 1.0f, hyperspace[ 0 ].ToString( "0.0" ) + " deg" );
		Check( "steering: up and right together fly the diagonal at once", ( system[ 1 ] < 1.0f ) && ( hyperspace[ 1 ] < 1.0f ), system[ 1 ].ToString( "0.0" ) + " / " + hyperspace[ 1 ].ToString( "0.0" ) + " deg" );
		Check( "steering: the ship's model has turned after the flight direction within half a second", ( system[ 2 ] < 2.0f ) && ( hyperspace[ 2 ] < 2.0f ), system[ 2 ].ToString( "0.0" ) + " / " + hyperspace[ 2 ].ToString( "0.0" ) + " deg" );
		Check( "steering: with no key held the ship stops at once", ( system[ 3 ] == 0.0f ) && ( hyperspace[ 3 ] == 0.0f ), system[ 3 ].ToString( "0.0" ) + " / " + hyperspace[ 3 ].ToString( "0.0" ) );

		Finish( "scenario=steering checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the speed by the engines (ROADMAP D8, since 2026-10-17)

	// fits the ship with these engines, cargo pods and armor and nothing else, and works out its mass and acceleration as the Starport does
	static void FitShip( int enginesClass, int cargoPods, int armorClass )
	{
		var ship = DataController.m_instance.m_playerData.m_playerShip;

		ship.m_enginesClass = enginesClass;
		ship.m_numCargoPods = cargoPods;
		ship.m_armorClass = armorClass;
		ship.m_shieldingClass = 0;
		ship.m_missileLauncherClass = 0;
		ship.m_laserCannonClass = 0;
		ship.RecalculateMass();
		ship.RecalculateVolume();
		ship.RecalculateAcceleration();
	}

	// from a standstill over Arth's sun, held there (or where the ship is in hyperspace), flies east or west and gives back the speed after a second and after six
	IEnumerator FlyFromStandstill( Vector3 direction, float[] speeds )
	{
		var controller = SpaceflightController.m_instance;
		var general = DataController.m_instance.m_playerData.m_general;

		if ( general.m_location == PD_General.Location.StarSystem )
		{
			general.m_coordinates = Vector3.zero;
			general.m_lastStarSystemCoordinates = Vector3.zero;
			controller.m_playerShip.transform.position = Vector3.zero;
		}

		general.m_currentSpeed = 0.0f;
		general.m_currentDirection = direction;

		controller.m_playerShip.TurnOnEngines();

		var start = Time.time;

		speeds[ 0 ] = -1.0f;

		var inStarSystem = general.m_location == PD_General.Location.StarSystem;

		while ( Time.time < start + 6.0f )
		{
			general.m_currentDirection = direction;

			// (held over the sun, or six seconds at class 5's speed would carry the ship out of the system: the speed is the engines', wherever the ship is)
			if ( inStarSystem )
			{
				general.m_coordinates = Vector3.zero;
				general.m_lastStarSystemCoordinates = Vector3.zero;
				controller.m_playerShip.transform.position = Vector3.zero;
			}

			if ( ( speeds[ 0 ] < 0.0f ) && ( Time.time >= start + 1.0f ) )
			{
				speeds[ 0 ] = general.m_currentSpeed;
			}

			yield return null;
		}

		speeds[ 1 ] = general.m_currentSpeed;

		controller.m_playerShip.TurnOffEngines();

		yield return Frames( 3 );
	}

	// the speed by the engines (D8: the original's ship flies at one speed whatever its engines): in a star system the top speed of class 1 engines is a third of
	// the original's at GOG's pace (999.4), class 3's two thirds (1998.8) and class 5's all of it (2998.3), and in hyperspace class 1's a third of 371.2 (123.7); a new
	// ship (class 1, 5 G) is all but at its top speed after a second, a ship of 1 G (class 1 engines, 16 pods, class 5 armor) far from it, and one of 25 G (class 5,
	// a bare hull) at it
	IEnumerator ScenarioEngineSpeeds()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var general = playerData.m_general;
		var starSystem = controller.m_starSystem;
		var classOne = new float[ 2 ];
		var classThree = new float[ 2 ];
		var classFive = new float[ 2 ];
		var heavy = new float[ 2 ];
		var hyperspaceClassOne = new float[ 2 ];

		EnsureCrew();

		// a ship that survives whatever it meets, and no encounter able to begin
		playerData.m_playerShip.m_armorPoints = 100000;

		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		SetSystemHealth( 0, 100 );

		// ---- 1. the star system of Arth
		controller.SwitchLocation( PD_General.Location.JustLaunched );

		for ( var end = Time.realtimeSinceStartup + 60.0f; ( Time.realtimeSinceStartup < end ) && starSystem.GeneratingPlanets(); )
		{
			yield return null;
		}

		yield return Frames( 10 );

		PressButton( ButtonController.ButtonSet.NavigationA, 0 );

		yield return Frames( 10 );

		// (Maneuver, while it runs, turns the engines off when no direction is held)
		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		yield return Frames( 3 );

		var inStarSystem = general.m_location == PD_General.Location.StarSystem;

		FitShip( 1, 0, 0 );

		var newShipG = playerData.m_playerShip.m_acceleration;

		yield return FlyFromStandstill( Vector3.right, classOne );

		FitShip( 3, 0, 0 );

		yield return FlyFromStandstill( Vector3.left, classThree );

		FitShip( 5, 0, 0 );

		var bareG = playerData.m_playerShip.m_acceleration;

		yield return FlyFromStandstill( Vector3.right, classFive );

		FitShip( 1, 16, 5 );

		var heavyG = playerData.m_playerShip.m_acceleration;

		yield return FlyFromStandstill( Vector3.left, heavy );

		var stillInStarSystem = general.m_location == PD_General.Location.StarSystem;

		// ---- 2. hyperspace, in a quiet corner, with a new ship
		FitShip( 1, 0, 0 );

		general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 6.0f, 0.0f, 6.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );

		yield return FlyFromStandstill( Vector3.right, hyperspaceClassOne );

		controller.m_encounterRange = encounterRange;

		Log( "enginespeeds: star system (" + inStarSystem + ", still " + stillInStarSystem + "): class 1 (" + newShipG + " G) " + classOne[ 0 ].ToString( "0.0" ) + " after 1 s, " + classOne[ 1 ].ToString( "0.0" ) + " after 6 s; class 3 " + classThree[ 0 ].ToString( "0.0" ) + " / " + classThree[ 1 ].ToString( "0.0" ) + "; class 5 bare (" + bareG + " G) " + classFive[ 0 ].ToString( "0.0" ) + " / " + classFive[ 1 ].ToString( "0.0" ) + "; class 1 heavy (" + heavyG + " G) " + heavy[ 0 ].ToString( "0.0" ) + " / " + heavy[ 1 ].ToString( "0.0" ) + "; hyperspace class 1 " + hyperspaceClassOne[ 0 ].ToString( "0.0" ) + " / " + hyperspaceClassOne[ 1 ].ToString( "0.0" ) );

		Check( "enginespeeds: the ship flies in Arth's star system throughout, and the fits give 5 G for a new ship, 25 G for class 5 engines in a bare hull and 1 G for class 1 engines with 16 pods and class 5 armor (control)", inStarSystem && stillInStarSystem && ( newShipG == 5 ) && ( bareG == 25 ) && ( heavyG == 1 ), newShipG + " / " + bareG + " / " + heavyG + " G" );
		Check( "enginespeeds: class 1 engines' top speed in a star system is a third of the original's at GOG's pace (999.4; the code before gave every ship 2998.3)", Mathf.Abs( classOne[ 1 ] - 2998.272f / 3.0f ) < 0.5f, classOne[ 1 ].ToString( "0.0" ) );
		Check( "enginespeeds: class 3 engines' is two thirds of it (1998.8) and class 5 engines' all of it (2998.3)", ( Mathf.Abs( classThree[ 1 ] - 2998.272f * 2.0f / 3.0f ) < 0.5f ) && ( Mathf.Abs( classFive[ 1 ] - 2998.272f ) < 0.5f ), classThree[ 1 ].ToString( "0.0" ) + " / " + classFive[ 1 ].ToString( "0.0" ) );
		Check( "enginespeeds: in hyperspace class 1 engines' top speed is a third of the original's (123.7)", Mathf.Abs( hyperspaceClassOne[ 1 ] - 371.2f / 3.0f ) < 0.1f, hyperspaceClassOne[ 1 ].ToString( "0.0" ) );
		Check( "enginespeeds: a new ship (5 G) is at its top speed a second after it starts, as the original's 12 steps at GOG's pace", classOne[ 0 ] >= classOne[ 1 ] * 0.95f, classOne[ 0 ].ToString( "0.0" ) + " of " + classOne[ 1 ].ToString( "0.0" ) );
		Check( "enginespeeds: a ship of 1 G is far from its top speed a second after it starts (it takes 5 s), and one of 25 G is at it", ( heavy[ 0 ] < heavy[ 1 ] * 0.4f ) && ( classFive[ 0 ] >= classFive[ 1 ] * 0.999f ), heavy[ 0 ].ToString( "0.0" ) + " of " + heavy[ 1 ].ToString( "0.0" ) + "; " + classFive[ 0 ].ToString( "0.0" ) + " of " + classFive[ 1 ].ToString( "0.0" ) );

		Finish( "scenario=enginespeeds checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the terrain vehicle's model (Terrain Vehicle.fbx, made by DevTools/ShipModels/import_meshy_tv.py)

	// the triangles of a mesh, from its index counts (the model's meshes are not readable)
	static int TriangleCount( Mesh mesh )
	{
		if ( mesh == null )
		{
			return 0;
		}

		var indices = 0L;

		for ( var i = 0; i < mesh.subMeshCount; i++ )
		{
			indices += mesh.GetIndexCount( i );
		}

		return (int) ( indices / 3 );
	}

	IEnumerator ScenarioTvModel()
	{
		var controller = SpaceflightController.m_instance;
		var vehicle = controller.m_terrainVehicle;
		var errorsBefore = s_errorCount;

		EnsureCrew();

		// ---- 1. the model as the scene holds it: the body, the radar and the six wheels, each on its steering joint, in the textured materials
		var model = vehicle.m_terrainVehicleModel;
		var bodyRenderer = ( model != null ) ? model.GetComponent<MeshRenderer>() : null;
		var bodyFilter = ( model != null ) ? model.GetComponent<MeshFilter>() : null;
		var radar = ( model != null ) ? model.transform.Find( "Radar" ) : null;
		var radarRenderer = ( radar != null ) ? radar.GetComponent<MeshRenderer>() : null;
		var radarFilter = ( radar != null ) ? radar.GetComponent<MeshFilter>() : null;
		var bodyMaterial = ( bodyRenderer != null ) ? bodyRenderer.sharedMaterial : null;
		var bodyTextured = ( bodyMaterial != null ) && ( bodyMaterial.name == "Terrain Vehicle Meshy Body" ) && ( bodyMaterial.GetTexture( "_MainTex" ) != null ) && ( bodyRenderer.sharedMaterials.Length == 1 );
		var radarTextured = ( radarRenderer != null ) && ( radarRenderer.sharedMaterial == bodyMaterial );
		var wheelsTextured = 0;
		var wheelsOnJoints = 0;
		var wheelTriangles = 0;

		for ( var i = 0; i < vehicle.m_wheels.Length; i++ )
		{
			var wheel = vehicle.m_wheels[ i ];
			var renderer = ( wheel != null ) ? wheel.GetComponent<MeshRenderer>() : null;
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;

			if ( ( material != null ) && ( material.name == "Terrain Vehicle Meshy Wheel" ) && ( material.GetTexture( "_MainTex" ) != null ) && ( renderer.sharedMaterials.Length == 1 ) )
			{
				wheelsTextured++;
			}

			if ( ( wheel != null ) && System.Array.Exists( vehicle.m_steeringJoints, joint => ( joint != null ) && ( wheel.transform.parent == joint.transform ) ) )
			{
				wheelsOnJoints++;
			}

			var filter = ( wheel != null ) ? wheel.GetComponent<MeshFilter>() : null;

			wheelTriangles = Mathf.Max( wheelTriangles, TriangleCount( ( filter != null ) ? filter.sharedMesh : null ) );
		}

		var bodyTriangles = TriangleCount( ( bodyFilter != null ) ? bodyFilter.sharedMesh : null ) + TriangleCount( ( radarFilter != null ) ? radarFilter.sharedMesh : null );

		Log( "tvmodel: body " + ( ( bodyMaterial != null ) ? bodyMaterial.name : "none" ) + " (" + ( ( bodyRenderer != null ) ? bodyRenderer.sharedMaterials.Length : 0 ) + " materials, textured " + bodyTextured + "), radar " + ( ( radar != null ) ? "found" : "none" ) + " textured " + radarTextured + ", wheels textured " + wheelsTextured + "/" + vehicle.m_wheels.Length + " on joints " + wheelsOnJoints + " | triangles: body " + bodyTriangles + ", a wheel " + wheelTriangles );

		// ---- 2. on the ground of planet 94 (rock): the wheels meet the ground level with each other, the body clears it, the capsule covers the model, the radar turns
		var landed = new bool[ 1 ];

		yield return LandInTheArthSystemAt( 94, Vector3.zero, landed );
		yield return Frames( 10 );

		// each wheel's bottom against the ground under its middle, as the vehicle reads the ground (ApplyElevation)
		var wheelBottoms = new List<float>();
		var wheelGaps = new List<float>();
		var wheelSize = 0.0f;

		foreach ( var wheel in vehicle.m_wheels )
		{
			var renderer = ( wheel != null ) ? wheel.GetComponent<MeshRenderer>() : null;

			if ( renderer == null )
			{
				continue;
			}

			var ground = Call( vehicle, "ApplyElevation", renderer.bounds.center, false );
			var groundHeight = ( ground is Vector3 groundPoint ) ? groundPoint.y : float.NaN;

			wheelBottoms.Add( renderer.bounds.min.y );
			wheelGaps.Add( renderer.bounds.min.y - groundHeight );
			wheelSize = Mathf.Max( wheelSize, renderer.bounds.size.y );
		}

		var lowestWheel = ( wheelBottoms.Count > 0 ) ? Mathf.Min( wheelBottoms.ToArray() ) : 0.0f;
		var bodyBottom = ( bodyRenderer != null ) ? bodyRenderer.bounds.min.y : 0.0f;
		var wheelsLevel = ( wheelGaps.Count == 6 ) && ( wheelSize > 0.0f ) && wheelGaps.TrueForAll( gap => Mathf.Abs( gap ) < 0.3f * wheelSize );
		var bodyClears = ( bodyRenderer != null ) && ( bodyBottom > lowestWheel );

		// the capsule against the model's meshes, in the root's frame (Y along the vehicle, as the capsule lies)
		var root = model.transform;
		var low = Vector3.positiveInfinity;
		var high = Vector3.negativeInfinity;

		foreach ( var filter in model.GetComponentsInChildren<MeshFilter>( false ) )
		{
			if ( filter.sharedMesh == null )
			{
				continue;
			}

			var meshBounds = filter.sharedMesh.bounds;

			for ( var corner = 0; corner < 8; corner++ )
			{
				var local = meshBounds.center + Vector3.Scale( meshBounds.extents, new Vector3( ( corner & 1 ) * 2 - 1, ( ( corner >> 1 ) & 1 ) * 2 - 1, ( ( corner >> 2 ) & 1 ) * 2 - 1 ) );
				var point = root.InverseTransformPoint( filter.transform.TransformPoint( local ) );

				low = Vector3.Min( low, point );
				high = Vector3.Max( high, point );
			}
		}

		var capsule = model.GetComponent<CapsuleCollider>();
		var modelLength = high.y - low.y;
		var modelMiddle = ( low + high ) * 0.5f;
		var capsuleLength = ( capsule != null ) ? capsule.height : 0.0f;
		var centreApart = ( capsule != null ) ? new Vector2( capsule.center.x - modelMiddle.x, capsule.center.y - modelMiddle.y ).magnitude : float.MaxValue;
		var capsuleFits = ( capsule != null ) && ( capsule.direction == 1 ) && ( modelLength > 0.0f ) && ( Mathf.Abs( capsuleLength - modelLength ) < 0.2f * modelLength ) && ( centreApart < 0.15f * modelLength );

		// the radar turns on its mast
		var radarBefore = ( radar != null ) ? radar.localRotation : Quaternion.identity;

		yield return Frames( 20 );

		var radarTurned = ( radar != null ) && ( Quaternion.Angle( radarBefore, radar.localRotation ) > 1.0f );

		// (with -Graphics, a picture of the vehicle on the ground)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "tvmodel-on-94.png" ) );
		}

		Log( "tvmodel: on planet 94 (landed " + landed[ 0 ] + "): wheel bottoms " + string.Join( " ", wheelBottoms.ConvertAll( b => b.ToString( "F2" ) ) ) + ", each above the ground under it by " + string.Join( " ", wheelGaps.ConvertAll( g => g.ToString( "F2" ) ) ) + " (a wheel " + wheelSize.ToString( "F2" ) + " high), body bottom " + bodyBottom.ToString( "F2" ) + " | model " + modelLength.ToString( "F2" ) + " long, capsule " + capsuleLength.ToString( "F2" ) + " (centres " + centreApart.ToString( "F2" ) + " apart) | radar turned " + radarTurned );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "tvmodel: the terrain vehicle is the textured model: the body and its radar in the body's material, all six wheels in the wheel's, one material each", bodyTextured && radarTextured && ( wheelsTextured == 6 ), bodyTextured + " " + radarTextured + " " + wheelsTextured );
		Check( "tvmodel: every wheel is on a steering joint, as TerrainVehicle turns and steers it", ( vehicle.m_wheels.Length == 6 ) && ( wheelsOnJoints == 6 ), wheelsOnJoints.ToString() );
		Check( "tvmodel: the model is light enough: the body under 15,000 triangles, a wheel under 6,000", ( bodyTriangles > 1000 ) && ( bodyTriangles < 15000 ) && ( wheelTriangles > 500 ) && ( wheelTriangles < 6000 ), bodyTriangles + " " + wheelTriangles );
		Check( "tvmodel: on the ground every wheel meets the ground under it and the body clears it", landed[ 0 ] && wheelsLevel && bodyClears, landed[ 0 ] + " " + wheelsLevel + " " + bodyClears );
		Check( "tvmodel: the capsule collider covers the model, as long as it and around its middle", capsuleFits, modelLength.ToString( "F2" ) + " " + capsuleLength.ToString( "F2" ) + " " + centreApart.ToString( "F2" ) );
		Check( "tvmodel: the radar turns on its mast", radarTurned, radarTurned.ToString() );
		Check( "tvmodel: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=tvmodel textured=" + bodyTextured + "/" + wheelsTextured + " triangles=" + bodyTriangles + "/" + wheelTriangles + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the ancient ruins' models (DevTools/ShipModels/import_meshy_props.py)

	IEnumerator ScenarioRuinModels()
	{
		var controller = SpaceflightController.m_instance;
		var ruins = controller.m_disembarked.m_terrainGrid.m_terrainRuins;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// ---- 1. the five templates (the model files themselves): each in its own textured material with the glyphs' glow, light enough, the old ruins' size
		var textured = 0;
		var light = 0;
		var sized = 0;
		var details = new List<string>();

		for ( var i = 0; i < ruins.m_ruinTemplates.Length; i++ )
		{
			var template = ruins.m_ruinTemplates[ i ];
			var renderer = ( template != null ) ? template.GetComponentInChildren<MeshRenderer>( true ) : null;
			var filter = ( template != null ) ? template.GetComponentInChildren<MeshFilter>( true ) : null;
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;
			var mesh = ( filter != null ) ? filter.sharedMesh : null;

			if ( ( material != null ) && ( material.name == "Ancient Ruins " + ( i + 1 ) ) && ( material.GetTexture( "_MainTex" ) != null ) && ( material.GetTexture( "SF_EmissiveMap" ) != null ) && ( renderer.sharedMaterials.Length == 1 ) )
			{
				textured++;
			}

			var triangles = TriangleCount( mesh );

			if ( ( triangles > 1000 ) && ( triangles < 10000 ) )
			{
				light++;
			}

			// (the old ruins stand on a square of 24, and the new ones on the same square)
			var size = ( mesh != null ) ? Vector3.Scale( mesh.bounds.size, filter.transform.lossyScale ) : Vector3.zero;
			var footprint = Mathf.Max( size.x, Mathf.Max( size.y, size.z ) );

			if ( Mathf.Abs( footprint - 24.0f ) < 2.4f )
			{
				sized++;
			}

			details.Add( ( ( template != null ) ? template.name : "none" ) + ": " + ( ( material != null ) ? material.name : "no material" ) + ", " + triangles + " triangles, " + size.ToString( "F1" ) );
		}

		Log( "ruinmodels: " + ruins.m_ruinTemplates.Length + " templates: " + string.Join( " | ", details ) );

		// ---- 2. on the ground of planet 94 (one random ruin): the placed ruin is in its textured material
		yield return LandOnPlanet94At( Vector3.zero, done );

		var randomRuins = RandomRuinsOnTheGround();
		var placedTextured = randomRuins.Count > 0;

		foreach ( var ruin in randomRuins )
		{
			var renderer = ruin.GetComponentInChildren<MeshRenderer>( true );
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;

			placedTextured &= ( material != null ) && material.name.StartsWith( "Ancient Ruins " ) && ( material.GetTexture( "_MainTex" ) != null );
		}

		// (with -Graphics, a picture of the vehicle beside the ruin)
		if ( ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null ) && ( randomRuins.Count > 0 ) )
		{
			var place = randomRuins[ 0 ].transform.position;

			controller.SwitchLocation( PD_General.Location.Planetside );

			yield return Frames( 5 );
			yield return LandOnPlanet94At( place + Vector3.forward * 40.0f, done );
			yield return Frames( 10 );

			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "ruinmodels-on-94.png" ) );
		}

		Log( "ruinmodels: planet 94: " + randomRuins.Count + " random ruins on the ground, in their textured materials " + placedTextured );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "ruinmodels: each of the five ancient ruins is in its own textured material, with the glyphs' glow", ( ruins.m_ruinTemplates.Length == 5 ) && ( textured == 5 ), textured + "/" + ruins.m_ruinTemplates.Length );
		Check( "ruinmodels: each ruin is light enough, under 10,000 triangles", light == 5, light.ToString() );
		Check( "ruinmodels: each ruin stands on the old ruins' square of 24", sized == 5, sized.ToString() );
		Check( "ruinmodels: a ruin placed on the ground is in its textured material", placedTextured, randomRuins.Count + " " + placedTextured );
		Check( "ruinmodels: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=ruinmodels textured=" + textured + " light=" + light + " sized=" + sized + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the rocks' and the deposits' models (DevTools/ShipModels/import_meshy_props.py)

	// the bounding volume of the old rocks and deposits as Unity measured them (their meshes' bounds, in their nodes' frames), by model
	static readonly Dictionary<string, float> c_oldPropVolumes = new Dictionary<string, float>
	{
		{ "Assets/Game Objects/Rocks/Rock 1.fbx", 104.493f }, { "Assets/Game Objects/Rocks/Rock 2.fbx", 153.443f }, { "Assets/Game Objects/Rocks/Rock 3.fbx", 153.564f },
		{ "Assets/Game Objects/Rocks/Rock 4.fbx", 162.890f }, { "Assets/Game Objects/Rocks/Rock 5.fbx", 64.001f }, { "Assets/Game Objects/Rocks/Rock 6.fbx", 141.581f },
		{ "Assets/Game Objects/Rocks/Rock 7.fbx", 99.067f }, { "Assets/Game Objects/Rocks/Rock 8.fbx", 83.338f }, { "Assets/Game Objects/Rocks/Rock 9.fbx", 87.171f },
		{ "Assets/Game Objects/Elements/Endurium.fbx", 127.706f }, { "Assets/Game Objects/Elements/Mercury.fbx", 66.320f }
	};

	// the model file a template of the scene is a copy of, by its mesh ("" if none: in play mode a copy no longer knows its prefab)
	static string TemplateModelPath( GameObject template )
	{
		var filter = ( template != null ) ? template.GetComponentInChildren<MeshFilter>( true ) : null;

		return ( ( filter != null ) && ( filter.sharedMesh != null ) ) ? AssetDatabase.GetAssetPath( filter.sharedMesh ) : "";
	}

	// a mesh's bounding volume in its node's frame, and its size
	static float MeshVolume( MeshFilter filter, out Vector3 size )
	{
		size = ( ( filter != null ) && ( filter.sharedMesh != null ) ) ? Vector3.Scale( filter.sharedMesh.bounds.size, filter.transform.localScale ) : Vector3.zero;

		return size.x * size.y * size.z;
	}

	IEnumerator ScenarioRockModels()
	{
		var controller = SpaceflightController.m_instance;
		var grid = controller.m_disembarked.m_terrainGrid;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// ---- 1. the nine rock templates: each in its own material with the new maps (Rocks/Textures), light enough, the old rock's size
		var rocks = grid.m_terrainRocks.m_rockTemplates;
		var rocksTextured = 0;
		var rocksLight = 0;
		var rocksSized = 0;
		var rockDetails = new List<string>();
		var measured = new List<string>();

		foreach ( var template in rocks )
		{
			var model = TemplateModelPath( template );
			var name = System.IO.Path.GetFileNameWithoutExtension( model );
			var renderer = ( template != null ) ? template.GetComponentInChildren<MeshRenderer>( true ) : null;
			var filter = ( template != null ) ? template.GetComponentInChildren<MeshFilter>( true ) : null;
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;
			var albedo = ( material != null ) ? AssetDatabase.GetAssetPath( material.GetTexture( "_MainTex" ) ) : "";
			var triangles = TriangleCount( ( filter != null ) ? filter.sharedMesh : null );
			var volume = MeshVolume( filter, out var size );

			rocksTextured += ( albedo == "Assets/Game Objects/Rocks/Textures/" + name + " - Albedo.jpg" ) ? 1 : 0;
			rocksLight += ( ( triangles > 1000 ) && ( triangles < 4000 ) ) ? 1 : 0;
			rocksSized += ( c_oldPropVolumes.TryGetValue( model, out var oldVolume ) && ( oldVolume > 0.0f ) && ( Mathf.Abs( volume / oldVolume - 1.0f ) < 0.25f ) ) ? 1 : 0;
			rockDetails.Add( name + ": " + ( ( material != null ) ? material.name : "none" ) + " " + albedo.Replace( "Assets/Game Objects/", "" ) + ", " + triangles + " triangles, " + size.ToString( "F2" ) );
			measured.Add( "{ \"" + model + "\", " + volume.ToString( "F3", System.Globalization.CultureInfo.InvariantCulture ) + "f }" );
		}

		// ---- 2. the deposits: those made in a rock's shape take the rock's grey map under their element's colour; Endurium and Mercury have their own maps
		var elements = grid.m_terrainElements.m_elementTemplates;
		var depositsGrey = 0;
		var depositsRockShaped = 0;
		var ownShapes = 0;
		var depositDetails = new List<string>();

		for ( var i = 0; i < elements.Length; i++ )
		{
			var template = elements[ i ];
			var model = TemplateModelPath( template );
			var name = System.IO.Path.GetFileNameWithoutExtension( model );
			var renderer = ( template != null ) ? template.GetComponentInChildren<MeshRenderer>( true ) : null;
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;
			var albedo = ( material != null ) ? AssetDatabase.GetAssetPath( material.GetTexture( "_MainTex" ) ) : "";
			var filter = ( template != null ) ? template.GetComponentInChildren<MeshFilter>( true ) : null;
			var volume = MeshVolume( filter, out var size );

			if ( model.StartsWith( "Assets/Game Objects/Rocks/" ) )
			{
				// (one element's deposit is drawn in the rock's own material, and keeps the rock's new maps)
				depositsRockShaped++;
				depositsGrey += ( ( albedo == "Assets/Game Objects/Rocks/Textures/" + name + " - Grey.jpg" ) || ( ( material != null ) && ( material.name == name ) && ( albedo == "Assets/Game Objects/Rocks/Textures/" + name + " - Albedo.jpg" ) ) ) ? 1 : 0;
			}
			else
			{
				var emissive = ( material != null ) ? AssetDatabase.GetAssetPath( material.GetTexture( "SF_EmissiveMap" ) ) : "";
				var ownMaps = ( albedo == "Assets/Game Objects/Elements/Textures/" + name + " - Albedo.jpg" ) && ( ( name != "Endurium" ) || ( emissive == "Assets/Game Objects/Elements/Textures/Endurium - Emissive.jpg" ) );
				// (the mercury, a flat pool, keeps the old pool's widest side, 7.17, and is thinner; the crystals keep about the old volume)
				var sized = ( name == "Mercury" ) ? ( Mathf.Abs( Mathf.Max( size.x, Mathf.Max( size.y, size.z ) ) / 7.173f - 1.0f ) < 0.1f ) : ( c_oldPropVolumes.TryGetValue( model, out var oldVolume ) && ( oldVolume > 0.0f ) && ( volume / oldVolume > 0.5f ) && ( volume / oldVolume < 2.0f ) );

				ownShapes += ( ownMaps && sized ) ? 1 : 0;
				depositDetails.Add( name + " own maps " + ownMaps + ", sized " + sized + " " + size.ToString( "F2" ) );
				measured.Add( "{ \"" + model + "\", " + volume.ToString( "F3", System.Globalization.CultureInfo.InvariantCulture ) + "f }" );
			}

			depositDetails.Add( name + "/" + ( ( material != null ) ? material.name : "none" ) + " " + albedo.Replace( "Assets/Game Objects/", "" ) );
		}

		Log( "rockmodels: rocks: " + string.Join( " | ", rockDetails ) );
		Log( "rockmodels: deposits: " + string.Join( " | ", depositDetails ) );
		Log( "rockmodels: volumes: " + string.Join( ", ", measured ) );

		// ---- 3. on the ground of planet 92 (minerals 15): the placed rocks and deposits are in the new materials
		yield return LandInTheArthSystemAt( 92, Vector3.zero, done );
		yield return Frames( 5 );

		var placedRocks = grid.m_terrainRocks.GetComponentsInChildren<MeshRenderer>( false );
		var placedDeposits = grid.m_terrainElements.GetComponentsInChildren<MeshRenderer>( false );
		var rocksNew = System.Array.TrueForAll( placedRocks, r => ( r.sharedMaterial != null ) && AssetDatabase.GetAssetPath( r.sharedMaterial.GetTexture( "_MainTex" ) ).StartsWith( "Assets/Game Objects/Rocks/Textures/" ) );
		var depositsNew = System.Array.TrueForAll( placedDeposits, r => ( r.sharedMaterial != null ) && AssetDatabase.GetAssetPath( r.sharedMaterial.GetTexture( "_MainTex" ) ).Contains( "/Textures/" ) );

		// (with -Graphics, a picture of the vehicle among them)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "rockmodels-on-92.png" ) );
		}

		Log( "rockmodels: planet 92: " + placedRocks.Length + " rocks and " + placedDeposits.Length + " deposits on the ground, rocks new " + rocksNew + ", deposits new " + depositsNew );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "rockmodels: each of the nine rocks is in its own material with its new maps", ( rocks.Length == 9 ) && ( rocksTextured == 9 ), rocksTextured + "/" + rocks.Length );
		Check( "rockmodels: each rock has between 1,000 and 4,000 triangles", rocksLight == 9, rocksLight.ToString() );
		Check( "rockmodels: each rock is the old rock's size (its bounding volume within a quarter)", rocksSized == 9, rocksSized.ToString() );
		Check( "rockmodels: every deposit made in a rock's shape takes the rock's grey map under its element's colour (or the rock's own new maps, if it is drawn in the rock's material)", ( depositsRockShaped == 20 ) && ( depositsGrey == 20 ), depositsGrey + "/" + depositsRockShaped );
		Check( "rockmodels: Endurium and Mercury have their own maps (Endurium's glow too), at about the old size", ownShapes == 2, ownShapes.ToString() );
		Check( "rockmodels: on the ground the rocks and the deposits are in the new materials", done[ 0 ] && ( placedRocks.Length > 0 ) && ( placedDeposits.Length > 0 ) && rocksNew && depositsNew, done[ 0 ] + " " + placedRocks.Length + " " + placedDeposits.Length + " " + rocksNew + " " + depositsNew );
		Check( "rockmodels: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=rockmodels rocks=" + rocksTextured + "/" + rocksLight + "/" + rocksSized + " deposits=" + depositsGrey + "/" + depositsRockShaped + " own=" + ownShapes + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the special artifacts' models (Resources/Artifacts, DevTools/ShipModels/import_meshy_artifacts.py)

	IEnumerator ScenarioArtifactModels()
	{
		var controller = SpaceflightController.m_instance;
		var gameData = DataController.m_instance.m_gameData;
		var playerData = DataController.m_instance.m_playerData;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// ---- 1. every special artifact has its model, textured, light enough and one unit across; no curio has one
		var special = 0;
		var modelled = 0;
		var curiosWithModels = new List<string>();
		var details = new List<string>();

		foreach ( var artifact in gameData.m_artifactList )
		{
			var model = ArtifactModels.Get( artifact );

			if ( !artifact.IsSpecial() )
			{
				if ( model != null )
				{
					curiosWithModels.Add( artifact.m_name );
				}

				continue;
			}

			special++;

			var renderer = ( model != null ) ? model.GetComponentInChildren<MeshRenderer>( true ) : null;
			var filter = ( model != null ) ? model.GetComponentInChildren<MeshFilter>( true ) : null;
			var material = ( renderer != null ) ? renderer.sharedMaterial : null;
			var triangles = TriangleCount( ( filter != null ) ? filter.sharedMesh : null );
			var size = ( ( filter != null ) && ( filter.sharedMesh != null ) ) ? Vector3.Scale( filter.sharedMesh.bounds.size, filter.transform.lossyScale ) : Vector3.zero;
			var widest = Mathf.Max( size.x, Mathf.Max( size.y, size.z ) );
			var good = ( material != null ) && ( material.name == "Artifact " + artifact.m_name ) && ( material.GetTexture( "_MainTex" ) != null ) && ( triangles > 500 ) && ( triangles < 6000 ) && ( Mathf.Abs( widest - 1.0f ) < 0.1f );

			modelled += good ? 1 : 0;

			if ( !good )
			{
				details.Add( artifact.m_name + ": " + ( ( material != null ) ? material.name : "no model" ) + ", " + triangles + " triangles, " + widest.ToString( "F2" ) + " across" );
			}
		}

		Log( "artifactmodels: " + modelled + " of " + special + " special artifacts modelled" + ( ( details.Count > 0 ) ? " (" + string.Join( "; ", details ) + ")" : "" ) + ", curios with models: " + curiosWithModels.Count );

		// ---- 2. on Earth at 11N x 104W the Hypercube shows beside the ruin that holds it, hovering and turning
		yield return GoIntoOrbit( 0, 5 );

		playerData.m_general.m_selectedLatitude = -104.0f;
		playerData.m_general.m_selectedLongitude = 11.0f;

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );
		yield return DisembarkNow( done );

		var sitePosition = Tools.LatLongToWorldCoordinates( -104.0f, 11.0f );
		TerrainRuin siteRuin = null;

		foreach ( var ruin in controller.m_disembarked.m_terrainGrid.m_terrainRuins.GetComponentsInChildren<TerrainRuin>( false ) )
		{
			var delta = ruin.transform.position - sitePosition;

			if ( ( Mathf.Abs( delta.x ) < 0.5f ) && ( Mathf.Abs( delta.z ) < 0.5f ) )
			{
				siteRuin = ruin;
			}
		}

		var displays = ( siteRuin != null ) ? siteRuin.m_artifactDisplays.FindAll( display => display != null ) : new List<GameObject>();
		var display = ( displays.Count > 0 ) ? displays[ 0 ] : null;
		var shownBeside = ( display != null ) && ( display.name == "Artifact Hypercube" ) && ( display.GetComponent<ArtifactDisplay>() != null ) && ( display.GetComponentInChildren<MeshRenderer>() != null );
		var apart = ( display != null ) ? Vector3.Distance( new Vector3( display.transform.position.x, 0.0f, display.transform.position.z ), new Vector3( siteRuin.transform.position.x, 0.0f, siteRuin.transform.position.z ) ) : -1.0f;
		var positionBefore = ( display != null ) ? display.transform.position : Vector3.zero;
		var rotationBefore = ( display != null ) ? display.transform.rotation : Quaternion.identity;

		// (with -Graphics, a picture of the vehicle near the Hypercube)
		if ( ( siteRuin != null ) && ( display != null ) )
		{
			controller.m_terrainVehicle.transform.position = display.transform.position + ( siteRuin.transform.position - display.transform.position ).normalized * -12.0f;
		}

		yield return Frames( 30 );

		var moves = ( display != null ) && ( ( Vector3.Distance( positionBefore, display.transform.position ) > 0.01f ) || ( Quaternion.Angle( rotationBefore, display.transform.rotation ) > 1.0f ) );

		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "artifactmodels-hypercube.png" ) );
		}

		// ---- 3. beside the ruin, the cargo button takes the Hypercube, and it no longer shows
		if ( siteRuin != null )
		{
			controller.m_terrainVehicle.transform.position = siteRuin.transform.position + Vector3.forward * 5.0f;
		}

		yield return Frames( 2 );

		new TVCargoButton().Execute();

		yield return Frames( 3 );

		var taken = ArtifactsHeld( playerData.m_terrainVehicle.m_artifactStorage, gameData.FindArtifactId( "Hypercube" ) ) == 1;
		var goneAfter = ( siteRuin != null ) && ( siteRuin.m_artifactDisplays.FindAll( d => d != null ).Count == 0 ) && ( display == null );

		Log( "artifactmodels: Earth (in the vehicle " + done[ 0 ] + "): the ruin of 11N x 104W " + ( ( siteRuin != null ) ? "found" : "not found" ) + ", " + displays.Count + " artifacts shown beside it" + ( ( display != null ) ? " (" + display.name + ", " + apart.ToString( "F1" ) + " from its middle)" : "" ) + ", moving " + moves + "; taken " + taken + ", shown after " + !goneAfter );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "artifactmodels: each of the 15 special artifacts has its own textured model, between 500 and 6,000 triangles, one unit across", ( special == 15 ) && ( modelled == 15 ), modelled + "/" + special );
		Check( "artifactmodels: no curio has a model", curiosWithModels.Count == 0, string.Join( ", ", curiosWithModels ) );
		Check( "artifactmodels: the Hypercube shows beside the ruin that holds it, hovering and turning", done[ 0 ] && shownBeside && ( apart > 8.0f ) && ( apart < 30.0f ) && moves, done[ 0 ] + " " + shownBeside + " " + apart.ToString( "F1" ) + " " + moves );
		Check( "artifactmodels: once the terrain vehicle takes it, it no longer shows", taken && goneAfter, taken + " " + goneAfter );
		Check( "artifactmodels: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=artifactmodels modelled=" + modelled + "/" + special + " shown=" + shownBeside + " gone=" + goneAfter + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the Trade Depot's artifact window (ArtifactPreview, TradeDepotPanel.UpdateArtifactPreview)

	// the window of the depot, or null (read without naming its type, so that the scenario also runs on the code before the window)
	static Component GetArtifactPreview( TradeDepotPanel depot )
	{
		var field = depot.GetType().GetField( "m_artifactPreview", c_any );

		return ( field != null ) ? field.GetValue( depot ) as Component : null;
	}

	// what the depot's window shows: "" when it is hidden, else the names of its artifacts
	static string ArtifactPreviewShows( TradeDepotPanel depot )
	{
		var preview = GetArtifactPreview( depot );

		if ( ( preview == null ) || !( Call( preview, "IsShowing" ) is bool showing ) || !showing )
		{
			return "";
		}

		var gameData = DataController.m_instance.m_gameData;
		var names = new List<string>();

		foreach ( var id in (IList<int>) Call( preview, "GetShownIds" ) )
		{
			names.Add( gameData.m_artifactList[ id ].m_name );
		}

		return string.Join( ", ", names );
	}

	// selects the depot's item of this type and id on the list it shows (false if it is not on it)
	static bool SelectDepotItem( TradeDepotPanel depot, int type, int id )
	{
		var items = GetField( depot, "m_itemList" ) as IList;

		for ( var index = 0; ( items != null ) && ( index < items.Count ); index++ )
		{
			if ( ( (int) GetField( items[ index ], "m_type" ) == type ) && ( (int) GetField( items[ index ], "m_id" ) == id ) )
			{
				SetField( depot, "m_currentItemIndex", index );
				Call( depot, "UpdateScreen" );

				return true;
			}
		}

		return false;
	}

	IEnumerator ScenarioStarportArtifactView()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var depot = FindPanel<TradeDepotPanel>();
		var errorsBefore = s_errorCount;

		var whiningOrb = gameData.FindArtifactId( "Whining Orb" );
		var rodDevice = gameData.FindArtifactId( "Rod Device" );
		var redHerring = gameData.FindArtifactId( "Red Herring" );

		// the Rod Device and a curio in the hold (the Starport has the Whining Orb and the Flat Device of a new game)
		playerData.m_playerShip.m_artifactStorage.m_artifactList.Clear();
		playerData.m_playerShip.m_artifactStorage.Add( rodDevice );
		playerData.m_playerShip.m_artifactStorage.Add( redHerring );

		yield return OpenPanel( depot, "trade depot" );

		// ---- 1. Buy: the Whining Orb turns in the window; an element shows nothing
		Call( depot, "SwitchToBuyItemState", true );

		yield return Frames( 2 );

		var buyElement = ArtifactPreviewShows( depot );
		var foundOrb = SelectDepotItem( depot, 1, whiningOrb );

		yield return Frames( 2 );

		var buyOrb = ArtifactPreviewShows( depot );

		// it turns
		var preview = GetArtifactPreview( depot );
		var stage = ( preview != null ) ? GetField( preview, "m_stage" ) as Transform : null;
		var model = ( ( stage != null ) && ( stage.childCount > 0 ) ) ? stage.GetChild( stage.childCount - 1 ) : null;
		var turnBefore = ( model != null ) ? model.localRotation : Quaternion.identity;

		yield return new WaitForSecondsRealtime( 0.5f );

		var turned = ( model != null ) ? Quaternion.Angle( turnBefore, model.localRotation ) : 0.0f;

		// the window: in the item column's free room (right of the longest artifact name of the game, left of the Volume column, inside the list), and drawn
		// over the list and under the popups and their overlay
		var longestName = "";

		foreach ( var artifact in gameData.m_artifactList )
		{
			if ( depot.m_itemListText.GetPreferredValues( artifact.m_name ).x > depot.m_itemListText.GetPreferredValues( longestName ).x )
			{
				longestName = artifact.m_name;
			}
		}

		var placed = false;
		var drawnRight = false;
		var placement = "no window";

		if ( preview != null )
		{
			var corners = new Vector3[ 4 ];

			( (RectTransform) preview.transform ).GetWorldCorners( corners );

			var window = new Rect( corners[ 0 ].x, corners[ 0 ].y, corners[ 2 ].x - corners[ 0 ].x, corners[ 2 ].y - corners[ 0 ].y );

			depot.m_itemListText.rectTransform.GetWorldCorners( corners );

			// (the names start at the item text's left side; its scale turns the preferred width into world units)
			var namesRight = corners[ 0 ].x + depot.m_itemListText.GetPreferredValues( longestName ).x * depot.m_itemListText.rectTransform.lossyScale.x;

			depot.m_volumeListText.rectTransform.GetWorldCorners( corners );

			var volumeLeft = corners[ 0 ].x;

			depot.m_itemListMask.GetComponent<RectTransform>().GetWorldCorners( corners );

			placed = ( window.xMin > namesRight ) && ( window.xMax < volumeLeft ) && ( window.yMin > corners[ 0 ].y ) && ( window.yMax < corners[ 2 ].y ) && ( window.width > 0.0f );
			placement = "window x " + window.xMin.ToString( "F1" ) + " to " + window.xMax.ToString( "F1" ) + " (names to " + namesRight.ToString( "F1" ) + ", \"" + longestName + "\"; Volume from " + volumeLeft.ToString( "F1" ) + "), y " + window.yMin.ToString( "F1" ) + " to " + window.yMax.ToString( "F1" ) + " (list " + corners[ 0 ].y.ToString( "F1" ) + " to " + corners[ 2 ].y.ToString( "F1" ) + ")";

			// every popup on the trade screen comes after the window, and the list after none of them
			drawnRight = true;

			foreach ( var popup in new[] { depot.m_overlayPanel, depot.m_amountGameObject, depot.m_analyzePanel, depot.m_confirmAnalyzePanel, depot.m_errorPanel } )
			{
				if ( ( popup != null ) && ( popup.transform.parent == preview.transform.parent ) && ( popup.transform.GetSiblingIndex() < preview.transform.GetSiblingIndex() ) )
				{
					drawnRight = false;
				}
			}

			var listChild = depot.m_itemListMask.transform;

			for ( var depth = 0; ( depth < 32 ) && ( listChild != null ) && ( listChild.parent != preview.transform.parent ); depth++ )
			{
				listChild = listChild.parent;
			}

			drawnRight = drawnRight && ( listChild != null ) && ( listChild.GetSiblingIndex() < preview.transform.GetSiblingIndex() );
		}

		// (with -Graphics, a picture of the Buy list with the Whining Orb turning)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "starport-artifactview.png" ) );
		}

		// ---- 2. Sell: the Rod Device turns; the curio shows nothing
		Call( depot, "SwitchToSellItemState", true );

		SelectDepotItem( depot, 1, rodDevice );

		yield return Frames( 2 );

		var sellRod = ArtifactPreviewShows( depot );

		SelectDepotItem( depot, 1, redHerring );

		yield return Frames( 2 );

		var sellCurio = ArtifactPreviewShows( depot );

		// ---- 3. Analyze: the Rod Device turns
		Call( depot, "SwitchToAnalyzeItemState", true );

		SelectDepotItem( depot, 1, rodDevice );

		yield return Frames( 2 );

		var analyzeRod = ArtifactPreviewShows( depot );

		// ---- 4. the menu bar and a closed panel show nothing, and the window's camera stops drawing
		Call( depot, "SwitchToMenuBarState" );

		yield return Frames( 2 );

		var menuBar = ArtifactPreviewShows( depot );

		yield return ClosePanel( depot, "trade depot" );
		yield return Frames( 2 );

		var closed = ArtifactPreviewShows( depot );
		var previewCamera = ( preview != null ) ? GetField( preview, "m_camera" ) as Camera : null;
		var cameraOff = ( previewCamera != null ) && !previewCamera.enabled;

		var errorsDuring = s_errorCount - errorsBefore;

		Log( "starport-artifactview: Buy: an element \"" + buyElement + "\", the Whining Orb (" + ( foundOrb ? "listed" : "not listed" ) + ") \"" + buyOrb + "\", turned " + turned.ToString( "F1" ) + " degrees in 0.5 s; Sell: the Rod Device \"" + sellRod + "\", the Red Herring \"" + sellCurio + "\"; Analyze: the Rod Device \"" + analyzeRod + "\"; menu bar \"" + menuBar + "\", closed \"" + closed + "\", its camera off " + cameraOff + "; " + placement + ", drawn over the list and under the popups " + drawnRight );

		Check( "starport-artifactview: on the Buy list the selected Whining Orb turns in the window, and an element shows nothing", foundOrb && ( buyOrb == "Whining Orb" ) && ( buyElement == "" ) && ( turned > 5.0f ), buyOrb + " / " + buyElement + " / " + turned.ToString( "F1" ) );
		Check( "starport-artifactview: on the Sell list the Rod Device shows and the curio does not", ( sellRod == "Rod Device" ) && ( sellCurio == "" ), sellRod + " / " + sellCurio );
		Check( "starport-artifactview: on the Analyze list the Rod Device shows", analyzeRod == "Rod Device", analyzeRod );
		Check( "starport-artifactview: the window is in the item column's free room, right of the longest artifact name and left of the Volume column, inside the list", placed, placement );
		Check( "starport-artifactview: the window is drawn over the list and under the popups and their overlay", drawnRight, drawnRight.ToString() );
		Check( "starport-artifactview: with the menu bar up and the panel closed the window shows nothing and its camera is off", ( menuBar == "" ) && ( closed == "" ) && cameraOff, menuBar + " / " + closed + " / " + cameraOff );
		Check( "starport-artifactview: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=starport-artifactview checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the cargo display's artifact window (TerrainVehicleCargoDisplay, TVCargoButton.GetMarkedArtifactId)

	// what the cargo display's artifact window shows: "" when it is hidden, else the names of its artifacts (read without naming its type, so that the
	// scenario also runs on the code before the window)
	static string CargoArtifactWindowShows( TerrainVehicleCargoDisplay cargoDisplay )
	{
		var field = ( cargoDisplay != null ) ? cargoDisplay.GetType().GetField( "m_artifactPreview", c_any ) : null;
		var preview = ( field != null ) ? field.GetValue( cargoDisplay ) as Component : null;

		if ( ( preview == null ) || !( Call( preview, "IsShowing" ) is bool showing ) || !showing )
		{
			return "";
		}

		var gameData = DataController.m_instance.m_gameData;
		var names = new List<string>();

		foreach ( var id in (IList<int>) Call( preview, "GetShownIds" ) )
		{
			names.Add( gameData.m_artifactList[ id ].m_name );
		}

		return string.Join( ", ", names );
	}

	IEnumerator ScenarioArtifactCargo()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var controller = SpaceflightController.m_instance;
		var displayController = controller.m_displayController;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// ---- out on planet 90 with 3 cubic meters of an element, a Hypercube and a curio, nothing within reach
		yield return EnterOrbit( 90 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );
		yield return DisembarkNow( done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=artifactcargo abort: never got into the terrain vehicle (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		var terrainVehicle = controller.m_terrainVehicle;

		foreach ( var deposit in controller.m_disembarked.m_terrainGrid.m_terrainElements.transform.GetComponentsInChildren<TerrainElement>( true ) )
		{
			if ( Vector3.Distance( deposit.transform.position, terrainVehicle.transform.position ) < 50.0f )
			{
				deposit.transform.position += Vector3.right * 1000.0f;
			}
		}

		var elementId = gameData.m_planetList[ 90 ].m_elementIdA;
		var hypercubeId = gameData.FindArtifactId( "Hypercube" );
		var redHerringId = gameData.FindArtifactId( "Red Herring" );

		playerData.m_terrainVehicle.AddElement( elementId, 30 );
		playerData.m_terrainVehicle.AddArtifact( hypercubeId );
		playerData.m_terrainVehicle.AddArtifact( redHerringId );

		var cargoDisplay = displayController.m_terrainVehicleCargoDisplay;
		var cargoListSet = CargoListButtonSet();

		// ---- 1. the cargo list opens with the element marked: nothing turns
		new TVCargoButton().Execute();

		yield return Frames( 3 );

		var element = CargoArtifactWindowShows( cargoDisplay );

		// ---- 2. Next: the Hypercube turns under the list
		PressButton( (ButtonController.ButtonSet) cargoListSet, 0 );

		yield return Frames( 3 );

		var hypercube = CargoArtifactWindowShows( cargoDisplay );

		// the window: under the list's text and inside the display, and turning
		var field = cargoDisplay.GetType().GetField( "m_artifactPreview", c_any );
		var preview = ( field != null ) ? field.GetValue( cargoDisplay ) as Component : null;
		var placed = false;
		var placement = "no window";

		if ( preview != null )
		{
			var corners = new Vector3[ 4 ];

			( (RectTransform) preview.transform ).GetWorldCorners( corners );

			var windowLow = corners[ 0 ];
			var windowHigh = corners[ 2 ];

			cargoDisplay.m_labelsText.ForceMeshUpdate();

			var textBottom = cargoDisplay.m_labelsText.rectTransform.TransformPoint( new Vector3( 0.0f, cargoDisplay.m_labelsText.textBounds.min.y, 0.0f ) ).y;

			( (RectTransform) cargoDisplay.m_labelsText.rectTransform.parent ).GetWorldCorners( corners );

			placed = ( windowHigh.y < textBottom ) && ( windowLow.y > corners[ 0 ].y ) && ( windowLow.x > corners[ 0 ].x ) && ( windowHigh.x < corners[ 2 ].x );
			placement = "window y " + windowLow.y.ToString( "F2" ) + " to " + windowHigh.y.ToString( "F2" ) + " (text down to " + textBottom.ToString( "F2" ) + ", display " + corners[ 0 ].y.ToString( "F2" ) + " to " + corners[ 2 ].y.ToString( "F2" ) + "), x " + windowLow.x.ToString( "F2" ) + " to " + windowHigh.x.ToString( "F2" ) + " (display " + corners[ 0 ].x.ToString( "F2" ) + " to " + corners[ 2 ].x.ToString( "F2" ) + ")";
		}

		var stage = ( preview != null ) ? GetField( preview, "m_stage" ) as Transform : null;
		var model = ( ( stage != null ) && ( stage.childCount > 0 ) ) ? stage.GetChild( stage.childCount - 1 ) : null;
		var turnBefore = ( model != null ) ? model.localRotation : Quaternion.identity;

		yield return new WaitForSecondsRealtime( 0.5f );

		var turned = ( model != null ) ? Quaternion.Angle( turnBefore, model.localRotation ) : 0.0f;

		// an update of the display with nothing changed takes no memory with the Hypercube showing either
		var updateBytes = Allocated( () => cargoDisplay.Update(), c_meterCalls ) / c_meterCalls;

		// (with -Graphics, a picture of the cargo display with the Hypercube turning)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			RenderScreenPicture( System.IO.Path.Combine( System.IO.Path.GetTempPath(), "starflight-probe", "artifactcargo.png" ) );
		}

		// ---- 3. Next: the curio, nothing turns
		PressButton( (ButtonController.ButtonSet) cargoListSet, 0 );

		yield return Frames( 3 );

		var curio = CargoArtifactWindowShows( cargoDisplay );

		// ---- 4. Next again (round to the element and on to the Hypercube), then Back: the list is closed, nothing shows, and the window's camera is off
		PressButton( (ButtonController.ButtonSet) cargoListSet, 0 );

		yield return Frames( 2 );

		PressButton( (ButtonController.ButtonSet) cargoListSet, 0 );

		yield return Frames( 2 );

		var hypercubeAgain = CargoArtifactWindowShows( cargoDisplay );

		PressButton( (ButtonController.ButtonSet) cargoListSet, 2 );

		yield return Frames( 3 );

		var afterBack = CargoArtifactWindowShows( cargoDisplay );
		var previewCamera = ( preview != null ) ? GetField( preview, "m_camera" ) as Camera : null;
		var cameraOff = ( previewCamera != null ) && !previewCamera.enabled;

		var errorsDuring = s_errorCount - errorsBefore;

		Log( "artifactcargo: marked the element \"" + element + "\", the Hypercube \"" + hypercube + "\" (turned " + turned.ToString( "F1" ) + " degrees in 0.5 s, an update with nothing changed " + updateBytes + " bytes), the Red Herring \"" + curio + "\", the Hypercube again \"" + hypercubeAgain + "\"; after Back \"" + afterBack + "\", its camera off " + cameraOff + "; " + placement );

		Check( "artifactcargo: with the element marked on the cargo list nothing turns, with the Hypercube marked it turns in the cargo display's window", ( element == "" ) && ( hypercube == "Hypercube" ) && ( turned > 5.0f ), element + " / " + hypercube + " / " + turned.ToString( "F1" ) );
		Check( "artifactcargo: a marked curio shows nothing, and the Hypercube shows again when it is marked again", ( curio == "" ) && ( hypercubeAgain == "Hypercube" ), curio + " / " + hypercubeAgain );
		Check( "artifactcargo: the window is under the list's text and inside the display", placed, placement );
		Check( "artifactcargo: an update of the cargo display with nothing changed takes no memory with the window showing", updateBytes == 0, updateBytes + " bytes per call" );
		Check( "artifactcargo: with the list closed nothing shows and the window's camera is off", ( afterBack == "" ) && cameraOff, afterBack + " / " + cameraOff );
		Check( "artifactcargo: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=artifactcargo checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// the columns of the table the Captain's Cargo button renders in the text window, as the player sees them (empty strings while it is hidden)
	static string[] ShipCargoTableColumns()
	{
		var columns = new List<string>();
		var table = SpaceflightController.m_instance.m_messages.GetComponentInChildren<UnityEngine.UI.HorizontalLayoutGroup>();

		if ( table != null )
		{
			foreach ( Transform column in table.transform )
			{
				var text = column.GetComponent( "TextMeshProUGUI" );

				columns.Add( ( text == null ) ? "" : ( text.GetType().GetProperty( "text" ).GetValue( text ) as string ?? "" ) );
			}
		}

		return columns.ToArray();
	}

	// the rows of the Cargo table below its headings, each as "item|volume|value" with the item's indent trimmed
	static List<string> ShipCargoTableRows( string[] columns )
	{
		var rows = new List<string>();

		if ( columns.Length < 3 )
		{
			return rows;
		}

		var items = columns[ 0 ].Split( '\n' );
		var volumes = columns[ 1 ].Split( '\n' );
		var values = columns[ 2 ].Split( '\n' );

		for ( var i = 1; i < items.Length; i++ )
		{
			if ( items[ i ].Trim().Length == 0 )
			{
				continue;
			}

			// (without the marked item's colour and marker, since the list has one: roadmap 8.33)
			var item = System.Text.RegularExpressions.Regex.Replace( items[ i ], "<[^>]*>", "" ).Trim();

			if ( item.StartsWith( "> " ) )
			{
				item = item.Substring( 2 ).Trim();
			}

			rows.Add( item + "|" + ( ( i < volumes.Length ) ? volumes[ i ] : "" ) + "|" + ( ( i < values.Length ) ? values[ i ] : "" ) );
		}

		return rows;
	}

	IEnumerator ScenarioShipCargo()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var ship = playerData.m_playerShip;

		EnsureCrew();

		yield return Frames( 5 );

		// ---- 1. an empty hold: the original says STARSHIP HOLD IS EMPTY. and shows no list (CAPTAIN (/ITEMS) WEEF2)
		ship.m_elementStorage.Reset();
		ship.m_artifactStorage.Reset();
		ship.GetSpecimenStorage().m_specimenList.Clear();

		PressButtonLabelled( ButtonController.ButtonSet.CommandB, "Cargo" );

		yield return Frames( 5 );

		var emptyMessages = MessageList();
		var emptyColumns = ShipCargoTableColumns();
		var emptyTable = string.Join( "#", emptyColumns ).Replace( '\n', '/' );

		Log( "shipcargo: with the hold empty the messages say '" + emptyMessages + "', the table shows '" + emptyTable + "'" );

		Check( "shipcargo: an empty hold says Starship hold is empty. and shows no list", emptyMessages.Contains( "Starship hold is empty." ) && !emptyTable.Contains( "ITEM" ), emptyMessages + " | " + emptyTable );

		// ---- 2. a hold with every kind of item: two elements, two artifacts (one of a kind analysed, one not) and two specimens, each pair put in in that order
		var enduriumId = gameData.m_misc.m_enduriumElementId;
		var molybdenumId = Array.FindIndex( gameData.m_elementList, element => element.m_name == "Molybdenum" );
		var knownId = Array.FindIndex( gameData.m_artifactList, artifact => artifact.m_name == "Bladed Toy" );
		var unknownId = Array.FindIndex( gameData.m_artifactList, artifact => artifact.m_name == "Blue Bauble" );

		if ( ( enduriumId < 0 ) || ( molybdenumId < 0 ) || ( knownId < 0 ) || ( unknownId < 0 ) )
		{
			Finish( "scenario=shipcargo abort: missing game data (" + enduriumId + " " + molybdenumId + " " + knownId + " " + unknownId + ")", 2 );
			yield break;
		}

		// the Bladed Toy's kind analysed, the Blue Bauble's not
		if ( !playerData.m_knownArtifacts.IsKnown( knownId ) )
		{
			playerData.m_knownArtifacts.Add( knownId );
		}

		for ( var attempt = 0; ( attempt < 10 ) && playerData.m_knownArtifacts.IsKnown( unknownId ); attempt++ )
		{
			playerData.m_knownArtifacts.Remove( unknownId );
		}

		ship.m_elementStorage.Add( enduriumId, 200 );
		ship.m_elementStorage.Add( molybdenumId, 96 );

		ship.m_artifactStorage.Add( knownId );
		ship.m_artifactStorage.Add( unknownId );

		var firstSpecimen = new PD_Specimen { m_planetId = 90, m_speciesIndex = 0, m_name = "Probe Specimen One", m_volume = 20, m_value = 400 };
		var secondSpecimen = new PD_Specimen { m_planetId = 90, m_speciesIndex = 1, m_name = "Probe Specimen Two", m_volume = 15, m_value = 300 };

		ship.GetSpecimenStorage().Add( firstSpecimen );
		ship.GetSpecimenStorage().Add( secondSpecimen );

		PressButtonLabelled( ButtonController.ButtonSet.CommandB, "Cargo" );

		yield return Frames( 5 );

		var rows = ShipCargoTableRows( ShipCargoTableColumns() );
		var shown = string.Join( " / ", rows );

		// with -Graphics, the whole screen with the list on it (Logs/screen-pictures/shipcargo/, or the folder given with -probePictures)
		if ( SystemInfo.graphicsDeviceType != UnityEngine.Rendering.GraphicsDeviceType.Null )
		{
			var folder = GetArg( "-probePictures", System.IO.Path.Combine( System.IO.Directory.GetCurrentDirectory(), "Logs", "screen-pictures", "shipcargo" ) );

			System.IO.Directory.CreateDirectory( folder );

			RenderScreenPicture( System.IO.Path.Combine( folder, "cargo_list.png" ) );

			Log( "shipcargo: picture written to " + folder );
		}

		Log( "shipcargo: the Cargo list shows " + shown );

		// the headings, in the order of the kinds
		var items = rows.ConvertAll( row => row.Split( '|' )[ 0 ] );
		var elementsAt = items.IndexOf( "ELEMENTS" );
		var artifactsAt = items.IndexOf( "ARTIFACTS" );
		var specimensAt = items.IndexOf( "SPECIMENS" );

		Check( "shipcargo: the list has a heading for each kind of item in the hold: elements, artifacts and specimens", ( elementsAt >= 0 ) && ( artifactsAt > elementsAt ) && ( specimensAt > artifactsAt ), elementsAt + " " + artifactsAt + " " + specimensAt + " | " + shown );

		// each kind's items under its heading, the one put in last first, each with its volume and value: an element at what the Trade Depot pays for a cubic
		// meter of it, an artifact of an analysed kind at what the Trade Depot pays for it and one of a kind not analysed at ???, a specimen at its sale value
		var molybdenum = gameData.m_elementList[ molybdenumId ];
		var endurium = gameData.m_elementList[ enduriumId ];
		var known = gameData.m_artifactList[ knownId ];
		var unknown = gameData.m_artifactList[ unknownId ];

		var expected = new List<string>
		{
			"ELEMENTS||",
			molybdenum.m_name + "|9.6|" + molybdenum.GetActualValue(),
			endurium.m_name + "|20.0|" + endurium.GetActualValue(),
			"ARTIFACTS||",
			unknown.m_name + "|" + Tools.VolumeToText( unknown.m_volume ) + "|???",
			known.m_name + "|" + Tools.VolumeToText( known.m_volume ) + "|" + known.m_actualValue,
			"SPECIMENS||",
			"Probe Specimen Two|1.5|" + secondSpecimen.GetSaleValue(),
			"Probe Specimen One|2.0|" + firstSpecimen.GetSaleValue()
		};

		var expectedText = string.Join( " / ", expected );

		Check( "shipcargo: every item in the hold is listed under its kind, the one put in last first, with its volume and value (??? for an artifact not analysed)", shown == expectedText, "shown: " + shown + " | expected: " + expectedText );

		// ---- 3. once the Blue Bauble's kind is analysed, the list shows its value
		playerData.m_knownArtifacts.Add( unknownId );

		PressButtonLabelled( ButtonController.ButtonSet.CommandB, "Cargo" );

		yield return Frames( 5 );

		var analysedRows = ShipCargoTableRows( ShipCargoTableColumns() );
		var analysedRow = analysedRows.Find( row => row.StartsWith( unknown.m_name + "|" ) ) ?? "";

		Log( "shipcargo: after the Blue Bauble's kind is analysed its row is '" + analysedRow + "'" );

		Check( "shipcargo: an artifact whose kind has been analysed shows its value", analysedRow == unknown.m_name + "|" + Tools.VolumeToText( unknown.m_volume ) + "|" + unknown.m_actualValue, analysedRow );

		Finish( "scenario=shipcargo rows=" + rows.Count + " checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the shields' recharge as the original's (since 2026-10-18)

	// the shield points the ship gains in this many seconds of game time, from none, with the shields down: the alien ships are put far away, out of their lasers'
	// reach, but hostile aliens that have opened fire launch missiles at any range (COMBAT-OV rules 1 and 2), and a missile that lands meanwhile hits the armor of
	// a ship with its shields down, not the shield points
	IEnumerator ShieldGain( float seconds, int[] gained )
	{
		var playerData = DataController.m_instance.m_playerData;
		var encounter = SpaceflightController.m_instance.m_encounter;

		if ( playerData.m_general.m_location == PD_General.Location.Encounter )
		{
			foreach ( var alienShip in encounter.m_pdEncounter.GetAlienShipList() )
			{
				if ( alienShip.m_addedToEncounter )
				{
					alienShip.m_coordinates = new Vector3( 2000.0f, 0.0f, 2000.0f );
				}
			}
		}

		playerData.m_playerShip.DropShields();
		playerData.m_playerShip.m_shieldPoints = 0;

		for ( var end = Time.time + seconds; Time.time < end; )
		{
			yield return null;
		}

		gained[ 0 ] = playerData.m_playerShip.m_shieldPoints;
	}

	// the shields regain their charge as the original's: 20 points on each of the ship's turns in an encounter (COMBAT-OV COMBAT, WEF20: each pass of the main loop
	// is one icon's turn, the ship's every (ships + 1) passes of Encounter.c_passSeconds), none outside an encounter (the code before gave 1% of the full charge every
	// 5 s anywhere), and the whole charge when the encounter ends (HYPER-OV ENCCLEANUP, CHARGE-D); class 2 shielding, 1000 points
	IEnumerator ScenarioShieldTurns()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var ship = playerData.m_playerShip;
		var general = playerData.m_general;
		var outside = new int[ 1 ];
		var withOne = new int[ 1 ];
		var withThree = new int[ 1 ];

		EnsureCrew();

		ship.m_shieldingClass = 2;
		ship.m_armorPoints = 100000;
		ship.RestoreSystems();

		var full = ship.GetMaximumShieldPoints();
		var encounterRange = controller.m_encounterRange;

		controller.m_encounterRange = 0.0f;

		// ---- 1. hyperspace, in a quiet corner, no encounter: six seconds
		general.m_lastHyperspaceCoordinates = Tools.GameToWorldCoordinates( new Vector3( 6.0f, 0.0f, 6.0f ) );

		controller.SwitchLocation( PD_General.Location.Hyperspace );

		yield return Frames( 10 );
		yield return ShieldGain( 6.0f, outside );

		// ---- 2. Spemin group 135 with one ship in it, then three: four seconds each, in the Combat menu as in a fight (out of it the encounter can end by itself
		// once the aliens move off over 22 cells, the original's ?UNNEST)
		EnterEncounter( 135 );

		yield return Frames( 3 );

		controller.m_buttonController.ChangeButtonSet( ButtonController.ButtonSet.Combat );

		KeepAlienShips( 1 );

		var shipsOne = AlienShipsPresent();

		yield return ShieldGain( 4.0f, withOne );

		KeepAlienShips( 3 );

		var shipsThree = AlienShipsPresent();

		yield return ShieldGain( 4.0f, withThree );

		// ---- 3. the encounter ends: the shields are refilled
		ship.m_shieldPoints = 100;

		var leave = typeof( Encounter ).GetMethod( "LeaveEncounter", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.Public );

		leave.Invoke( controller.m_encounter, null );

		yield return Frames( 3 );

		var afterLeaving = ship.m_shieldPoints;
		var leftTo = general.m_location;

		controller.m_encounterRange = encounterRange;

		// the gains a turn every (ships + 1) passes of 0.25 s would give, and how many turns the four seconds hold
		// (20 points a turn, the original's WEF20: a number here, since the code before has no constant for it)
		var expectOne = Mathf.FloorToInt( 4.0f / ( ( shipsOne + 1 ) * Encounter.c_passSeconds ) ) * 20;
		var expectThree = Mathf.FloorToInt( 4.0f / ( ( shipsThree + 1 ) * Encounter.c_passSeconds ) ) * 20;

		Log( "shieldturns: class 2 shielding (" + full + "): 6 s in hyperspace +" + outside[ 0 ] + "; 4 s in an encounter with " + shipsOne + " ship +" + withOne[ 0 ] + " (turns would give " + expectOne + "), with " + shipsThree + " ships +" + withThree[ 0 ] + " (" + expectThree + "); leaving the encounter (to " + leftTo + "): 100 -> " + afterLeaving );

		Check( "shieldturns: the encounter has one alien ship, then three, and the shielding holds 1000 (control)", ( shipsOne == 1 ) && ( shipsThree == 3 ) && ( full == 1000 ), shipsOne + " / " + shipsThree + " / " + full );
		Check( "shieldturns: outside an encounter the shields regain nothing (the code before gave 1% of the full charge every 5 s)", outside[ 0 ] == 0, "+" + outside[ 0 ] + " in 6 s" );
		Check( "shieldturns: with one alien ship the shields regain 20 points on each of the ship's turns, every 2 passes (160 in 4 s, one turn either way)", Mathf.Abs( withOne[ 0 ] - expectOne ) <= 20, "+" + withOne[ 0 ] + " of " + expectOne );
		Check( "shieldturns: with three alien ships the ship's turn comes every 4 passes (80 in 4 s, one turn either way)", Mathf.Abs( withThree[ 0 ] - expectThree ) <= 20, "+" + withThree[ 0 ] + " of " + expectThree );
		Check( "shieldturns: the encounter's end refills the shields (HYPER-OV ENCCLEANUP, CHARGE-D)", afterLeaving == full, "100 -> " + afterLeaving );

		Finish( "scenario=shieldturns checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- a star's state, the science officer's call (since 2026-10-18)

	// how many of this many star system scans give the star's stability as "Not certain", with the science officer at this skill
	static int UncertainStarScans( int skill, int scans )
	{
		var playerData = DataController.m_instance.m_playerData;
		var scienceOfficer = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.ScienceOfficer );
		var uncertain = 0;

		scienceOfficer.m_science = skill;

		for ( var i = 0; i < scans; i++ )
		{
			SpaceflightController.m_instance.m_messages.Clear();

			new SensorsButton().Execute();

			if ( MessageList().Contains( "Stability: <color=white>Not certain" ) )
			{
				uncertain++;
			}
		}

		return uncertain;
	}

	// the star system scan gives the star's stability only when the science officer can tell, as the original's analysis of a star (ANALYZE-OV WF31E: " STATE: "
	// then ?.CERTAIN, certain when the skill beats RRND 0 to 200; the creature file that would make it certain is never loaded in space): a science officer of no
	// skill never can (the code before always gave it), one of 250 always can, one of 100 half the time
	IEnumerator ScenarioStarState()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var starSystem = controller.m_starSystem;

		EnsureCrew();

		controller.m_encounterRange = 0.0f;

		// the star system of Arth, after Maneuver from the Starport (Sensors scans a star system only there)
		controller.SwitchLocation( PD_General.Location.JustLaunched );

		for ( var end = Time.realtimeSinceStartup + 60.0f; ( Time.realtimeSinceStartup < end ) && starSystem.GeneratingPlanets(); )
		{
			yield return null;
		}

		yield return Frames( 10 );

		PressButton( ButtonController.ButtonSet.NavigationA, 0 );

		yield return Frames( 10 );

		if ( GetField( controller.m_buttonController, "m_currentButton" ) is ManeuverButton )
		{
			controller.m_buttonController.DeactivateButton();
		}

		yield return Frames( 3 );

		var inStarSystem = playerData.m_general.m_location == PD_General.Location.StarSystem;
		var scienceOfficer = playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.ScienceOfficer );
		var skillBefore = scienceOfficer.m_science;

		controller.m_messages.Clear();
		new SensorsButton().Execute();

		var sample = MessageList();
		var noSkill = UncertainStarScans( 0, 10 );
		var fullSkill = UncertainStarScans( 250, 10 );
		var halfSkill = UncertainStarScans( 100, 40 );

		scienceOfficer.m_science = skillBefore;

		Log( "starstate: in the star system " + inStarSystem + "; a scan: '" + sample.Replace( "\n", " / " ) + "'; uncertain: skill 0 " + noSkill + " of 10, skill 250 " + fullSkill + " of 10, skill 100 " + halfSkill + " of 40" );

		Check( "starstate: the star system scan gives the star's stability line (control)", inStarSystem && sample.Contains( "Stability:" ), sample.Replace( "\n", " / " ) );
		Check( "starstate: a science officer of no skill cannot tell the star's state (the code before always gave it)", noSkill == 10, noSkill + " of 10 not certain" );
		Check( "starstate: a science officer of skill 250 always can", fullSkill == 0, fullSkill + " of 10 not certain" );
		Check( "starstate: one of skill 100 can about half the time (skill / 200)", ( halfSkill >= 8 ) && ( halfSkill <= 32 ), halfSkill + " of 40 not certain" );

		Finish( "scenario=starstate checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- damaged equipment malfunctions (since 2026-10-18)

	// whether a system has broken down, read by reflection so that the scenario also compiles on the code from before the rule (where nothing ever breaks down)
	static bool ProbeIsInoperative( PD_PlayerShip ship, PD_PlayerShip.ShipSystem system )
	{
		var method = typeof( PD_PlayerShip ).GetMethod( "IsInoperative", c_any );

		return ( method != null ) && (bool) method.Invoke( ship, new object[] { system } );
	}

	static void ProbeSetInoperative( PD_PlayerShip ship, PD_PlayerShip.ShipSystem system, bool inoperative )
	{
		var method = typeof( PD_PlayerShip ).GetMethod( "SetInoperative", c_any );

		if ( method != null )
		{
			method.Invoke( ship, new object[] { system, inoperative } );
		}
	}

	// repairs exactly one point of a system, as the engineer's repairs do once a point's work is done
	static void RepairOnePoint( PD_PlayerShip ship, PD_PlayerShip.ShipSystem system )
	{
		ship.m_repairItem = (int) system + 1;
		ship.m_repairsAreUnderWay = true;
		ship.m_repairProgress = 1.0f;

		Call( ship, "UpdateSystemRepairs", 0.0f );
	}

	// the original's equipment check (MISC-OV (?.EQ through OV?.EQUIP-OK): a damaged system malfunctions when it is used with a chance of its damage in percent, and
	// then stays inoperative until it is repaired; the sensors, the comm, the engines, the shields and each weapon are checked before they are used, engines shot
	// down to nothing break down at once, a repair that makes a system whole makes it work, and past 73 each repaired point has a chance of 1 in 5 to (REPAIR-OV).
	// The code before had no malfunctions: a damaged system always worked, and the sensors refused only below a quarter of their health
	IEnumerator ScenarioMalfunctions()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var ship = playerData.m_playerShip;
		var sensors = PD_PlayerShip.ShipSystem.Sensors;
		var engines = PD_PlayerShip.ShipSystem.Engines;

		EnsureCrew();

		controller.m_encounterRange = 0.0f;

		EnterStarSystem( DataController.m_instance.m_gameData.m_misc.m_arthStarId );

		for ( var end = Time.realtimeSinceStartup + 60.0f; ( Time.realtimeSinceStartup < end ) && controller.m_starSystem.GeneratingPlanets(); )
		{
			yield return null;
		}

		yield return Frames( 10 );

		// a ship with shields, missiles and lasers, all whole, and fuel
		ship.m_shieldingClass = Mathf.Max( 1, ship.m_shieldingClass );
		ship.m_missileLauncherClass = Mathf.Max( 1, ship.m_missileLauncherClass );
		ship.m_laserCannonClass = Mathf.Max( 1, ship.m_laserCannonClass );
		ship.RestoreSystems();
		ship.m_shieldsAreUp = false;
		ship.m_weaponsAreArmed = false;

		if ( ship.m_elementStorage.Find( 5 ) == null )
		{
			ship.AddElement( 5, 50 );
		}

		// ---- 1. whole systems never malfunction (control)
		var wholeFailures = 0;

		for ( var i = 0; i < 20; i++ )
		{
			if ( !PressAndRead( new SensorsButton() ).Contains( "Star System Scan" ) )
			{
				wholeFailures++;
			}

			PressAndRead( new RaiseShieldsButton() );

			if ( !ship.m_shieldsAreUp )
			{
				wholeFailures++;
			}

			ship.DropShields();

			if ( PressAndRead( new ArmWeaponButton() ).Contains( "MALFUNCTION" ) || !ship.m_weaponsAreArmed )
			{
				wholeFailures++;
			}

			ship.m_weaponsAreArmed = false;
		}

		// ---- 2. sensors at 0 always malfunction, and then say they are inoperative even once they are better (no roll)
		ship.SetSystemHealth( sensors, 0 );

		var sensorsAtZero = PressAndRead( new SensorsButton() );
		var sensorsBrokeDown = ProbeIsInoperative( ship, sensors );

		ship.SetSystemHealth( sensors, 90 );

		var sensorsInoperative = PressAndRead( new SensorsButton() );

		// ---- 3. at half health they malfunction about half the time
		var halfMalfunctions = 0;

		ship.SetSystemHealth( sensors, 50 );

		for ( var i = 0; i < 100; i++ )
		{
			ProbeSetInoperative( ship, sensors, false );

			if ( PressAndRead( new SensorsButton() ).Contains( "Sensors: MALFUNCTION" ) )
			{
				halfMalfunctions++;
			}
		}

		ProbeSetInoperative( ship, sensors, false );
		ship.SetSystemHealth( sensors, 100 );

		// ---- 4. engines at 0: Maneuver malfunctions and then is refused
		ship.SetSystemHealth( engines, 0 );

		var maneuverFirst = new ManeuverButton();
		controller.m_messages.Clear();
		var maneuverFirstStarted = maneuverFirst.Execute();
		var maneuverFirstText = MessageList();

		var maneuverSecond = new ManeuverButton();
		controller.m_messages.Clear();
		var maneuverSecondStarted = maneuverSecond.Execute();
		var maneuverSecondText = MessageList();

		playerData.m_general.m_currentSpeed = 0.0f;
		controller.m_playerShip.TurnOffEngines();

		// ---- 5. engines shot down to nothing break down at once
		ship.SetSystemHealth( engines, 100 );
		ship.SetSystemHealth( PD_PlayerShip.ShipSystem.Hull, 100 );

		controller.m_messages.Clear();

		ship.DamageSystem( engines, 1000 );

		var enginesShotDown = ( ship.GetSystemHealth( engines ) == 0 ) && ProbeIsInoperative( ship, engines );
		var enginesShotText = MessageList();

		ship.RestoreSystems();

		// ---- 6. the shield generator at 0 raises nothing
		ship.SetSystemHealth( PD_PlayerShip.ShipSystem.Shields, 0 );

		var shieldsText = PressAndRead( new RaiseShieldsButton() );
		var shieldsUp = ship.m_shieldsAreUp;

		ship.DropShields();
		ship.RestoreSystems();

		// ---- 7. the missile launcher at 0 is not armed, the lasers are
		ship.SetSystemHealth( PD_PlayerShip.ShipSystem.Missiles, 0 );

		var armText = PressAndRead( new ArmWeaponButton() );
		var armedAfter = ship.m_weaponsAreArmed;

		ship.m_weaponsAreArmed = false;
		ship.RestoreSystems();

		// ---- 8. the comm at 0 cannot answer a hail
		ship.SetSystemHealth( PD_PlayerShip.ShipSystem.Comm, 0 );

		var respondStarted = new RespondButton().Execute();
		var respondText = MessageList();

		controller.m_buttonController.ChangeButtonSet( ButtonController.ButtonSet.Bridge );

		var commBrokeDown = ProbeIsInoperative( ship, PD_PlayerShip.ShipSystem.Comm );

		// ---- 9. the damage report reads the breakdown, and a repair that makes the comm whole makes it work
		ship.SetSystemHealth( PD_PlayerShip.ShipSystem.Comm, 99 );

		var commItem = (int) PD_PlayerShip.ShipSystem.Comm + 1;
		var reportInoperative = !ship.IsRepairItemOperative( commItem );

		RepairOnePoint( ship, PD_PlayerShip.ShipSystem.Comm );

		var repairedWorks = ( ship.GetSystemHealth( PD_PlayerShip.ShipSystem.Comm ) == 100 ) && !ProbeIsInoperative( ship, PD_PlayerShip.ShipSystem.Comm ) && ship.IsRepairItemOperative( commItem );

		// ---- 10. past 73 each repaired point makes a broken system work with a chance of 1 in 5, and below it never
		var earlyHigh = 0;
		var earlyLow = 0;

		for ( var i = 0; i < 200; i++ )
		{
			ship.SetSystemHealth( sensors, 80 );
			ProbeSetInoperative( ship, sensors, true );
			RepairOnePoint( ship, sensors );

			if ( ProbeIsInoperative( ship, sensors ) == false )
			{
				earlyHigh++;
			}

			ship.SetSystemHealth( sensors, 50 );
			ProbeSetInoperative( ship, sensors, true );
			RepairOnePoint( ship, sensors );

			if ( ProbeIsInoperative( ship, sensors ) == false )
			{
				earlyLow++;
			}
		}

		ship.m_repairsAreUnderWay = false;

		// ---- 11. a breakdown is saved, and the Starport's repairs end it
		ship.SetSystemHealth( sensors, 60 );
		ProbeSetInoperative( ship, sensors, true );

		var copy = JsonUtility.FromJson<PD_PlayerShip>( JsonUtility.ToJson( ship ) );
		var savedBreakdown = ProbeIsInoperative( copy, sensors );

		ship.RestoreSystems();

		var starportFixes = !ProbeIsInoperative( ship, sensors );

		Log( "malfunctions: whole failures " + wholeFailures + " | sensors at 0 '" + sensorsAtZero + "' broke down " + sensorsBrokeDown + " | at 90 after '" + sensorsInoperative + "' | at 50: " + halfMalfunctions + " of 100 | maneuver " + maneuverFirstStarted + " '" + maneuverFirstText + "' then " + maneuverSecondStarted + " '" + maneuverSecondText + "' | engines shot " + enginesShotDown + " '" + enginesShotText + "' | shields '" + shieldsText + "' up " + shieldsUp + " | arm '" + armText + "' armed " + armedAfter + " | respond " + respondStarted + " '" + respondText + "' broke down " + commBrokeDown + " | report inoperative " + reportInoperative + ", repaired works " + repairedWorks + " | early at 80: " + earlyHigh + " of 200, at 50: " + earlyLow + " | saved " + savedBreakdown + ", Starport " + starportFixes );

		Check( "malfunctions: whole systems never malfunction (control)", wholeFailures == 0, wholeFailures + " failures in 20 rounds" );
		Check( "malfunctions: sensors at 0 malfunction, give no reading and break down (the code before refused them as too badly damaged)", sensorsAtZero.Contains( "Sensors: MALFUNCTION" ) && !sensorsAtZero.Contains( "Star System Scan" ) && sensorsBrokeDown, sensorsAtZero );
		Check( "malfunctions: sensors that have broken down say so with no roll, though now at 90", sensorsInoperative.Contains( "Sensors: inoperative." ) && !sensorsInoperative.Contains( "Star System Scan" ), sensorsInoperative );
		Check( "malfunctions: at half health the sensors malfunction about half the time", ( halfMalfunctions >= 30 ) && ( halfMalfunctions <= 70 ), halfMalfunctions + " of 100" );
		Check( "malfunctions: engines at 0 malfunction on Maneuver, which then says they are inoperative, and the ship does not maneuver", !maneuverFirstStarted && maneuverFirstText.Contains( "Engines: MALFUNCTION" ) && !maneuverSecondStarted && maneuverSecondText.Contains( "Engines: inoperative." ), maneuverFirstStarted + " " + maneuverFirstText + " | " + maneuverSecondStarted + " " + maneuverSecondText );
		Check( "malfunctions: engines shot down to nothing break down at once, with the malfunction's line", enginesShotDown && enginesShotText.Contains( "Engines: MALFUNCTION" ), enginesShotText );
		Check( "malfunctions: a shield generator at 0 malfunctions and the shields stay down", shieldsText.Contains( "Shields: MALFUNCTION" ) && !shieldsUp, shieldsText );
		Check( "malfunctions: a missile launcher at 0 malfunctions and only the lasers arm", armText.Contains( "Missiles: MALFUNCTION" ) && armText.Contains( "Arming lasers." ) && !armText.Contains( "Arming missiles." ) && armedAfter, armText );
		Check( "malfunctions: comm equipment at 0 malfunctions and cannot answer a hail", !respondStarted && respondText.Contains( "Communications: MALFUNCTION" ) && commBrokeDown, respondStarted + " " + respondText );
		Check( "malfunctions: the damage report says a broken down system is inoperative, and the repair that makes it whole makes it work", reportInoperative && repairedWorks, reportInoperative + " " + repairedWorks );
		Check( "malfunctions: past 73 a repaired point makes a broken system work about one time in 5, and below it never", ( earlyHigh >= 20 ) && ( earlyHigh <= 65 ) && ( earlyLow == 0 ), earlyHigh + " of 200 at 80, " + earlyLow + " at 50" );
		Check( "malfunctions: a breakdown is saved, and the Starport's repairs end it", savedBreakdown && starportFixes, savedBreakdown + " " + starportFixes );

		Finish( "scenario=malfunctions checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the ground tools' sounds (since 2026-10-18)

	// what the pool of SoundController's audio sources holds: one entry per source with a clip, "name[/loop][/fading][/playing]" (read by reflection, so
	// that the scenario also runs on the code before the new sounds)
	static List<string> PoolSounds()
	{
		var list = new List<string>();
		var controllers = ( SoundController.m_instance != null ) ? GetField( SoundController.m_instance, "m_audioSourceControllerList" ) as Array : null;

		if ( controllers == null )
		{
			return list;
		}

		foreach ( var controller in controllers )
		{
			var source = GetField( controller, "m_audioSource" ) as AudioSource;

			if ( ( source == null ) || ( source.clip == null ) )
			{
				continue;
			}

			list.Add( source.clip.name + ( source.loop ? "/loop" : "" ) + ( ( GetField( controller, "m_isFadingOut" ) is bool fading ) && fading ? "/fading" : "" ) + ( source.isPlaying ? "/playing" : "" ) );
		}

		return list;
	}

	// a source of the pool holds this clip, looping or not, and not fading out
	static bool PoolHolds( List<string> pool, string clipName, bool loop )
	{
		return pool.Exists( entry => entry.StartsWith( clipName + ( loop ? "/loop" : "" ) ) && ( loop || !entry.StartsWith( clipName + "/loop" ) ) && !entry.Contains( "/fading" ) );
	}

	// takes every clip out of the pool, so that what it holds next is what was played since
	static void ClearPool()
	{
		var controllers = ( SoundController.m_instance != null ) ? GetField( SoundController.m_instance, "m_audioSourceControllerList" ) as Array : null;

		if ( controllers == null )
		{
			return;
		}

		foreach ( var controller in controllers )
		{
			if ( GetField( controller, "m_audioSource" ) is AudioSource source )
			{
				source.Stop();
				source.clip = null;
			}

			SetField( controller, "m_isFadingOut", false );
		}
	}

	IEnumerator ScenarioGroundSounds()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();
		ProbeKeyboard();

		// ---- 1. the mining laser: its own beam while it cuts, and a crumble when the deposit is gone (planet 90, as mininglaser)
		yield return EnterOrbit( 90 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );

		PressButton( ButtonController.ButtonSet.CommandA, 1 );

		yield return WaitForLocation( PD_General.Location.Disembarked, 15.0f );
		yield return Frames( 10 );

		if ( playerData.m_general.m_location != PD_General.Location.Disembarked )
		{
			Finish( "scenario=groundsounds abort: never got into the terrain vehicle (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		if ( GetField( buttonController, "m_currentButton" ) != null )
		{
			buttonController.DeactivateButton();
		}

		var terrainVehicle = controller.m_terrainVehicle;
		var deposits = controller.m_disembarked.m_terrainGrid.m_terrainElements.transform.GetComponentsInChildren<TerrainElement>( true );

		foreach ( var other in deposits )
		{
			if ( Vector3.Distance( other.transform.position, terrainVehicle.transform.position ) < 100.0f )
			{
				other.transform.position += Vector3.right * 1000.0f;
			}
		}

		var deposit = ( deposits.Length > 0 ) ? deposits[ 0 ] : null;
		var whileMining = new List<string>();
		var afterMinedOut = new List<string>();
		var minedOut = false;

		if ( deposit != null )
		{
			// a small deposit, cut in about a second
			deposit.m_volume = 12;
			deposit.transform.position = BesideTheVehicle( terrainVehicle );

			yield return Frames( 3 );

			ClearPool();

			var toolLabels = ButtonSetLabels( ButtonController.ButtonSet.TerrainVehicleWeapon );
			var mineIndex = Array.IndexOf( toolLabels.Split( ',' ), "Mine" );

			if ( mineIndex >= 0 )
			{
				PressButton( ButtonController.ButtonSet.TerrainVehicleWeapon, mineIndex );

				for ( var end = Time.time + 0.4f; Time.time < end; )
				{
					yield return null;
				}

				whileMining = PoolSounds();

				for ( var end = Time.time + 6.0f; ( Time.time < end ) && !deposit.HasBeenPickedUp(); )
				{
					yield return null;
				}

				yield return Frames( 2 );

				minedOut = deposit.HasBeenPickedUp();
				afterMinedOut = PoolSounds();
			}
		}

		Log( "groundsounds: mining pool " + string.Join( ", ", whileMining ) + " | mined out " + minedOut + ", pool " + string.Join( ", ", afterMinedOut ) );

		var laserPlays = PoolHolds( whileMining, "Mining Laser", true ) && !PoolHolds( whileMining, "Scanner", true );
		var crumblePlays = minedOut && PoolHolds( afterMinedOut, "Deposit Crumble", false );
		var laserStops = minedOut && !PoolHolds( afterMinedOut, "Mining Laser", true );

		// ---- 2. the capture beam: its hum while it holds a stunned lifeform, stopped when the lifeform gets away (planet 92, as capture)
		yield return LandInTheArthSystemAt( 92, Vector3.zero, done );

		var firstPlace = ( LifeformsOnTheGround().Count > 0 ) ? LifeformsOnTheGround()[ 0 ].position : Vector3.zero;

		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 5 );
		yield return LandInTheArthSystemAt( 92, firstPlace + Vector3.forward * 10.0f, done );

		var all = LifeformsOnTheGround();
		var whileCapturing = new List<string>();
		var afterGotAway = new List<string>();

		if ( all.Count > 0 )
		{
			var vehicle = controller.m_terrainVehicle.transform.position;
			var target = all[ 0 ].GetComponent<TerrainLifeform>();

			for ( var i = 1; i < all.Count; i++ )
			{
				all[ i ].position = vehicle + Vector3.right * 600.0f + Vector3.forward * ( i * 10.0f );
			}

			target.transform.position = new Vector3( vehicle.x + 6.0f, target.transform.position.y, vehicle.z );
			target.m_status = TerrainLifeform.Status.Stunned;
			target.m_stuns = 0;

			yield return Frames( 2 );

			ClearPool();
			Press( "TVCaptureButton" );

			for ( var end = Time.time + 0.4f; Time.time < end; )
			{
				yield return null;
			}

			whileCapturing = PoolSounds();

			// it gets away
			target.transform.position = vehicle + Vector3.left * 600.0f;

			yield return Frames( 5 );

			afterGotAway = PoolSounds();
		}

		Log( "groundsounds: capturing pool " + string.Join( ", ", whileCapturing ) + " | after it got away " + string.Join( ", ", afterGotAway ) );

		var beamPlays = PoolHolds( whileCapturing, "Capture Beam", true );
		var beamStops = ( whileCapturing.Count > 0 ) && !PoolHolds( afterGotAway, "Capture Beam", true );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "groundsounds: the mining laser plays its own looping beam, not the scanner's sound", laserPlays, string.Join( ", ", whileMining ) );
		Check( "groundsounds: when the deposit is mined out it crumbles, and the beam stops", crumblePlays && laserStops, minedOut + " | " + string.Join( ", ", afterMinedOut ) );
		Check( "groundsounds: a capture plays the capture beam's looping hum, which stops when the lifeform gets away", beamPlays && beamStops, string.Join( ", ", whileCapturing ) + " | " + string.Join( ", ", afterGotAway ) );
		Check( "groundsounds: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=groundsounds checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	IEnumerator ScenarioArtifactHum()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// the artifact hum: on Earth at 11N x 104W beside the Hypercube's ruin, loud near it, fading with distance, silent far off, paused with the game
		yield return GoIntoOrbit( 0, 5 );

		playerData.m_general.m_selectedLatitude = -104.0f;
		playerData.m_general.m_selectedLongitude = 11.0f;

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );
		yield return DisembarkNow( done );

		var sitePosition = Tools.LatLongToWorldCoordinates( -104.0f, 11.0f );
		GameObject display = null;

		foreach ( var ruin in controller.m_disembarked.m_terrainGrid.m_terrainRuins.GetComponentsInChildren<TerrainRuin>( false ) )
		{
			var delta = ruin.transform.position - sitePosition;

			if ( ( Mathf.Abs( delta.x ) < 0.5f ) && ( Mathf.Abs( delta.z ) < 0.5f ) && ( ruin.m_artifactDisplays.Count > 0 ) )
			{
				display = ruin.m_artifactDisplays[ 0 ];
			}
		}

		var hum = ( display != null ) ? display.GetComponent<AudioSource>() : null;
		var humClip = ( ( hum != null ) && ( hum.clip != null ) ) ? hum.clip.name : "none";
		var humLoops = ( hum != null ) && hum.loop;
		var volumes = new float[ 3 ];
		var distances = new[] { 5.0f, 25.0f, 100.0f };
		var pausedHum = false;
		var pausedVolume = -1.0f;

		if ( display != null )
		{
			// the vehicle stands still, and is put down at each distance through its saved coordinates (local to its parent), which it follows every frame
			if ( GetField( controller.m_buttonController, "m_currentButton" ) != null )
			{
				controller.m_buttonController.DeactivateButton();
			}

			playerData.m_general.m_currentSpeed = 0.0f;

			var vehicleParent = controller.m_terrainVehicle.transform.parent;

			for ( var i = 0; i < distances.Length; i++ )
			{
				var place = display.transform.position + Vector3.back * distances[ i ];
				var local = ( vehicleParent != null ) ? vehicleParent.InverseTransformPoint( place ) : place;

				playerData.m_general.m_coordinates = new Vector3( local.x, playerData.m_general.m_coordinates.y, local.z );
				controller.m_terrainVehicle.transform.localPosition = playerData.m_general.m_coordinates;

				yield return Frames( 3 );

				volumes[ i ] = ( hum != null ) ? hum.volume : -1.0f;
			}

			// paused: the hum pauses, and it does not follow the vehicle
			controller.m_gameIsPaused = true;

			var place2 = display.transform.position + Vector3.back * 5.0f;
			var local2 = ( vehicleParent != null ) ? vehicleParent.InverseTransformPoint( place2 ) : place2;

			playerData.m_general.m_coordinates = new Vector3( local2.x, playerData.m_general.m_coordinates.y, local2.z );
			controller.m_terrainVehicle.transform.localPosition = playerData.m_general.m_coordinates;

			yield return Frames( 3 );

			var displayScript = display.GetComponent<ArtifactDisplay>();

			pausedHum = ( displayScript != null ) && ( FieldOrNull( displayScript, "m_humPaused" ) is bool paused ) && paused;
			pausedVolume = ( hum != null ) ? hum.volume : -1.0f;

			controller.m_gameIsPaused = false;

			yield return Frames( 2 );
		}

		Log( "artifacthum: artifact " + ( ( display != null ) ? display.name : "not found" ) + ", hum clip " + humClip + " (loop " + humLoops + ", playing " + ( ( hum != null ) && hum.isPlaying ) + "), volume at 5, 25 and 100 units " + volumes[ 0 ].ToString( "F2" ) + ", " + volumes[ 1 ].ToString( "F2" ) + ", " + volumes[ 2 ].ToString( "F2" ) + "; paused " + pausedHum + " (volume " + pausedVolume.ToString( "F2" ) + ")" );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "artifacthum: a floating artifact hums (its own looping clip)", ( humClip == "Artifact Hum" ) && humLoops, humClip + " " + humLoops );
		Check( "artifacthum: the hum is loud near the artifact, fades with distance and is silent far off", ( Mathf.Abs( volumes[ 0 ] - 0.5f ) < 0.01f ) && ( Mathf.Abs( volumes[ 1 ] - 0.25f ) < 0.02f ) && ( volumes[ 2 ] == 0.0f ), volumes[ 0 ].ToString( "F2" ) + " " + volumes[ 1 ].ToString( "F2" ) + " " + volumes[ 2 ].ToString( "F2" ) );
		Check( "artifacthum: the hum pauses with the game and does not follow the vehicle meanwhile", pausedHum && ( Mathf.Abs( pausedVolume ) < 0.001f ), pausedHum + " " + pausedVolume.ToString( "F2" ) );
		Check( "artifacthum: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=artifacthum checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the sounds that replaced the Star Trek clips (since 2026-10-18)

	IEnumerator ScenarioSoundClips()
	{
		var errorsBefore = s_errorCount;
		var soundController = SoundController.m_instance;

		yield return Frames( 5 );

		if ( soundController == null )
		{
			Finish( "scenario=soundclips abort: no SoundController", 2 );
			yield break;
		}

		// the fields that held a Star Trek clip, the clip each holds now, the Sound value the game plays it by and its length in seconds; the
		// space missile (Attribution NonCommercial) was never played and shares the new missile launch, and the aliens' energy weapon (no
		// traceable source) has its own
		var expected = new[]
		{
			new { field = "m_redAlert", clip = "Hull Alarm", sound = "RedAlert", seconds = 2.5f },
			new { field = "m_transporter", clip = "Cargo Transfer", sound = "Transporter", seconds = 3.0f },
			new { field = "m_commChirp", clip = "Comm Hail", sound = "CommChirp", seconds = 0.5f },
			new { field = "m_phaserFire", clip = "Laser Cannon", sound = "PhaserFire", seconds = 1.5f },
			new { field = "m_enterWarp", clip = "Flux Enter", sound = "EnterWarp", seconds = 2.0f },
			new { field = "m_exitWarp", clip = "Flux Exit", sound = "ExitWarp", seconds = 3.0f },
			new { field = "m_torpedoFire", clip = "Missile Launch", sound = "TorpedoFire", seconds = 1.5f },
			new { field = "m_missileLaunch", clip = "Missile Launch", sound = "MissileLaunch", seconds = 1.5f },
			new { field = "m_energyWeapon", clip = "Alien Laser", sound = "EnergyWeapon", seconds = 2.0f },
		};

		var soundList = GetField( soundController, "m_soundList" ) as AudioClip[];

		// ---- 1. each of those fields holds its new clip, the sound list the game plays from has it under the field's Sound value, and the clip is
		// as long as the file that was made for it
		foreach ( var entry in expected )
		{
			var clip = GetField( soundController, entry.field ) as AudioClip;
			var clipName = ( clip != null ) ? clip.name : "(none)";
			var length = ( clip != null ) ? clip.length : 0.0f;

			Check( "soundclips: " + entry.field + " holds " + entry.clip, clipName == entry.clip, clipName + ", " + length.ToString( "0.000" ) + " s" + ( ( clip != null ) ? ", " + clip.frequency + " Hz, " + clip.channels + " channel(s)" : "" ) );
			Check( "soundclips: " + entry.clip + " is " + entry.seconds + " s long", Mathf.Abs( length - entry.seconds ) < 0.02f, length.ToString( "0.000" ) + " s" );

			AudioClip listed = null;

			if ( ( soundList != null ) && Enum.IsDefined( typeof( SoundController.Sound ), entry.sound ) )
			{
				var index = (int) Enum.Parse( typeof( SoundController.Sound ), entry.sound );

				listed = ( index < soundList.Length ) ? soundList[ index ] : null;
			}

			Check( "soundclips: Sound." + entry.sound + " plays " + entry.clip, ( listed != null ) && ( listed.name == entry.clip ), ( listed != null ) ? listed.name : "(none)" );
		}

		// ---- 2. no clip of the SoundController is a Star Trek one, and every one of its clip fields holds a clip (none was left empty by the removal)
		var startrek = new List<string>();
		var empty = new List<string>();
		var count = 0;

		foreach ( var field in typeof( SoundController ).GetFields( BindingFlags.Public | BindingFlags.Instance ) )
		{
			if ( field.FieldType != typeof( AudioClip ) )
			{
				continue;
			}

			count++;

			var clip = field.GetValue( soundController ) as AudioClip;

			if ( clip == null )
			{
				empty.Add( field.Name );
			}
			else if ( clip.name.ToLowerInvariant().Contains( "tng" ) )
			{
				startrek.Add( field.Name + "=" + clip.name );
			}
		}

		Check( "soundclips: no SoundController clip has tng in its name", startrek.Count == 0, count + " clip fields; " + ( ( startrek.Count > 0 ) ? string.Join( ", ", startrek ) : "none" ) );
		Check( "soundclips: every SoundController clip field holds a clip", ( count > 0 ) && ( empty.Count == 0 ), count + " clip fields; empty: " + ( ( empty.Count > 0 ) ? string.Join( ", ", empty ) : "none" ) );

		// ---- 3. no audio file of the project is a Star Trek clip or one of the two removed for their licence (the space missile and the untraced energy
		// weapon)
		var leftOver = new List<string>();

		foreach ( var guid in AssetDatabase.FindAssets( "t:AudioClip", new[] { "Assets" } ) )
		{
			var path = AssetDatabase.GUIDToAssetPath( guid );
			var file = System.IO.Path.GetFileName( path ).ToLowerInvariant();

			if ( file.Contains( "tng" ) || file.Contains( "robinhood76" ) || file.Contains( "sci-fi_energy_weapon" ) )
			{
				leftOver.Add( path );
			}
		}

		Check( "soundclips: no Star Trek, Attribution NonCommercial or untraced clip is left in the project", leftOver.Count == 0, ( leftOver.Count > 0 ) ? string.Join( ", ", leftOver ) : "none" );

		// ---- 4. PlaySound puts each new clip on an audio source of the pool (the path every call site takes), read right after each play
		var notPlayed = new List<string>();

		ClearPool();

		foreach ( var entry in expected )
		{
			if ( !Enum.IsDefined( typeof( SoundController.Sound ), entry.sound ) )
			{
				notPlayed.Add( entry.sound + " (no such Sound)" );
				continue;
			}

			try
			{
				soundController.PlaySound( (SoundController.Sound) Enum.Parse( typeof( SoundController.Sound ), entry.sound ), 0.0f );
			}
			catch ( Exception exception )
			{
				notPlayed.Add( entry.sound + " (" + exception.GetType().Name + ")" );
				continue;
			}

			var pool = PoolSounds();

			if ( !pool.Exists( held => held.StartsWith( entry.clip ) ) )
			{
				notPlayed.Add( entry.sound + " -> " + string.Join( ", ", pool ) );
			}
		}

		ClearPool();

		Check( "soundclips: PlaySound plays each new clip", notPlayed.Count == 0, ( notPlayed.Count > 0 ) ? string.Join( "; ", notPlayed ) : "all " + expected.Length );

		yield return Frames( 3 );

		Check( "soundclips: no errors", s_errorCount == errorsBefore, ( s_errorCount - errorsBefore ) + " error(s)" );

		Finish( "scenario=soundclips checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the About screen and the intro's credits (since 2026-10-18)

	// the save panel has an About screen with the game's credits (the remake it is built on, its contributors, Starflight's makers and the licences of its sounds,
	// music and fonts), opened from its menu and closed with Done or Escape; the intro's third page credits the port (its name, its author's GitHub account) and
	// sends the rest to the About screen. The code before had no About screen, and the intro credited the 2017 remake project and BraveArmy.com
	IEnumerator ScenarioAboutScreen()
	{
		EnsureCrew();

		// ---- 1. the save panel's menu has an About button, which opens the screen
		PressEscape();

		yield return new WaitForSecondsRealtime( 1.5f );

		var panel = PanelController.m_instance.m_saveGamePanel;
		var aboutButton = FieldOrNull( panel, "m_aboutButton" ) as UnityEngine.UI.Button;
		var buttonShown = ( aboutButton != null ) && aboutButton.gameObject.activeInHierarchy && aboutButton.interactable;

		if ( aboutButton != null )
		{
			aboutButton.onClick.Invoke();
		}

		yield return Frames( 5 );

		var aboutPanel = FieldOrNull( panel, "m_aboutPanel" ) as GameObject;
		var aboutShown = ( aboutPanel != null ) && aboutPanel.activeInHierarchy;
		var aboutText = ( typeof( SaveGamePanel ).GetMethod( "GetAboutText" ) != null ) ? ( Call( panel, "GetAboutText" ) as string ) ?? "" : "";
		var folder = ScreenPictureFolder( "aboutscreen" );

		// a picture of it, in a run with a graphics device (probe.ps1 -Graphics)
		if ( folder != "" )
		{
			yield return new WaitForSecondsRealtime( 0.5f );

			RenderScreenPicture( System.IO.Path.Combine( folder, "01_about_screen.png" ) );
		}

		// ---- 2. Escape closes it, back to the menu
		SetInput( "m_cancel", true );

		Call( panel, "Tick" );

		SetInput( "m_cancel", false );

		yield return Frames( 3 );

		var closedByEscape = ( aboutPanel != null ) && !aboutPanel.activeInHierarchy && PanelController.m_instance.HasActivePanel();

		yield return CloseTheSavePanel();

		// ---- 3. the intro's third page credits the port
		SceneManager.LoadScene( "Intro" );

		yield return WaitForScene( "Intro" );
		yield return Frames( 5 );

		var introTexts = new List<string>();

		// (the Intro scene's own texts: the save panel lives on in the persistent scene, and its About screen names the remake's team)
		foreach ( var text in UnityEngine.Object.FindObjectsByType<TMPro.TMP_Text>( FindObjectsInactive.Include, FindObjectsSortMode.None ) )
		{
			if ( text.gameObject.scene.name == "Intro" )
			{
				introTexts.Add( text.text );
			}
		}

		var intro = string.Join( " | ", introTexts );

		// and of the intro's third page
		if ( folder != "" )
		{
			var introController = UnityEngine.Object.FindFirstObjectByType<IntroController>();

			if ( introController != null )
			{
				Time.timeScale = 0.0f;
				SetField( introController, "m_timer", 38.0f );

				yield return Frames( 5 );

				RenderScreenPicture( System.IO.Path.Combine( folder, "02_intro_page_3.png" ) );

				Time.timeScale = 1.0f;
			}
		}

		Log( "aboutscreen: button " + buttonShown + ", shown " + aboutShown + ", closed by Escape " + closedByEscape + " | about: '" + aboutText.Replace( "\n", " / " ) + "' | intro: '" + intro.Replace( "\n", " / " ) + "'" );

		Check( "aboutscreen: the save panel has an About button, which opens the About screen (the code before had none)", buttonShown && aboutShown, buttonShown + " " + aboutShown );
		Check( "aboutscreen: it credits the port's author and the remake it is built on, released into the public domain", aboutText.Contains( "cptjamestiberiouskirk-pixel" ) && aboutText.Contains( "Built on the Starflight Remake Project by Marvin Herbold, released into the public domain." ), aboutText );
		Check( "aboutscreen: it thanks the remake's contributors and names Starflight's makers and the music and sound effects made for this port", aboutText.Contains( "Jeff Graw" ) && aboutText.Contains( "Planet Map Project" ) && aboutText.Contains( "Binary Systems" ) && aboutText.Contains( "Music: made for this port." ) && !aboutText.Contains( "Tabletop Audio" ) && aboutText.Contains( "Sound effects: made for this port." ) && !aboutText.Contains( "bubaproducer" ), aboutText );
		Check( "aboutscreen: Escape closes it, back to the save panel's menu", closedByEscape, closedByEscape.ToString() );
		Check( "aboutscreen: the intro credits the port and its author's GitHub account, and no longer BraveArmy.com or the 2017 team", intro.Contains( "Starflight: The Remaking of a Legend" ) && intro.Contains( "github.com/cptjamestiberiouskirk-pixel" ) && !intro.Contains( "BraveArmy" ) && !intro.Contains( "Marvin" ), intro );
		Check( "aboutscreen: the original's credits stay on the intro (Binary Systems, Electronic Arts)", intro.Contains( "Binary Systems" ) && intro.Contains( "Electronic Arts" ), intro );

		Finish( "scenario=aboutscreen checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- the music made for this port (since 2026-10-18)

	// every MusicController track holds the track made for it, by name and length, streamed from disk; no Tabletop Audio file (under Attribution
	// NonCommercial NoDerivatives) is left on a MusicController field or in the project; and ChangeToTrack puts each track's clip on the music source,
	// looping all but the intro. The code before had the 15 Tabletop Audio ambiences, 8 of them played, each decompressed into memory when loaded
	IEnumerator ScenarioMusic()
	{
		var errorsBefore = s_errorCount;
		var musicController = MusicController.m_instance;

		yield return Frames( 5 );

		if ( musicController == null )
		{
			Finish( "scenario=music abort: no MusicController", 2 );
			yield break;
		}

		// each track's field, its new clip and that clip's length in seconds (a loop is its generated take less the 6 s crossfaded into its start)
		var expected = new[]
		{
			new { field = "m_intro", track = MusicController.Track.Intro, clip = "Title Theme", seconds = 40.05f },
			new { field = "m_starport", track = MusicController.Track.Starport, clip = "Starport Theme", seconds = 248.67f },
			new { field = "m_dockingBay", track = MusicController.Track.DockingBay, clip = "Docking Bay Theme", seconds = 108.41f },
			new { field = "m_starSystem", track = MusicController.Track.StarSystem, clip = "Star System Theme", seconds = 347.87f },
			new { field = "m_inOrbit", track = MusicController.Track.InOrbit, clip = "Orbit Theme", seconds = 246.95f },
			new { field = "m_hyperspace", track = MusicController.Track.Hyperspace, clip = "Hyperspace Theme", seconds = 335.69f },
			new { field = "m_encounter", track = MusicController.Track.Encounter, clip = "Encounter Theme", seconds = 228.81f },
			new { field = "m_planetside", track = MusicController.Track.Planetside, clip = "Planetside Theme", seconds = 342.96f },
		};

		var trackList = GetField( musicController, "m_trackList" ) as AudioClip[];

		// ---- 1. each field holds its new clip, as long as the file made for it, under its track in the list the controller plays from, and streamed
		foreach ( var entry in expected )
		{
			var clip = GetField( musicController, entry.field ) as AudioClip;
			var clipName = ( clip != null ) ? clip.name : "(none)";
			var length = ( clip != null ) ? clip.length : 0.0f;

			Check( "music: " + entry.field + " holds " + entry.clip, clipName == entry.clip, clipName + ", " + length.ToString( "0.000" ) + " s" + ( ( clip != null ) ? ", " + clip.frequency + " Hz, " + clip.channels + " channel(s), " + clip.loadType : "" ) );
			Check( "music: " + entry.clip + " is " + entry.seconds + " s long", Mathf.Abs( length - entry.seconds ) < 0.05f, length.ToString( "0.000" ) + " s" );
			Check( "music: " + entry.clip + " streams from disk", ( clip != null ) && ( clip.loadType == AudioClipLoadType.Streaming ), ( clip != null ) ? clip.loadType.ToString() : "(none)" );

			var index = (int) entry.track;
			var listed = ( ( trackList != null ) && ( index < trackList.Length ) ) ? trackList[ index ] : null;

			Check( "music: Track." + entry.track + " plays " + entry.clip, ( listed != null ) && ( listed.name == entry.clip ), ( listed != null ) ? listed.name : "(none)" );
		}

		// ---- 2. no MusicController clip is a Tabletop Audio file, every one is in Assets/Music, and no Tabletop Audio file is left in the project
		var tabletop = new[] { "103_testing_chamber", "106_lunar_outpost", "112_ethereal_plane", "113_astral_plane", "126_endless_voyage", "155_outpost_31", "16_busy_space_port", "17_alien_night_club", "21_derelict_freighter", "24_forbidden_galaxy", "25_deep_space_eva", "28_nephilim_labs_fe", "33_far_above_the_world", "93_starship_medical" };
		var onFields = new List<string>();
		var outside = new List<string>();

		foreach ( var field in typeof( MusicController ).GetFields( BindingFlags.Public | BindingFlags.Instance ) )
		{
			if ( field.FieldType != typeof( AudioClip ) )
			{
				continue;
			}

			var clip = field.GetValue( musicController ) as AudioClip;
			var path = ( clip != null ) ? AssetDatabase.GetAssetPath( clip ) : "";
			var file = System.IO.Path.GetFileNameWithoutExtension( path ).ToLowerInvariant();

			if ( ( Array.IndexOf( tabletop, file ) >= 0 ) || ( path == "Assets/Music/Intro.wav" ) )
			{
				onFields.Add( field.Name + "=" + path );
			}
			else if ( !path.StartsWith( "Assets/Music/" ) )
			{
				outside.Add( field.Name + "=" + path );
			}
		}

		Check( "music: no MusicController track is a Tabletop Audio file", onFields.Count == 0, ( onFields.Count > 0 ) ? string.Join( ", ", onFields ) : "none" );
		Check( "music: every MusicController track is a file in Assets/Music", outside.Count == 0, ( outside.Count > 0 ) ? string.Join( ", ", outside ) : "all" );

		var leftOver = new List<string>();

		foreach ( var guid in AssetDatabase.FindAssets( "t:AudioClip", new[] { "Assets" } ) )
		{
			var path = AssetDatabase.GUIDToAssetPath( guid );
			var file = System.IO.Path.GetFileNameWithoutExtension( path ).ToLowerInvariant();

			if ( ( Array.IndexOf( tabletop, file ) >= 0 ) || ( path == "Assets/Music/Intro.wav" ) )
			{
				leftOver.Add( path );
			}
		}

		Check( "music: no Tabletop Audio file is left in the project", leftOver.Count == 0, ( leftOver.Count > 0 ) ? leftOver.Count + ": " + string.Join( ", ", leftOver ) : "none" );

		// ---- 3. ChangeToTrack puts each track's clip on the music source: the loops looping, then, from silence as when the game starts, the intro once
		var audioSource = GetField( musicController, "m_audioSource" ) as AudioSource;
		var notPlayed = new List<string>();

		foreach ( var entry in expected )
		{
			if ( entry.track == MusicController.Track.Intro )
			{
				continue;
			}

			yield return WaitForMusicTransition( musicController );

			musicController.ChangeToTrack( entry.track );

			yield return WaitForMusicTransition( musicController );

			var held = ( ( audioSource != null ) && ( audioSource.clip != null ) ) ? audioSource.clip.name : "(none)";
			var loops = ( audioSource != null ) && audioSource.loop;

			if ( ( held != entry.clip ) || !loops )
			{
				notPlayed.Add( entry.track + " -> " + held + ( loops ? "" : " (not looping)" ) );
			}
		}

		yield return WaitForMusicTransition( musicController );

		musicController.ChangeToTrack( MusicController.Track.None );

		yield return WaitForMusicTransition( musicController );

		musicController.ChangeToTrack( MusicController.Track.Intro );

		yield return WaitForMusicTransition( musicController );

		var introHeld = ( ( audioSource != null ) && ( audioSource.clip != null ) ) ? audioSource.clip.name : "(none)";
		var introLoops = ( audioSource != null ) && audioSource.loop;

		if ( ( introHeld != "Title Theme" ) || introLoops )
		{
			notPlayed.Add( "Intro -> " + introHeld + ( introLoops ? " (looping)" : "" ) );
		}

		Check( "music: ChangeToTrack plays each new track, the loops looping and the intro once", notPlayed.Count == 0, ( notPlayed.Count > 0 ) ? string.Join( "; ", notPlayed ) : "all " + expected.Length );

		yield return Frames( 3 );

		Check( "music: no errors", s_errorCount == errorsBefore, ( s_errorCount - errorsBefore ) + " error(s)" + ( ( s_errorCount > errorsBefore ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=music checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// waits until the MusicController is not fading between tracks (it ignores a ChangeToTrack meanwhile), at most 10 s of real time: a fade takes
	// m_trackChangeTime (2 s) of game time, and headless frames are far shorter than a rendered game's
	static IEnumerator WaitForMusicTransition( MusicController musicController )
	{
		var until = Time.realtimeSinceStartup + 10.0f;

		while ( Time.realtimeSinceStartup < until )
		{
			var phase = GetField( musicController, "m_phase" );

			if ( ( phase == null ) || ( (MusicController.Phase) phase == MusicController.Phase.None ) )
			{
				yield break;
			}

			yield return null;
		}
	}

	// ---------------------------------------------------------------- phase 8: Disembark lowers the shields and disarms (roadmap 8.35)

	IEnumerator ScenarioDisembarkShields()
	{
		var playerData = DataController.m_instance.m_playerData;
		var controller = SpaceflightController.m_instance;
		var ship = playerData.m_playerShip;
		var errorsBefore = s_errorCount;

		EnsureCrew();

		// on the ground of planet 94 of Arth, in the ship, with the shields up and the weapons armed (the original's Disembark runs WEDEC first: SHIPBUTTONS WF095)
		yield return GoIntoOrbit( 25, 94 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );

		ship.m_shieldingClass = Mathf.Max( ship.m_shieldingClass, 1 );
		ship.m_shieldPoints = ship.GetMaximumShieldPoints();
		ship.m_shieldsAreUp = true;
		ship.m_weaponsAreArmed = true;

		var chargeBefore = ship.m_shieldPoints;

		controller.m_messages.Clear();

		// the real Disembark button (the second of the command set on a planet), every line in the order it first came up, until the terrain vehicle is out
		PressButton( ButtonController.ButtonSet.CommandA, 1 );

		var lines = new List<string>();
		var end = Time.realtimeSinceStartup + 15.0f;

		while ( Time.realtimeSinceStartup < end )
		{
			foreach ( var message in playerData.m_general.m_messageList )
			{
				var line = System.Text.RegularExpressions.Regex.Replace( message, "<[^>]*>", "" );

				if ( !lines.Contains( line ) )
				{
					lines.Add( line );
				}
			}

			if ( playerData.m_general.m_location == PD_General.Location.Disembarked )
			{
				break;
			}

			yield return null;
		}

		var said = string.Join( " | ", lines );
		var isOut = playerData.m_general.m_location == PD_General.Location.Disembarked;

		Log( "disembarkshields: (" + playerData.m_general.m_location + ") shields up " + ship.m_shieldsAreUp + ", weapons armed " + ship.m_weaponsAreArmed + ", charge " + chargeBefore + " -> " + ship.m_shieldPoints + "; " + said );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "disembarkshields: Disembark lowers the shields and disarms the weapons, saying so before Standby", isOut && !ship.m_shieldsAreUp && !ship.m_weaponsAreArmed && said.StartsWith( "Shields are down. | Weapons are disarmed. | Standby...scanning planet." ), ship.m_shieldsAreUp + " " + ship.m_weaponsAreArmed + " | " + said );
		Check( "disembarkshields: the lowered shields keep their charge", ship.m_shieldPoints == chargeBefore, chargeBefore + " -> " + ship.m_shieldPoints );
		Check( "disembarkshields: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=disembarkshields checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- phase 8: the Crystal Orb goes back to its site (since 2026-10-18)

	// the index of the recovered data's artifact site of this artifact (-1 if there is none)
	static int ArtifactSiteOf( string artifactName )
	{
		var gameData = DataController.m_instance.m_gameData;
		var artifactId = gameData.FindArtifactId( artifactName );

		for ( var siteId = 0; siteId < gameData.m_artifactSiteList.Length; siteId++ )
		{
			if ( gameData.m_artifactSiteList[ siteId ].m_artifactId == artifactId )
			{
				return siteId;
			}
		}

		return -1;
	}

	// the Crystal Orb the Veloxi take goes back to its site (COMMSPEC-OV -ARTIFACT, WEB3F), unless its planet has been destroyed (?SPHEXI); the Ellipsoid they take
	// is gone. The code before kept the orb's site empty for good, and a game could no longer be won
	IEnumerator ScenarioOrbReturns()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var controller = SpaceflightController.m_instance;
		var surfaces = playerData.m_planetSurfaces;

		EnsureCrew();

		// an officer who understands every word, and a ship that survives an attack
		playerData.m_crewAssignment.GetPersonnelFile( PD_CrewAssignment.Role.CommunicationsOfficer ).m_communications = 250;
		playerData.m_playerShip.m_armorPoints = 100000;

		controller.m_encounterRange = 0.0f;

		var veloxId = FindEncounter( 1, 6, 3, 0, GameData.Race.Velox );
		var orbSite = ArtifactSiteOf( "Crystal Orb" );
		var ellipsoidSite = ArtifactSiteOf( "Ellipsoid" );
		var orbPlanet = ( orbSite >= 0 ) ? gameData.m_artifactSiteList[ orbSite ].m_planetId : -1;

		// ---- 1. the orb taken from its site, then handed to the Veloxi: it is back at its site
		surfaces.TakeArtifactSite( orbSite );

		var takenBefore = surfaces.IsArtifactSiteTaken( orbSite );
		var handover = new List<string>();

		yield return AnswerTheVeloxi( veloxId, 50, "Crystal Orb", new AnswerYesButton(), handover );

		var backAtSite = !surfaces.IsArtifactSiteTaken( orbSite );

		// ---- 2. the Ellipsoid handed over stays gone (the control)
		var ellipsoidReturned = false;

		if ( ellipsoidSite >= 0 )
		{
			surfaces.TakeArtifactSite( ellipsoidSite );

			var ellipsoid = new List<string>();

			yield return AnswerTheVeloxi( veloxId, 50, "Ellipsoid", new AnswerYesButton(), ellipsoid );

			ellipsoidReturned = !surfaces.IsArtifactSiteTaken( ellipsoidSite );
		}

		// ---- 3. with the orb's planet destroyed, the orb handed over is gone
		surfaces.TakeArtifactSite( orbSite );
		surfaces.DestroyPlanet( orbPlanet );

		var destroyedHandover = new List<string>();

		yield return AnswerTheVeloxi( veloxId, 50, "Crystal Orb", new AnswerYesButton(), destroyedHandover );

		var backOnDestroyedPlanet = !surfaces.IsArtifactSiteTaken( orbSite );

		Log( "orbreturns: orb site " + orbSite + " on planet " + orbPlanet + " taken before " + takenBefore + " | handover [" + string.Join( " | ", handover ) + "] back " + backAtSite + " | ellipsoid site " + ellipsoidSite + " returned " + ellipsoidReturned + " | destroyed planet: back " + backOnDestroyedPlanet );

		Check( "orbreturns: the orb's site is known and taken before the handover (control)", ( orbSite >= 0 ) && ( orbPlanet >= 0 ) && takenBefore, orbSite + " " + orbPlanet + " " + takenBefore );
		Check( "orbreturns: the Veloxi take the orb, and it is back at its site (the code before kept the site empty)", ( handover.Count > 3 ) && ( handover[ 3 ] == "gone" ) && backAtSite, string.Join( " | ", handover ) + " | back " + backAtSite );
		Check( "orbreturns: the Ellipsoid they take does not come back (control)", ( ellipsoidSite < 0 ) || !ellipsoidReturned, ellipsoidSite + " " + ellipsoidReturned );
		Check( "orbreturns: with the orb's planet destroyed, the orb they take is gone", ( destroyedHandover.Count > 3 ) && ( destroyedHandover[ 3 ] == "gone" ) && !backOnDestroyedPlanet, string.Join( " | ", destroyedHandover ) + " | back " + backOnDestroyedPlanet );

		Finish( "scenario=orbreturns checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}
	// ---------------------------------------------------------------- phase 8: the Black Egg is armed only if the crew says so (roadmap 8.31)

	// the Black Eggs lying on a planet
	static int EggsLyingOn( int planetId, int blackEggId )
	{
		var count = 0;

		foreach ( var droppedCargo in DataController.m_instance.m_playerData.m_planetSurfaces.m_droppedCargoList )
		{
			if ( ( droppedCargo.m_planetId == planetId ) && ( droppedCargo.m_artifactId == blackEggId ) )
			{
				count++;
			}
		}

		return count;
	}

	IEnumerator ScenarioEggArming()
	{
		var dataController = DataController.m_instance;
		var playerData = dataController.m_playerData;
		var gameData = dataController.m_gameData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;
		var blackEggId = gameData.FindArtifactId( "Black Egg" );
		var starId = gameData.m_planetList[ 90 ].m_starId;
		var errorsBefore = s_errorCount;
		var done = new bool[ 1 ];

		EnsureCrew();

		// out on planet 90 with a Black Egg in the terrain vehicle, nothing else within reach
		yield return GoIntoOrbit( starId, 90 );

		controller.m_planetside.UpdateTerrainGridNow();
		controller.SwitchLocation( PD_General.Location.Planetside );

		yield return Frames( 10 );
		yield return DisembarkNow( done );

		if ( !done[ 0 ] )
		{
			Finish( "scenario=eggarming abort: never got into the terrain vehicle (" + playerData.m_general.m_location + ")", 2 );
			yield break;
		}

		var terrainVehicle = controller.m_terrainVehicle;

		foreach ( var deposit in controller.m_disembarked.m_terrainGrid.m_terrainElements.transform.GetComponentsInChildren<TerrainElement>( true ) )
		{
			if ( Vector3.Distance( deposit.transform.position, terrainVehicle.transform.position ) < 50.0f )
			{
				deposit.transform.position += Vector3.right * 1000.0f;
			}
		}

		playerData.m_terrainVehicle.AddArtifact( blackEggId );

		var cargoListSet = CargoListButtonSet();

		// ---- 1. the cargo list drops it: the original asks "ARM THIS DEVICE? NO [  ] YES" (ITEMS-OV WE9AA)
		controller.m_messages.Clear();

		new TVCargoButton().Execute();

		yield return Frames( 2 );

		if ( cargoListSet >= 0 )
		{
			PressButton( (ButtonController.ButtonSet) cargoListSet, 1 );

			yield return Frames( 2 );
		}

		var askText = MessageList();
		var askLabels = ButtonSetLabels( buttonController.GetCurrentButtonSet() );
		var asked = askText.Contains( "Arm this device?" ) && ( PtIndexOf( "No" ) >= 0 ) && ( PtIndexOf( "Yes" ) >= 0 );
		var eggsAfterDrop = EggsLyingOn( 90, blackEggId );
		var armedBeforeAnswer = BlackEgg.IsArmedEggInStarSystem( starId );

		// ---- 2. No: the egg lies there unarmed
		var answeredNo = false;

		if ( PtIndexOf( "No" ) >= 0 )
		{
			PressButtonLabelled( buttonController.GetCurrentButtonSet(), "No" );

			answeredNo = true;

			yield return Frames( 2 );
		}

		var armedAfterNo = BlackEgg.IsArmedEggInStarSystem( starId );
		var eggsAfterNo = EggsLyingOn( 90, blackEggId );

		// ---- 3. Cargo picks the unarmed egg up again: nothing to disarm
		controller.m_messages.Clear();

		new TVCargoButton().Execute();

		yield return Frames( 2 );

		var pickupUnarmedText = MessageList();

		// ---- 4. dropped again, and Yes: it is armed
		controller.m_messages.Clear();

		new TVCargoButton().Execute();

		yield return Frames( 2 );

		if ( cargoListSet >= 0 )
		{
			PressButton( (ButtonController.ButtonSet) cargoListSet, 1 );

			yield return Frames( 2 );
		}

		if ( PtIndexOf( "Yes" ) >= 0 )
		{
			PressButtonLabelled( buttonController.GetCurrentButtonSet(), "Yes" );

			yield return Frames( 2 );
		}

		var yesText = MessageList();
		var armedAfterYes = BlackEgg.IsArmedEggInStarSystem( starId );

		// ---- 5. Cargo picks the armed egg up: "DISARMING DEVICE" (ITEMS-OV WE9FA), and it is no longer armed
		controller.m_messages.Clear();

		new TVCargoButton().Execute();

		yield return Frames( 2 );

		var pickupArmedText = MessageList();
		var armedAfterPickup = BlackEgg.IsArmedEggInStarSystem( starId );

		Log( "eggarming: drop: '" + askText + "' [" + askLabels + "], eggs " + eggsAfterDrop + ", armed " + armedBeforeAnswer + " | No " + answeredNo + ": armed " + armedAfterNo + ", eggs " + eggsAfterNo + " | pickup: '" + pickupUnarmedText + "' | Yes: '" + yesText + "', armed " + armedAfterYes + " | pickup: '" + pickupArmedText + "', armed " + armedAfterPickup );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "eggarming: dropping the Black Egg asks Arm this device? with No and Yes, and it is not armed before the answer", asked && ( eggsAfterDrop == 1 ) && !armedBeforeAnswer, askText + " [" + askLabels + "] eggs " + eggsAfterDrop + ", armed " + armedBeforeAnswer );
		Check( "eggarming: No leaves the egg lying there unarmed", answeredNo && !armedAfterNo && ( eggsAfterNo == 1 ), answeredNo + " " + armedAfterNo + " " + eggsAfterNo );
		Check( "eggarming: Yes arms it, and the messages say so", armedAfterYes && yesText.Contains( "The Black Egg is armed." ), armedAfterYes + " | " + yesText );
		Check( "eggarming: picking up the armed egg says Disarming device. and disarms it, picking up an unarmed one does not", pickupArmedText.Contains( "Disarming device." ) && !pickupUnarmedText.Contains( "Disarming device." ) && !armedAfterPickup, pickupArmedText + " | " + pickupUnarmedText + " | " + armedAfterPickup );
		Check( "eggarming: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=eggarming checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- phase 8: the ship's cargo list describes an artifact or a specimen (roadmap 8.33)

	// presses the console button with this label if the console has one (the buttons of the ship's cargo list exist only in the new code) - returns whether it did
	static bool PressIfThere( string label )
	{
		if ( PtIndexOf( label ) < 0 )
		{
			return false;
		}

		PressButtonLabelled( SpaceflightController.m_instance.m_buttonController.GetCurrentButtonSet(), label );

		return true;
	}

	IEnumerator ScenarioCargoDescribe()
	{
		var playerData = DataController.m_instance.m_playerData;
		var gameData = DataController.m_instance.m_gameData;
		var controller = SpaceflightController.m_instance;
		var buttonController = controller.m_buttonController;
		var ship = playerData.m_playerShip;
		var errorsBefore = s_errorCount;

		EnsureCrew();

		yield return Frames( 5 );

		// the hold: Endurium, the Bladed Toy (its kind analysed) and the Blue Bauble (not), a specimen from a save before the capture place and one captured at 12N
		// x 34W - so the list runs Endurium, Blue Bauble, Bladed Toy, the captured specimen, the older one (each kind the one put in last first)
		var enduriumId = gameData.m_misc.m_enduriumElementId;
		var knownId = Array.FindIndex( gameData.m_artifactList, artifact => artifact.m_name == "Bladed Toy" );
		var unknownId = Array.FindIndex( gameData.m_artifactList, artifact => artifact.m_name == "Blue Bauble" );

		if ( ( enduriumId < 0 ) || ( knownId < 0 ) || ( unknownId < 0 ) )
		{
			Finish( "scenario=cargodescribe abort: missing game data (" + enduriumId + " " + knownId + " " + unknownId + ")", 2 );
			yield break;
		}

		if ( !playerData.m_knownArtifacts.IsKnown( knownId ) )
		{
			playerData.m_knownArtifacts.Add( knownId );
		}

		for ( var attempt = 0; ( attempt < 10 ) && playerData.m_knownArtifacts.IsKnown( unknownId ); attempt++ )
		{
			playerData.m_knownArtifacts.Remove( unknownId );
		}

		ship.m_elementStorage.Reset();
		ship.m_artifactStorage.Reset();
		ship.GetSpecimenStorage().m_specimenList.Clear();

		ship.m_elementStorage.Add( enduriumId, 200 );
		ship.m_artifactStorage.Add( knownId );
		ship.m_artifactStorage.Add( unknownId );

		var olderSpecimen = new PD_Specimen { m_planetId = 90, m_speciesIndex = 0, m_name = "Older Specimen", m_volume = 20, m_value = 400 };
		var capturedSpecimen = new PD_Specimen { m_planetId = 90, m_speciesIndex = 1, m_name = "Captured Specimen", m_volume = 15, m_value = 300 };

		// (set by name, so that this runs on the code before the capture place too)
		SetFieldIfThere( capturedSpecimen, "m_hasCapturePlace", true );
		SetFieldIfThere( capturedSpecimen, "m_capturedNorthSouth", 12 );
		SetFieldIfThere( capturedSpecimen, "m_capturedEastWest", -34 );
		SetFieldIfThere( capturedSpecimen, "m_capturedStardateYMD", "4620-03-26" );

		ship.GetSpecimenStorage().Add( olderSpecimen );
		ship.GetSpecimenStorage().Add( capturedSpecimen );

		// ---- 1. Cargo opens the list with its first item marked, and the console's buttons for it
		PressButtonLabelled( ButtonController.ButtonSet.CommandB, "Cargo" );

		yield return Frames( 5 );

		var labels = ButtonSetLabels( buttonController.GetCurrentButtonSet() );
		var columns = ShipCargoTableColumns();
		var itemLines = ( columns.Length > 0 ) ? columns[ 0 ].Split( '\n' ) : new string[ 0 ];
		var firstItemMarked = Array.FindIndex( itemLines, line => line.Contains( "> " ) ) == Array.FindIndex( itemLines, line => line.Contains( gameData.m_elementList[ enduriumId ].m_name ) );
		var opened = labels.Contains( "Next" ) && labels.Contains( "Describe" ) && labels.Contains( "Back" ) && ( itemLines.Length > 0 ) && firstItemMarked && string.Join( "", itemLines ).Contains( "> " );

		// ---- 2. Describe on each item in turn: Endurium (nothing), the Blue Bauble, the Bladed Toy, the captured specimen, the older one
		var described = new List<string>();

		for ( var item = 0; item < 5; item++ )
		{
			if ( item > 0 )
			{
				PressIfThere( "Next" );

				yield return Frames( 2 );
			}

			controller.m_messages.Clear();

			var pressed = PressIfThere( "Describe" );

			yield return Frames( 2 );

			described.Add( pressed ? MessageList() : "(no Describe)" );
		}

		// ---- 3. Back: the command buttons again
		PressIfThere( "Back" );

		yield return Frames( 2 );

		var setAfterBack = buttonController.GetCurrentButtonSet();
		var planet = gameData.m_planetList[ 90 ];
		var star = gameData.m_starList[ planet.m_starId ];
		var systemLine = "System " + star.m_xCoordinate + "," + star.m_yCoordinate;
		var planetLine = "Planet " + planet.m_orbitPosition;
		var knownText = gameData.m_artifactList[ knownId ].m_analysisText;
		var knownStart = knownText.Substring( 0, Mathf.Min( 24, knownText.Length ) );

		Log( "cargodescribe: console [" + labels + "], first item marked " + firstItemMarked + ", list '" + string.Join( "/", itemLines ) + "'" );

		for ( var i = 0; i < described.Count; i++ )
		{
			Log( "cargodescribe: Describe on item " + i + ": '" + described[ i ] + "'" );
		}

		Log( "cargodescribe: after Back the console is " + setAfterBack );

		var errorsDuring = s_errorCount - errorsBefore;

		Check( "cargodescribe: the ship's Cargo opens the list with Next, Describe and Back, its first item marked", opened, "[" + labels + "] " + firstItemMarked + " | " + string.Join( "/", itemLines ) );
		Check( "cargodescribe: an element has no description", ( described[ 0 ] != "(no Describe)" ) && !described[ 0 ].Contains( "analyzed" ) && !described[ 0 ].Contains( "System" ), described[ 0 ] );
		Check( "cargodescribe: an artifact of a kind not analysed: This artifact has not been analyzed.", described[ 1 ].Contains( gameData.m_artifactList[ unknownId ].m_name ) && described[ 1 ].Contains( "This artifact has not been analyzed." ), described[ 1 ] );
		Check( "cargodescribe: an artifact of an analysed kind: its analysis", described[ 2 ].Contains( gameData.m_artifactList[ knownId ].m_name ) && described[ 2 ].Contains( knownStart ), described[ 2 ] );
		Check( "cargodescribe: a captured specimen: its system, planet, location and date", described[ 3 ].Contains( "Captured Specimen" ) && described[ 3 ].Contains( systemLine ) && described[ 3 ].Contains( planetLine ) && described[ 3 ].Contains( "Location 12N x 34W" ) && described[ 3 ].Contains( "Date " + PD_General.GetDisplayStardate( "4620-03-26" ) ), described[ 3 ] );
		Check( "cargodescribe: a specimen from an older save: its system and planet only", described[ 4 ].Contains( "Older Specimen" ) && described[ 4 ].Contains( systemLine ) && !described[ 4 ].Contains( "Location" ), described[ 4 ] );
		Check( "cargodescribe: Back closes the list, back to the command buttons", setAfterBack == ButtonController.ButtonSet.CommandB, setAfterBack.ToString() );
		Check( "cargodescribe: no error is logged", errorsDuring == 0, errorsDuring + " errors" + ( ( errorsDuring > 0 ) ? ", the last: " + s_lastError : "" ) );

		Finish( "scenario=cargodescribe checks=" + s_checksPassed + "/" + ( s_checksPassed + s_checksFailed ), 0 );
	}

	// ---------------------------------------------------------------- every sound effect made for the port (since 2026-10-19)

	IEnumerator ScenarioSoundEffects()
	{
		var errorsBefore = s_errorCount;
		var soundController = SoundController.m_instance;

		yield return Frames( 5 );

		if ( soundController == null )
		{
			Finish( "scenario=soundeffects abort: no SoundController", 2 );
			yield break;
		}

		// every clip field of the SoundController, the Sound value the game plays it by, the clip made for the port that it holds, and that file's
		// length in seconds and sample rate (every clip it replaced was two channels or another length, an MP3 or a freesound download)
		var expected = new[]
		{
			new { field = "m_activate", sound = "Activate", clip = "Activate", seconds = 0.495f, rate = 48000 },
			new { field = "m_alarm", sound = "Alarm", clip = "Alarm", seconds = 2.000f, rate = 48000 },
